    -- Filtre anti-spam : textes longs
    ["Hide (and optionally ignore) chat spammers whose names spell 'casino' & co. with look-alike letters."] = "Masque (et au besoin ignore) les spammeurs dont le nom écrit « casino » et compagnie avec des lettres sosies.",
    ["|cffaaaaaaHides chat from gold/casino spammers whose names use look-alike letters (e.g. Gãsïnô, Casinòbâbe). The name is folded to plain letters, then matched against the keywords below. Applies to whisper, channels, say, yell and emotes — not guild/party/raid.|r"] = "|cffaaaaaaMasque les messages des vendeurs d'or et des casinos dont le nom utilise des lettres sosies (p. ex. Gãsïnô, Casinòbâbe). Le nom est ramené à des lettres simples, puis comparé aux mots-clés ci-dessous. S'applique aux chuchotements, canaux, dire, crier et emotes — pas à la guilde, au groupe ni au raid.|r",
    ["Adds matched senders to /ignore too. The ignore list holds only ~50 names and spammers keep changing names, so hiding is usually enough — leave this off unless you want it."] = "Ajoute aussi les expéditeurs détectés à /ignore. La liste noire ne retient qu'une cinquantaine de noms et les spammeurs en changent sans cesse : masquer suffit généralement — laissez cette option désactivée sauf besoin précis.",
    ["Also checks the message body for the keywords, not just the sender's name. Catches more spam but can have false positives."] = "Analyse aussi le corps du message, pas seulement le nom de l'expéditeur. Attrape davantage de spam, mais peut produire des faux positifs.",
    ["|cffaaaaaaBuilt-in: casino / asino / gasino / kasino. Add your own below, comma-separated (look-alike letters are handled automatically).|r"] = "|cffaaaaaaIntégrés : casino / asino / gasino / kasino. Ajoutez les vôtres ci-dessous, séparés par des virgules (les lettres sosies sont gérées automatiquement).|r",
    ["Hides any message containing a web link (http://, www., domain.tld) in the filtered channels. Whitelisted names are exempt. Opt-in — can catch the occasional legit link."] = "Masque tout message contenant un lien (http://, www., domaine.tld) dans les canaux filtrés. Les noms en liste blanche sont épargnés. Optionnel — peut attraper un lien légitime de temps à autre.",
    ["|cffaaaaaaNames here are never filtered. Comma-separated, or use |r|cff9b6cff/vcui spam <name>|r|cffaaaaaa to toggle one.|r"] = "|cffaaaaaaLes noms indiqués ici ne sont jamais filtrés. Séparez-les par des virgules, ou utilisez |r|cff9b6cff/vcui spam <nom>|r|cffaaaaaa pour en basculer un.|r",
    ["Spam filter: '%s' removed from the whitelist."] = "Filtre anti-spam : « %s » retiré de la liste blanche.",
    ["Spam filter: '%s' added to the whitelist (never filtered)."] = "Filtre anti-spam : « %s » ajouté à la liste blanche (jamais filtré).",

    -- Journal de quêtes : textes longs
    ["Enhances the quest log: quest levels (and optional quest IDs) in the titles, a larger frame, and a Parchment or Dark theme."] = "Améliore le journal de quêtes : niveau des quêtes (et identifiants en option) dans les titres, fenêtre agrandie, et thème Parchemin ou Sombre.",
    ["|cffaaaaaaShows quest levels (and optionally IDs) in the quest log, can enlarge it, and lets you pick a Parchment or Dark look.|r"] = "|cffaaaaaaAffiche le niveau des quêtes (et au besoin les identifiants) dans le journal, permet de l'agrandir et de choisir un aspect Parchemin ou Sombre.|r",
    ["Enlarges the quest log so more quests are visible with the detail pane beside the list. /reload to fully apply or revert."] = "Agrandit le journal de quêtes pour voir plus de quêtes, avec le volet de détail à côté de la liste. /reload pour appliquer ou annuler complètement.",
    ["Quest log size changed. /reload recommended."] = "Taille du journal de quêtes modifiée. /reload recommandé.",

    -- Fenêtre de métier : textes longs
    ["Enlarges and themes the profession windows (Tradeskill & Craft) to match the quest log: the detail pane sits beside the recipe list, with a Parchment or Dark theme."] = "Agrandit et habille les fenêtres de métier (Artisanat et Création) comme le journal de quêtes : le volet de détail se place à côté de la liste des recettes, avec un thème Parchemin ou Sombre.",
    ["|cffaaaaaaEnlarges the Tradeskill and Craft windows so the detail sits beside the recipe list, with a Parchment or Dark look.|r"] = "|cffaaaaaaAgrandit les fenêtres d'Artisanat et de Création pour placer le détail à côté de la liste des recettes, avec un aspect Parchemin ou Sombre.|r",
    ["Enlarges the profession windows so more recipes are visible with the detail pane beside the list. /reload to fully apply or revert."] = "Agrandit les fenêtres de métier pour voir plus de recettes, avec le volet de détail à côté de la liste. /reload pour appliquer ou annuler complètement.",
    ["Profession window size changed. /reload recommended."] = "Taille de la fenêtre de métier modifiée. /reload recommandé.",
    ["Shows how many of each recipe you can make right now, like [12]."] = "Indique combien d'exemplaires de chaque recette vous pouvez faire immédiatement, sous la forme [12].",
    ["On the selected recipe, shows how many you can craft counting your bank mats too, and lists what's still missing. Bank mats are remembered from your last visit to the bank."] = "Sur la recette sélectionnée, indique combien vous pouvez fabriquer en comptant aussi les composants en banque, et liste ce qui manque encore. Les composants en banque sont mémorisés depuis votre dernière visite.",
    ["|cff888888Click a recipe's star (or right-click the recipe) to favourite it — the star turns gold.|r"] = "|cff888888Cliquez sur l'étoile d'une recette (ou faites un clic droit dessus) pour la mettre en favori — l'étoile devient dorée.|r",
    ["Recipes you marked with the star float to the top of the list."] = "Les recettes marquées d'une étoile remontent en haut de la liste.",
    ["On the selected recipe, shows the crafted item's auction value, material cost and profit, using Auctionator's price data."] = "Sur la recette sélectionnée, affiche la valeur à l'hôtel des ventes de l'objet fabriqué, le coût des composants et le bénéfice, d'après les données de prix d'Auctionator.",
    ["|cff1eff00Auctionator found — prices from its data.|r"] = "|cff1eff00Auctionator détecté — prix issus de ses données.|r",
    ["|cffff5555Auctionator not found. Install Auctionator to get price data.|r"] = "|cffff5555Auctionator introuvable. Installez Auctionator pour obtenir les prix.|r",
    ["|cffaaaaaaThree buttons under the recipe list toggle extra info on the selected recipe: source (where to learn/get it), skill levels (orange/yellow/green/grey) and your skill-up chance.|r"] = "|cffaaaaaaTrois boutons sous la liste des recettes affichent des infos supplémentaires sur la recette sélectionnée : la source (où l'apprendre ou l'obtenir), les paliers de compétence (orange/jaune/vert/gris) et vos chances de gain de compétence.|r",
    ["|cff1eff00CraftLib found — recipe source & levels available.|r"] = "|cff1eff00CraftLib détecté — source et paliers des recettes disponibles.|r",
    ["|cffff5555CraftLib not found. Install CraftLib to show recipe source & levels.|r"] = "|cffff5555CraftLib introuvable. Installez CraftLib pour afficher la source et les paliers des recettes.|r",

    -- Correctifs : textes longs
    ["Re-adds the missing BIND_SOCKET confirmation dialog so socketing a gem that binds the item no longer throws a Lua error (Anniversary client)."] = "Rétablit la fenêtre de confirmation BIND_SOCKET manquante : sertir une gemme qui lie l'objet ne provoque plus d'erreur Lua (client Anniversaire).",
    ["Socketing this gem will bind the item to you. Continue?"] = "Sertir cette gemme liera l'objet à vous. Continuer ?",
    ["The Anniversary client is missing the |cffffffffBIND_SOCKET|r confirmation dialog. Socketing a gem that would bind the item then throws \"Dialog BIND_SOCKET does not exist\" and aborts. This re-adds the dialog so socketing works."] = "Le client Anniversaire ne possède pas la fenêtre de confirmation |cffffffffBIND_SOCKET|r. Sertir une gemme qui lierait l'objet déclenche alors « Dialog BIND_SOCKET does not exist » et l'opération échoue. Ce correctif rétablit la fenêtre pour que le sertissage fonctionne.",
    ["Stops the Lua error that fires every time a nameplate appears (Blizzard's nameplate code calls a specialization API this client does not support)."] = "Supprime l'erreur Lua déclenchée à chaque apparition d'une barre d'unité (le code de Blizzard appelle une fonction de spécialisation que ce client ne gère pas).",
    ["Blizzard's own nameplate code asks for your specialization role - an API the Anniversary client rejects. The resulting Lua error fires on every nameplate spawn and aborts part of the nameplate setup. This fix answers the question safely with 'no role'."] = "Le code de Blizzard demande votre rôle de spécialisation — une fonction que le client Anniversaire refuse. L'erreur Lua qui en découle survient à chaque apparition de barre d'unité et interrompt une partie de sa mise en place. Ce correctif répond simplement « aucun rôle ».",
    ["Restores the missing 'in combat' glow on the Player frame (Anniversary default-UI bug). Pulses a red glow around your portrait while you are in combat."] = "Rétablit la lueur « en combat » absente de la fenêtre du joueur (défaut de l'interface Anniversaire). Une lueur rouge pulse autour de votre portrait pendant le combat.",
    ["|cffaaaaaaThe default Player frame on Anniversary no longer shows when you are in combat. This restores it: a red glow pulses around your portrait while you are in combat.|r"] = "|cffaaaaaaLa fenêtre du joueur par défaut sur Anniversaire n'indique plus quand vous êtes en combat. Ceci le rétablit : une lueur rouge pulse autour de votre portrait pendant le combat.|r",

    -- File de désenchantement : textes longs
    ["For enchanters: a window with one button that disenchants your bag items one click each, auto-advancing through the queue (no casting + picking each item by hand)."] = "Pour les enchanteurs : une fenêtre avec un seul bouton qui désenchante vos objets un clic à la fois, en avançant automatiquement dans la file (plus besoin de lancer le sort puis de choisir chaque objet).",
    ["You need the Enchanting profession (Disenchant) to use this."] = "Le métier d'Enchantement (Désenchantement) est nécessaire.",
    ["|cffaaaaaaA window with one button that disenchants your bag items one click each and auto-advances through the queue. WoW does not allow fully unattended disenchanting, so this is one click per item — but you never have to cast and pick each item by hand again.|r"] = "|cffaaaaaaUne fenêtre avec un seul bouton qui désenchante vos objets un clic à la fois et avance automatiquement dans la file. WoW n'autorise pas le désenchantement entièrement automatique : il faut donc un clic par objet — mais vous n'avez plus jamais à lancer le sort puis choisir chaque objet à la main.|r",
    ["|cffff5555You are not an enchanter — this tool will do nothing.|r"] = "|cffff5555Vous n'êtes pas enchanteur — cet outil ne fera rien.|r",
    ["|cff888888Also: /disenchant or /entzaubern|r"] = "|cff888888Également : /disenchant ou /entzaubern|r",
    ["|cff888888Only weapons and armour are listed. Each item is shown before you click, so you always see what you are about to disenchant.|r"] = "|cff888888Seuls les armes et les armures sont listées. Chaque objet est affiché avant votre clic : vous voyez toujours ce que vous allez désenchanter.|r",
    ["Skip this item for now (it comes back next time)."] = "Passer cet objet pour l'instant (il reviendra la prochaine fois).",
    ["Never disenchant this item (add it to the ignore list)."] = "Ne jamais désenchanter cet objet (l'ajouter à la liste des exclusions).",
    ["|cff888888No ignored items yet. Use the Ignore button in the window to protect an item.|r"] = "|cff888888Aucun objet exclu pour l'instant. Utilisez le bouton Ignorer dans la fenêtre pour protéger un objet.|r",
    ["|cff888888Click an entry to remove it from the ignore list.|r"] = "|cff888888Cliquez sur une entrée pour la retirer de la liste des exclusions.|r",

    -- Groupes et commandes : textes longs
    ["Quest log, profession windows and the disenchant queue, all in one place."] = "Journal de quêtes, fenêtres de métier et file de désenchantement, au même endroit.",
    ["Gold tracking and automatic buying at vendors."] = "Suivi de l'or et achat automatique chez les vendeurs.",
    ["toggle a name on/off the spam-filter whitelist"] = "ajouter ou retirer un nom de la liste blanche du filtre anti-spam",
    ["Type |cff9b6cff/vcui help|r for the full command list."] = "Tapez |cff9b6cff/vcui help|r pour la liste complète des commandes.",
    ["Usage: /vcui spam <name> — toggle a name on/off the spam-filter whitelist."] = "Utilisation : /vcui spam <nom> — ajoute ou retire un nom de la liste blanche du filtre anti-spam.",

    -- Minuteur d'attaque : textes longs
    ["Weapon swing timer for your melee auto-attacks (any melee class). Shows a main-hand bar and, while dual-wielding, an off-hand bar."] = "Minuteur d'attaque pour vos attaques automatiques au corps à corps (toute classe de mêlée). Affiche une barre de main droite et, en ambidextrie, une barre de main gauche.",
    ["|cffaaaaaaShows when your next melee auto-attack lands (any melee class). The off-hand bar only appears while dual-wielding. The bar fills up toward the swing; the number is the time left.|r"] = "|cffaaaaaaIndique quand tombe votre prochaine attaque automatique (toute classe de mêlée). La barre de main gauche n'apparaît qu'en ambidextrie. La barre se remplit jusqu'au coup ; le chiffre est le temps restant.|r",
    ["|cffffffffSWING TIMER|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffMINUTEUR D'ATTAQUE|r\n|cffaaaaaaGlisser ou touches fléchées|r",
    ["|cffffffffLOADOUTS SIDEBAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffBARRE DES ENSEMBLES|r\n|cffaaaaaaGlisser ou touches fléchées|r",
    ["Swing Timer mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Déplacement du minuteur d'attaque actif. |cff9b6cffGlissez le cadre violet|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Cliquez de nouveau sur « Déverrouiller / Tester » pour terminer.",
    ["Hides the bars unless you're auto-attacking. Turn off to always show them."] = "Masque les barres sauf pendant une attaque automatique. Désactivez pour les afficher en permanence.",

    -- Ensembles d'équipement : textes longs
    ["Save and quickly equip gear sets for different specs, content, or roles."] = "Enregistrez et équipez rapidement des ensembles pour différentes spécialisations, contenus ou rôles.",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "Enregistrez votre équipement actuel sous forme d'ensembles nommés et passez rapidement de l'un à l'autre. L'équipement n'est possible qu'hors combat — les objets de vos sacs sont équipés automatiquement via Utiliser.",
    ["Save current equipment as a new loadout. Enter name:"] = "Enregistrer l'équipement actuel comme nouvel ensemble. Nom :",
    ["Loadout '%s' equipped (%d swapped, %d missing from bags)."] = "Ensemble « %s » équipé (%d changés, %d absents des sacs).",
    ["Loadout '%s': %d items missing from bags, nothing swapped."] = "Ensemble « %s » : %d objets absents des sacs, rien n'a été changé.",
    ["Cannot change equipment in combat."] = "Impossible de changer d'équipement en combat.",
    ["Equipment swap API not available on this client."] = "Le changement d'équipement n'est pas disponible sur ce client.",
    ["No loadouts saved yet."] = "Aucun ensemble enregistré pour l'instant.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaAucun ensemble enregistré pour l'instant. Utilisez le bouton ci-dessus pour enregistrer votre équipement actuel.|r",
    ["Saved loadouts:"] = "Ensembles enregistrés :",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "Utilisation : /loadout equip <nom> | save <nom> | delete <nom> | list",
    ["Usage: /loadout delete <name>"] = "Utilisation : /loadout delete <nom>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaaCommandes : /loadout save <nom>, /loadout equip <nom>, /loadout delete <nom>, /loadout list. Alias court : /lo|r",
    ["No account-wide loadouts to import."] = "Aucun ensemble commun au compte à importer.",
    ["Imported %d account-wide loadout(s) onto this character."] = "%d ensemble(s) du compte importé(s) sur ce personnage.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "Vous avez des ensembles communs au compte issus d'une version antérieure. Tapez /lo import pour les copier sur ce personnage.",
    ["Import from older version"] = "Importer depuis une version antérieure",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaaUne version antérieure a enregistré des ensembles communs au compte. Les ensembles sont désormais propres à chaque personnage — l'importation les copie sur CE personnage.|r",
    ["Import account-wide loadouts"] = "Importer les ensembles du compte",

    -- Emplacements et macros
    ["Head"] = "Tête",
    ["Chest"] = "Torse",
    ["Feet"] = "Pieds",
    ["Finger 1"] = "Anneau 1",
    ["Trinket 1"] = "Bijou 1",
    ["Both trinkets"] = "Les deux bijoux",
    ["Set focus"] = "Définir le focus",
    ["Healing potion"] = "Potion de soins",
    ["Macro Factory"] = "Fabrique de macros",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaaUn clic crée une macro prête à l'emploi (par personnage). Ouvrez ensuite |cffffffff/macro|r et glissez-la sur votre barre d'action. Fonctionne sur tous les clients — utilise les emplacements et identifiants d'objets, aucun anglais requis.|r",
    ["Macro Factory: can't create macros in combat."] = "Fabrique de macros : impossible de créer une macro en combat.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "Fabrique de macros : rien à créer (p. ex. aucune potion de soins dans vos sacs).",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "Fabrique de macros : création impossible (emplacements de macros du personnage pleins ?).",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "Macro « %s » mise à jour — glissez-la depuis |cffffffff/macro|r sur votre barre d'action.",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "Macro « %s » créée — ouvrez |cffffffff/macro|r et glissez-la sur votre barre d'action.",
    ["Back"] = "Dos",
    ["Main Hand"] = "Main droite",

