    ["Right-click only"] = "Clic droit seul",
    ["Grid columns"] = "Colonnes de la grille",
    ["How many item icons per row in the picker popup."] = "Nombre d'icônes d'objets par ligne dans le sélecteur.",
    ["Items for: %s"] = "Objets pour : %s",
    ["Close automatically on mouse-out"] = "Fermer automatiquement à la sortie de la souris",
    ["The picker closes itself shortly after the mouse leaves it. Drag it once to pin it open until you close it manually."] = "Le sélecteur se ferme peu après que la souris l'a quitté. Faites-le glisser une fois pour l'épingler jusqu'à fermeture manuelle.",
    ["No matching items in your bags."] = "Aucun objet correspondant dans vos sacs.",
