    -- Confort de jeu
    ["Crisp portrait hit numbers"] = "Chiffres nets sur le portrait",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Affiche les chiffres de dégâts et de soins qui apparaissent sur le portrait du joueur ou du familier avec une police nette et fixe, au lieu de l'animation grandissante et floue de Blizzard.",
    ["Hit number size"] = "Taille des chiffres du portrait",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Taille de police des chiffres du portrait (quand « Nets » est activé).",
    ["Auto-select single gossip option"] = "Choisir automatiquement l'unique option de dialogue",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Ignore les fenêtres de dialogue des PNJ qui ne proposent qu'une seule option. Maintenez Maj pour passer outre temporairement.",
    ["Faster auto-loot"] = "Ramassage automatique plus rapide",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "Ramasse tous les objets d'un coup lorsque le ramassage automatique s'applique, au lieu d'un par un.",
    ["Max camera zoom"] = "Zoom arrière maximal",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "Augmente la distance maximale d'éloignement de la caméra bien au-delà de la valeur par défaut.",

    -- Fenêtres joueur et cible
    ["Player & Target Frame"] = "Fenêtres du joueur et de la cible",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "Bordure de dragon d'élite pour votre fenêtre de joueur, plus les points de vie réels, l'affichage de la menace et la bordure rare-élite pour les fenêtres de cible et de focus.",
    ["Target & Focus Frame"] = "Fenêtres de cible et de focus",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaaPlace le dragon d'élite doré (ou ses variantes rares) autour de votre portrait — l'aspect qu'ont les créatures d'élite sur la fenêtre de cible.|r",
    ["Frame style"] = "Style de fenêtre",
    ["Elite (golden dragon)"] = "Élite (dragon doré)",
    ["Rare-Elite (silver dragon)"] = "Rare-élite (dragon argenté)",
