    -- Groupes de recharges
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888Ce groupe est encore vide.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Groupe de recharges « %s » déverrouillé. Glissez-y des sorts ou objets ; |cff9b6cffglissez|r pour le déplacer.",
    ["Cooldown group '%s' locked."] = "Groupe de recharges « %s » verrouillé.",
    ["Group type"] = "Type de groupe",
    ["Buffs & Procs (only show while active)"] = "Améliorations et effets déclenchés (visibles seulement quand actifs)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaLes icônes n'apparaissent que tant que l'effet est actif sur vous ; la barre reste vide sinon. Ajoutez l'EFFET (p. ex. Prescience) par nom ou par identifiant.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaLes icônes affichent la recharge de chaque sort ou bijou.|r",
    ["Size & offsets"] = "Taille et décalages",
    ["Extra settings"] = "Réglages supplémentaires",

    -- Liste d'amis
    ["Friends List"] = "Liste d'amis",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Noms aux couleurs de classe, icônes de classe, pastilles d'état, notes intégrées, teinte de faction et acceptation automatique facultative.",
    ["Dark window skin"] = "Habillage sombre de la fenêtre",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Habille toute la fenêtre d'amis en sombre avec des accents violets. La désactiver nécessite un /reload pour rétablir la fenêtre de Blizzard.",
    ["Class color names"] = "Noms aux couleurs de classe",
    ["Colors each online friend's name by their class."] = "Colore le nom de chaque ami connecté selon sa classe.",
    ["Show class icons"] = "Afficher les icônes de classe",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Affiche une icône de classe à côté des amis WoW connectés (en jeu et Battle.net).",
    ["Class icon style"] = "Style des icônes de classe",
    ["Blizzard crests"] = "Emblèmes Blizzard",
    ["Circles"] = "Cercles",
    ["Squares"] = "Carrés",
    ["Show status dot"] = "Afficher la pastille d'état",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Une pastille colorée après le nom : vert connecté, jaune absent, rouge occupé, gris déconnecté.",
    ["Show friend notes"] = "Afficher les notes d'ami",
    ["Shows your saved note for the friend in grey under their name."] = "Affiche en gris, sous le nom, la note que vous avez enregistrée pour cet ami.",
    ["Faction"] = "Faction",
    ["Faction accent on realm line"] = "Accent de faction sur la ligne du royaume",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Teinte la ligne du royaume ou de la zone en rouge (Horde) ou en bleu (Alliance).",
    ["Faction row tint"] = "Teinte de faction sur la ligne",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Ajoute une légère teinte de fond rouge ou bleue à la ligne de chaque ami connecté.",
    ["Invites"] = "Invitations",
    ["Auto-accept Battle.net friend invites"] = "Accepter automatiquement les demandes d'ami Battle.net",
    ["Automatically accepts incoming Battle.net friend requests."] = "Accepte automatiquement les demandes d'ami Battle.net entrantes.",
    ["Auto-accept group invites from friends"] = "Accepter automatiquement les invitations de groupe des amis",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Rejoint automatiquement un groupe quand l'invitation vient d'une personne de votre liste d'amis.",

    -- Fenêtres de dialogue et habillages
    ["Dialog Popups"] = "Fenêtres de confirmation",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Habille les fenêtres de confirmation de Blizzard (compte à rebours de déconnexion, suppression d'objet, résurrection, invitation de groupe) dans le style sombre.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaHabille les fenêtres de confirmation de Blizzard — compte à rebours de déconnexion, suppression d'objet, résurrection, invitation de groupe — dans le style sombre.|r",
    ["Accent strip"] = "Bande d'accent",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Trace un fin dégradé d'accent le long du bord supérieur de chaque fenêtre.",
    ["Addon Skins"] = "Habillages d'add-ons",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Habille les fenêtres des add-ons pris en charge dans le style sombre : liste d'erreurs, suivi de quêtes, navigateur de butin, profileur et plus encore.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaHabille les fenêtres des add-ons pris en charge dans le style sombre. L'habillage s'applique au chargement de l'add-on ; le désactiver nécessite un /reload (le suivi de quêtes se rétablit immédiatement).|r",
    ["not loaded"] = "non chargé",

