    ["Only while solo"] = "Uniquement en solo",
    ["Never (temporarily off)"] = "Jamais (désactivé temporairement)",
    ["Countdown text size"] = "Taille du texte du compte à rebours",
    ["Percent of the icon size."] = "Pourcentage de la taille de l'icône.",
    ["Countdown text color..."] = "Couleur du texte du compte à rebours...",
    ["Warn color under (sec)"] = "Couleur d'alerte sous (s)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "En dessous de ce nombre de secondes, le compte à rebours passe à la couleur d'alerte ; 0 désactive la couleur d'alerte.",
    ["Warn color..."] = "Couleur d'alerte...",
    ["Glow while ready"] = "Lueur quand c'est prêt",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Une lueur continue tant que la recharge est prête — et, pour les sorts, uniquement lorsqu'ils sont réellement utilisables (mana suffisant, etc.).",
    ["Glow color"] = "Couleur de la lueur",
    ["Show keybinds"] = "Afficher les raccourcis",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Affiche la touche à laquelle le sort ou l'objet est assigné sur vos barres d'action. Les macros ne sont pas reconnues ; les pages de posture suivent la barre principale.",
    ["Keybind color..."] = "Couleur des raccourcis...",
    ["Keep inactive buffs visible (greyed out)"] = "Garder les effets inactifs visibles (grisés)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Les icônes restent en place quand l'effet se termine, simplement désaturées — la barre ne se réorganise jamais.",
    ["Add (name / ID)"] = "Ajouter (nom / identifiant)",
    ["Tracked"] = "Suivis",
    ["  |cff888888(item)|r"] = "  |cff888888(objet)|r",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(autre classe)|r",
    ["Up"] = "Monter",
    ["Icons per row"] = "Icônes par ligne",
    ["Growth direction"] = "Sens de croissance",
    ["Right"] = "Droite",
    ["Left"] = "Gauche",
    ["Down"] = "Bas",
    ["Only show while on cooldown"] = "Afficher uniquement pendant la recharge",
    ["Hides ready icons; they reappear when on cooldown."] = "Masque les icônes prêtes ; elles réapparaissent pendant la recharge.",
    ["Show countdown text"] = "Afficher le compte à rebours",
    ["Show stacks"] = "Afficher les cumuls",

    -- Mode édition
    ["Edit mode — move the cooldown bars"] = "Mode édition — déplacer les barres de recharge",
    ["Stop editing — lock the cooldown bars"] = "Terminer — verrouiller les barres de recharge",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "Déverrouille uniquement les barres de recharge pour pouvoir les glisser. Les touches fléchées affinent ; clic droit sur un cadre violet pour X/Y. (Pour déplacer TOUTES les fenêtres VuloUI, utilisez « Mode déverrouillage » dans Général.)",

    -- Recharges : filtres et disposition
    ["Hide cooldowns under (sec)"] = "Masquer les recharges sous (s)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "Les recharges inférieures ou égales à cette valeur sont ignorées. 1,5 masque le temps de recharge global ; augmentez pour masquer aussi les recharges courtes ; 0 affiche tout.",
    ["Move earlier"] = "Déplacer avant",
    ["Move later"] = "Déplacer après",
    ["Stack / reagent position"] = "Position des cumuls / composants",
    ["Stack / reagent size"] = "Taille des cumuls / composants",
    ["Stack / reagent color..."] = "Couleur des cumuls / composants...",
    ["Bottom right"] = "En bas à droite",
    ["Bottom left"] = "En bas à gauche",
    ["Top right"] = "En haut à droite",
    ["Top left"] = "En haut à gauche",
    ["Show reagent counts"] = "Afficher le nombre de composants",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "Affiche le nombre de composants PROPRE à chaque sort — Fragments d'âme pour Feu de l'âme, Pierre infernale pour Infernal, etc. Les sorts sans composant n'affichent rien. Nécessite « Afficher les cumuls ».",
    ["Anchor"] = "Ancrage",
    ["Anchor to"] = "Ancrer à",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "Fixe cette barre à une fenêtre d'unité, à la minicarte ou à la barre d'un autre groupe — elle suit alors ses déplacements. Glissez la barre pour la détacher.",
    ["Player Frame"] = "Fenêtre du joueur",
    ["Focus Frame"] = "Fenêtre du focus",
    ["Pet Frame"] = "Fenêtre du familier",
    ["None (free)"] = "Aucun (libre)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "Gestionnaire de recharges : ancrage impossible ici — cela créerait une boucle.",
    ["Side"] = "Côté",
    ["Below"] = "En dessous",
    ["Above"] = "Au-dessus",
    ["Left of"] = "À gauche de",
    ["Right of"] = "À droite de",
    ["X offset"] = "Décalage X",
    ["Y offset"] = "Décalage Y",
    ["Icon shape"] = "Forme des icônes",
