    ["Rounded"] = "Arrondie",
    ["Icon crop (%)"] = "Rognage des icônes (%)",
    ["How much is cut off each edge of the icon. 0 shows the whole icon including the border baked into its artwork."] = "Ce qui est coupé sur chaque bord de l'icône. 0 affiche l'icône entière, bordure de son image comprise.",
    ["Cooldown swipe darkness"] = "Assombrissement du balayage de recharge",
    ["Only in combat"] = "Uniquement en combat",
