    -- Bar Setups
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Enregistre des instantanés nommés de vos barres d'action, macros et raccourcis, et les restaure en un clic.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaEnregistre toute votre configuration de barres (emplacements, macros, raccourcis) sous forme de profil nommé et la restaure en un clic — par exemple une disposition JcJ et une disposition raid, ou pour recopier une configuration sur un reroll (stockage commun au compte).|r",
    ["Load"] = "Charger",
    ["Save current setup"] = "Enregistrer la configuration actuelle",
    ["Please enter a profile name first."] = "Veuillez d'abord saisir un nom de profil.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Aucun profil enregistré pour l'instant.|r",
    ["Also restore macros"] = "Restaurer aussi les macros",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Réécrit les macros enregistrées d'après leur nom (les existantes sont mises à jour, les absentes créées).",
    ["Also restore keybindings"] = "Restaurer aussi les raccourcis",
    ["Load profile"] = "Charger le profil",
    ["Overwrite with current setup"] = "Écraser avec la configuration actuelle",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Remplace le profil sélectionné par vos barres, macros et raccourcis actuels.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Remarque : le profil « %s » a été enregistré sur une autre classe (%s).",

    -- Minuteur de vol
    ["Flight Timer"] = "Minuteur de vol",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800La base des trajets aériens n'est pas chargée.|r Redémarrez complètement WoW (un /reload ne suffit pas après une mise à jour) pour que les temps de vol fonctionnent.",
    ["Show flight time bar"] = "Afficher la barre de temps de vol",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Affiche la destination et le temps restant pendant un vol. Le premier trajet d'une route est mémorisé, ensuite vous obtenez un compte à rebours.",
    ["Flight: %s (%s)"] = "Vol : %s (%s)",
    ["Print flight time to chat"] = "Afficher le temps de vol dans la discussion",
    ["After landing, prints the measured flight time."] = "Après l'atterrissage, affiche le temps de vol mesuré.",
    ["Reset learned times"] = "Réinitialiser les temps mémorisés",
    ["Deletes all saved route durations."] = "Supprime toutes les durées de trajet enregistrées.",
    ["Learned flight times reset."] = "Temps de vol mémorisés réinitialisés.",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffTEMPS DE VOL|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Minuteur de vol : x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Déplacement du minuteur de vol actif. |cff9b6cffGlissez|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px).",
    ["Flight timer mover disabled."] = "Déplacement du minuteur de vol désactivé.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Débogage de vol activé — prenez un vol, la résolution s'affichera dans le chat.",
    ["Flight debug off."] = "Débogage de vol désactivé.",

