    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "Définit en plus DAMAGE_TEXT_FONT globalement — change la police des chiffres de dégâts au-dessus des créatures et familiers. Nécessite /reload.",
