    ["Show clock"] = "Afficher l'horloge",
    ["Show date"] = "Afficher la date",
    ["Shows the date next to the clock. Click it to open the calendar."] = "Affiche la date à côté de l'horloge. Cliquez dessus pour ouvrir le calendrier.",
    ["Buttons"] = "Boutons",
    ["Zoom buttons (+/-)"] = "Boutons de zoom (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "Affiche un + et un - épurés sur le bord droit de la carte. La molette permet toujours de zoomer également.",
    ["Show day/night button"] = "Afficher le bouton jour / nuit",
    ["Restyle addon buttons"] = "Restyler les boutons d'add-on",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "Retire les bordures dorées des boutons de minicarte des autres add-ons et leur donne un aspect rond épuré. La désactivation nécessite un /reload.",
    ["Addon buttons only on mouseover"] = "Boutons d'add-on au survol uniquement",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "Masque les boutons de minicarte des autres add-ons tant que la souris n'est pas sur la minicarte.",
    ["Ping in chat"] = "Signal dans la discussion",
    ["Prints who pinged the minimap."] = "Indique qui a envoyé un signal sur la minicarte.",

    -- Barre de totems
    ["Totem Bar"] = "Barre de totems",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffffClic gauche|r sur une icône pour (re)lancer le totem de cet élément, |cffffffffsurvolez|r un emplacement pour choisir le totem dans la liste, |cffffffffclic du milieu|r pour rappeler tous les totems. La bordure de l'icône passe au rouge juste avant l'expiration du totem.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800Actif uniquement sur un chaman.|r",
    ["Totem set"] = "Ensemble de totems",
    ["Active set"] = "Ensemble actif",
    ["Set name"] = "Nom de l'ensemble",
    ["New set"] = "Nouvel ensemble",
    ["Delete set"] = "Supprimer l'ensemble",
    ["Shown elements"] = "Éléments affichés",
    ["Sound before a totem expires"] = "Son avant l'expiration d'un totem",
    ["Icon border (action-bar style)"] = "Bordure d'icône (style barre d'action)",
