    ["Flyout direction"] = "Direction du menu déroulant",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "Sens d'ouverture du sélecteur de totems au survol d'un emplacement. Automatique choisit le côté opposé au bord de l'écran.",
    ["Automatic"] = "Automatique",
    ["Upwards"] = "Vers le haut",
    ["Downwards"] = "Vers le bas",
    ["To the left"] = "Vers la gauche",
    ["To the right"] = "Vers la droite",
    ["Open flyout in combat"] = "Ouvrir le sélecteur en combat",
    ["Tooltip with cooldown on hover"] = "Infobulle avec recharge au survol",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "Survoler un emplacement de totem ou une icône du sélecteur affiche le nom du totem et sa recharge restante.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Désactivé = survoler un emplacement n'ouvre jamais le sélecteur de totems pendant un combat (les clics lancent toujours le totem). Le sélecteur se referme également de lui-même lorsque la souris le quitte et après chaque lancement, même en combat.",
    ["Earth"] = "Terre",
    ["Water"] = "Eau",
    ["|cffffffffTOTEMS|r"] = "|cffffffffTOTEMS|r",
    ["Totems: x=%.0f, y=%.0f"] = "Totems : x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Déplacement des minuteurs de totems actif. |cff9b6cffGlissez|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px).",
    ["Totem timer mover disabled."] = "Déplacement des minuteurs de totems désactivé.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555Erreur d'outil de classe :|r %s",

    -- Mode Édition
    ["EDIT MODE"] = "MODE ÉDITION",
    ["Edit Mode"] = "Mode Édition",
    ["Open Edit Mode"] = "Ouvrir le mode Édition",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "Ferme le mode Édition et verrouille toutes les fenêtres. Vos modifications restent appliquées.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "Conserve la disposition actuelle et poursuit l'édition. Abandonner revient alors à ce point plutôt qu'à l'état d'ouverture du mode Édition.",
    ["Window positions saved."] = "Positions des fenêtres enregistrées.",
    ["Exit"] = "Quitter",
    ["Close"] = "Fermer",
    ["Reset"] = "Réinitialiser",
    ["Reset this frame"] = "Réinitialiser cette fenêtre",
    ["Reset all VuloUI window positions to the screen centre."] = "Réinitialise toutes les positions de fenêtre VuloUI au centre de l'écran.",
    ["Reset all VuloUI window positions to the screen centre?"] = "Réinitialiser toutes les positions de fenêtre VuloUI au centre de l'écran ?",
    ["Done — lock everything"] = "Terminé — tout verrouiller",
    ["Grid"] = "Grille",
    ["Snap"] = "Aimanter",
    ["Show an alignment grid."] = "Affiche une grille d'alignement.",
    ["Snap windows to the grid while dragging."] = "Aimante les fenêtres à la grille pendant le déplacement.",
    ["%d frames here - hold Alt to cycle"] = "%d fenêtres ici — maintenez Alt pour les parcourir",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "Point de l'écran auquel la fenêtre est fixée (elle reste en place lors des changements de résolution).",
    ["ANCHOR"] = "ANCRAGE",
    ["POSITION"] = "POSITION",
    ["SCALE"] = "ÉCHELLE",
    ["FREE MOVE"] = "DÉPLACEMENT LIBRE",
    ["FOLLOW WINDOW"] = "SUIVRE UNE FENÊTRE",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "Fixe cette fenêtre à une autre — elle suit alors chaque déplacement de celle-ci. Déplacer cette fenêtre conserve la liaison et met simplement à jour l'écart.",
    ["Not possible - that would create a loop."] = "Impossible — cela créerait une boucle.",
    ["Anchor to window..."] = "Ancrer à une fenêtre...",
    ["WIDTH LIKE"] = "LARGEUR COMME",
    ["HEIGHT LIKE"] = "HAUTEUR COMME",
    ["Takes its width from another window and keeps it."] = "Reprend la largeur d'une autre fenêtre et la conserve.",
    ["Takes its height from another window and keeps it."] = "Reprend la hauteur d'une autre fenêtre et la conserve.",
    ["This window sets its own size - the match will not stick."] = "Cette fenêtre définit sa propre taille — la correspondance ne tiendra pas.",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Hold Shift while dragging to lock one axis. Shift+right-click hides a box that is in the way."] = "Glissez un cadre, ou survolez-le et utilisez les touches fléchées (Maj = 5 px). Maintenez Maj pendant le déplacement pour verrouiller un axe. Maj + clic droit masque un cadre gênant.",
    ["Then click any window to anchor this one to it."] = "Cliquez ensuite sur une fenêtre pour y ancrer celle-ci.",
    ["Click a window to anchor it (right-click to cancel)."] = "Cliquez sur une fenêtre pour l'ancrer (clic droit pour annuler).",
    ["ANCHOR SIDE"] = "CÔTÉ D'ANCRAGE",
    ["Centered"] = "Centré",
    ["Top of"] = "En haut de",
    ["Bottom of"] = "En bas de",
    ["Discard"] = "Abandonner",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "Fixe cette fenêtre à un bord ou à un coin de l'écran pour qu'elle reste en place lors des changements de résolution. Désactivé, elle reste centrée.",
    ["Leave this window unlocked so you can still drag it after closing Edit Mode. Stays unlocked through /reload."] = "Laisse cette fenêtre déverrouillée pour pouvoir la déplacer même après la fermeture du mode Édition. Reste déverrouillée après un /reload.",

    -- Dispositions
    ["LAYOUTS"] = "DISPOSITIONS",
    ["Layouts"] = "Dispositions",
    ["SAVED"] = "ENREGISTRÉES",
    ["No layouts saved"] = "Aucune disposition enregistrée",
    ["No layout selected."] = "Aucune disposition sélectionnée.",
    ["Save, load, export and import named window layouts."] = "Enregistrez, chargez, exportez et importez des dispositions de fenêtres nommées.",
    ["Save your window arrangement, then load or share it any time."] = "Enregistrez votre agencement de fenêtres, puis chargez-le ou partagez-le à tout moment.",
    ["Pick a saved layout to load, delete or export."] = "Choisissez une disposition enregistrée à charger, supprimer ou exporter.",
    ["Save current as..."] = "Enregistrer l'actuelle sous...",
    ["Name for this layout:"] = "Nom de cette disposition :",
    ["Delete layout '%s'?"] = "Supprimer la disposition « %s » ?",
    ["Layout '%s' saved."] = "Disposition « %s » enregistrée.",
    ["Applied layout '%s' (%d frames)."] = "Disposition « %s » appliquée (%d fenêtres).",
    ["Layout '%s' imported."] = "Disposition « %s » importée.",
    ["Import"] = "Importer",
    ["Export"] = "Exporter",
    ["Imported"] = "Importée",
    ["Import failed (%s)."] = "Échec de l'importation (%s).",
    ["Paste a layout string and confirm:"] = "Collez une chaîne de disposition et confirmez :",
    ["Copy this string (Ctrl+A, Ctrl+C):"] = "Copiez cette chaîne (Ctrl+A, Ctrl+C) :",
    ["Copy the link with Ctrl+C:"] = "Copiez le lien avec Ctrl+C :",
    ["Click: copy link"] = "Clic : copier le lien",
    ["Move it in the unified Edit Mode (/vedit)."] = "Déplacez-la dans le mode Édition unifié (/vedit).",
    ["Drag the combat-text box in the unified Edit Mode (/vedit)."] = "Glissez le cadre du texte de combat dans le mode Édition unifié (/vedit).",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffffFENÊTRES D'ARÈNE|r",
    ["|cff44ff44Edit Mode is ON.|r Close this window to reach the boxes."] = "|cff44ff44Le mode Édition est actif.|r Fermez cette fenêtre pour accéder aux cadres.",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaaDéplacez tout dans un seul éditeur : les fenêtres VuloUI et celles de Blizzard (joueur, cible, focus, minicarte, améliorations). Elles s'aimantent à une grille commune.|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• Glissez un cadre violet pour déplacer la fenêtre correspondante.|n• Survolez un cadre, puis affinez avec les touches fléchées (MAJ = 5 px).|n• Clic droit sur un cadre pour saisir X / Y exactement.|n• |cffffffff/vedit|r bascule également le mode Édition.|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "Activez « Cible et focus » dans les réglages du mode Édition de Blizzard, puis faites /reload, afin que VuloUI puisse déplacer la fenêtre de cible et de focus.",

    -- Icônes d'aura personnalisées
    ["Debuffs on target (yours only)"] = "Affaiblissements sur la cible (les vôtres uniquement)",
    ["Missing buffs (reminder)"] = "Améliorations manquantes (rappel)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaaLes icônes apparaissent tant que VOTRE affaiblissement ou DoT est sur la cible, avec sa durée restante. Ajoutez l'affaiblissement par nom ou par identifiant.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaaLes icônes apparaissent tant que l'amélioration vous MANQUE — un rappel pour les huiles d'arme, les bénédictions et les bonus de nourriture. Ajoutez l'amélioration par nom ou par identifiant.|r",
    ["Tint blue when out of mana"] = "Teinter en bleu en cas de manque de mana",
    ["Tint red when out of range"] = "Teinter en rouge hors de portée",
    ["Needs a target; uses the spell's own range."] = "Nécessite une cible ; utilise la portée propre du sort.",
    ["Auto-track equipped trinkets"] = "Suivre automatiquement les bijoux équipés",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "Conserve automatiquement les deux bijoux équipés dans ce groupe — ils suivent lorsque vous changez de bijou.",
    ["(copy)"] = "(copie)",
    ["Show tooltips on hover"] = "Afficher les infobulles au survol",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "Les icônes interceptent alors la souris — laissez l'option désactivée si la barre se trouve au-dessus d'éléments cliquables.",

    -- Thème
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaaColore dans la teinte de votre choix tout ce qui est violet aujourd'hui — barre latérale, bordures, surbrillances, barres. Un /reload l'applique partout.|r",
    ["Preset"] = "Préréglage",
    ["Purple (default)"] = "Violet (par défaut)",
    ["Turquoise"] = "Turquoise",
    ["Pink"] = "Rose",
    ["Orange"] = "Orange",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "Couleur du thème modifiée. Un /reload l'applique partout (les éléments déjà dessinés conservent l'ancienne couleur jusque-là).",

    -- Mode sombre
    ["Dark Mode"] = "Mode sombre",
    ["Desaturate (greyscale)"] = "Désaturer (niveaux de gris)",
    ["Strips the colour out of the artwork before tinting, for a true greyscale look. Off keeps a hint of the original hue."] = "Retire la couleur des décors avant la teinte, pour de véritables niveaux de gris. Désactivé, une pointe de la teinte d'origine subsiste.",
    ["Tint colour"] = "Couleur de teinte",
    ["Unit frames"] = "Fenêtres d'unité",
    ["Player, target, focus, pet and party frame borders."] = "Bordures des fenêtres du joueur, de la cible, du focus, du familier et du groupe.",
    ["Minimap border, compass, zoom and tracking buttons."] = "Bordure de la minicarte, boussole, boutons de zoom et de pistage.",
    ["Action bar artwork"] = "Décors des barres d'action",
    ["The gryphons and the metal action-bar background."] = "Les griffons et le fond métallique des barres d'action.",
    ["Action button borders"] = "Bordures des boutons d'action",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "Teinte également l'anneau de bordure de chaque bouton d'action. Facultatif — laissez désactivé si le rendu paraît trop plat.",
    ["Bag slots"] = "Emplacements de sac",
    ["Tints the backpack, bag and keyring button borders."] = "Teinte les bordures des boutons du sac à dos, des sacs et du porte-clés.",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaaRemarque : si la |cfffffffflueur de menace|r du module Fenêtres joueur et cible est active, la coloration de menace prend le pas sur la bordure de cible et de focus tant que vous avez l'aggro — c'est voulu.|r",

    -- Discussion
    ["Chat"] = "Discussion",
    ["Polishes Blizzard's chat: a dark panel with an icon sidebar, timestamps, class-coloured names, clickable links, dark tabs, idle fade and history that survives a /reload. Every part is optional."] = "Peaufine la fenêtre de discussion de Blizzard : panneau sombre avec barre latérale d'icônes, horodatage, noms aux couleurs de classe, liens cliquables, onglets sombres, atténuation en cas d'inactivité et historique qui survit à un /reload. Chaque élément est facultatif.",
    ["|cffaaaaaaPolishes Blizzard's own chat — nothing is replaced, so it stays light and compatible. Every option below is independent.|r"] = "|cffaaaaaaPeaufine la fenêtre de discussion de Blizzard — rien n'est remplacé, l'ensemble reste léger et compatible. Chaque option ci-dessous est indépendante.|r",
    ["Timestamps"] = "Horodatage",
    ["Show timestamps"] = "Afficher l'horodatage",
    ["Prefixes each line with the time, using the game's own timestamp setting."] = "Préfixe chaque ligne avec l'heure, en utilisant le réglage d'horodatage du jeu.",
    ["Time format"] = "Format de l'heure",
    ["Names & links"] = "Noms et liens",
    ["Class-coloured names"] = "Noms aux couleurs de classe",
    ["Colours player names by their class in say, party, raid, guild, whisper and channels."] = "Colore les noms des joueurs selon leur classe dans les canaux dire, groupe, raid, guilde, chuchotement et canaux personnalisés.",
    ["Clickable links"] = "Liens cliquables",
    ["Turns web links into clickable links that open a copy box."] = "Transforme les adresses web en liens cliquables qui ouvrent une zone de copie.",
    ["Style chat tabs"] = "Styliser les onglets de discussion",
    ["Flat dark tab background with an accent underline on the active tab."] = "Fond d'onglet sombre et épuré, avec un soulignement d'accentuation sur l'onglet actif.",
    ["Tab label size"] = "Taille du texte des onglets",
    ["One uniform font size for every chat tab label."] = "Une taille de police uniforme pour tous les libellés d'onglet.",
    ["Chat font size (0 = Blizzard)"] = "Taille de police de la discussion (0 = Blizzard)",
    ["Scrollback (lines per window)"] = "Historique de défilement (lignes par fenêtre)",
    ["How many lines each chat window keeps for scrolling (Blizzard default: 128). More lines use a little more memory; changing this clears the currently shown lines once."] = "Nombre de lignes que chaque fenêtre de discussion conserve pour le défilement (valeur Blizzard par défaut : 128). Davantage de lignes consomment un peu plus de mémoire ; modifier ce réglage efface une fois les lignes affichées.",
    ["Item levels in chat links"] = "Niveaux d'objet dans les liens",
    ["Appends the item level to equipment links: [Sword] becomes [Sword (45)]."] = "Ajoute le niveau d'objet aux liens d'équipement : [Épée] devient [Épée (45)].",
    ["Panel opacity (%)"] = "Opacité du panneau (%)",
    ["Transparency of the dark background panel behind the chat."] = "Transparence du panneau sombre placé derrière la discussion.",
    ["Indent wrapped lines"] = "Indenter les lignes de continuation",
    ["Wraps long messages with continuation lines indented under the message start, for a cleaner column."] = "Renvoie les messages longs avec les lignes suivantes indentées sous le début du message, pour une colonne plus nette.",
    ["Idle fade"] = "Atténuation en cas d'inactivité",
    ["Fade chat when idle"] = "Atténuer la discussion en cas d'inactivité",
    ["Dims the chat after a while with no activity. A new message, hovering it or typing brings it back."] = "Atténue la discussion après un moment sans activité. Un nouveau message, le survol de la souris ou la saisie la rétablissent.",
    ["Idle delay (seconds)"] = "Délai d'inactivité (secondes)",
    ["Faded opacity (%)"] = "Opacité atténuée (%)",
    ["History"] = "Historique",
    ["Keep chat history"] = "Conserver l'historique de discussion",
    ["Remembers recent chat per character and re-shows it after a /reload."] = "Mémorise les discussions récentes par personnage et les réaffiche après un /reload.",
    ["Lines to keep"] = "Lignes à conserver",
    ["Clear history"] = "Effacer l'historique",
    ["Chat history cleared."] = "Historique de discussion effacé.",
    ["--- chat history ---"] = "--- historique de discussion ---",
    ["Copy"] = "Copier",
    ["Copy chat"] = "Copier la discussion",
    ["Link"] = "Lien",
    ["Ctrl+A to select all, Ctrl+C to copy."] = "Ctrl+A pour tout sélectionner, Ctrl+C pour copier.",
    ["Scroll to bottom"] = "Aller en bas",
    ["|cffaaaaaaThe panel, input and sidebar reposition Blizzard's chat. Turning them off here hides them immediately; a |cffffffff/reload|r restores the exact original positions.|r"] = "|cffaaaaaaLe panneau, la ligne de saisie et la barre latérale repositionnent la discussion de Blizzard. Les désactiver ici les masque immédiatement ; un |cffffffff/reload|r rétablit exactement les positions d'origine.|r",
    ["Dark background panel"] = "Panneau de fond sombre",
    ["A dark panel behind the chat and input line, with the tab bar above it — one cohesive block."] = "Un panneau sombre derrière la discussion et la ligne de saisie, avec la barre d'onglets au-dessus — un bloc homogène.",
    ["Top fade"] = "Dégradé supérieur",
    ["Fades old lines into the panel at the top edge of the chat."] = "Fait disparaître les anciennes lignes dans le panneau, sur le bord supérieur de la discussion.",
    ["Icon sidebar"] = "Barre latérale d'icônes",
    ["A slim bar left of the chat with copy, settings, new-window and scroll-to-bottom icons."] = "Une barre fine à gauche de la discussion, avec les icônes de copie, de réglages, de nouvelle fenêtre et de retour en bas.",
    ["Show online friends"] = "Afficher les amis connectés",
    ["Show how many friends are online at the top of the sidebar; click the icon to open the friends list."] = "Affiche le nombre d'amis connectés en haut de la barre latérale ; cliquez sur l'icône pour ouvrir la liste d'amis.",
    ["Friends online"] = "Amis connectés",
    ["New chat window"] = "Nouvelle fenêtre de discussion",
    ["Create new chat window"] = "Créer une nouvelle fenêtre de discussion",
    ["This client can't create extra chat windows."] = "Ce client ne peut pas créer de fenêtres de discussion supplémentaires.",
    ["Use VuloUI font"] = "Utiliser la police VuloUI",
    ["Applies the VuloUI font to the chat text, tabs and input line."] = "Applique la police VuloUI au texte de la discussion, aux onglets et à la ligne de saisie.",
    ["Copy button (standalone)"] = "Bouton de copie (indépendant)",
    ["A small copy button above the chat. Off by default since the sidebar already has a copy icon; turn the sidebar off to use this instead."] = "Un petit bouton de copie au-dessus de la discussion. Désactivé par défaut, la barre latérale disposant déjà d'une icône de copie ; désactivez la barre latérale pour l'utiliser à la place.",

    -- Sacs
    ["Bags"] = "Sacs",
    ["Inventory"] = "Inventaire",
    ["Items"] = "Objets",
    ["Hide"] = "Masquer",
    ["Show"] = "Afficher",
    ["Color item levels by quality"] = "Colorer les niveaux d'objet par qualité",
    ["Tints the item level number in the item's quality color instead of plain white."] = "Teinte le niveau d'objet dans la couleur de qualité de l'objet plutôt qu'en blanc.",
    ["%d free"] = "%d libres",
    ["|cffaaaaaaOne window for all your bags. Press your bag key (default B) to open it. Type in the search box to find items; click the sort button to tidy up. At a banker, your bank opens in a matching window.|r"] = "|cffaaaaaaUne seule fenêtre pour tous vos sacs. Appuyez sur votre touche de sac (B par défaut) pour l'ouvrir. Saisissez du texte dans le champ de recherche pour trouver un objet ; cliquez sur le bouton de tri pour ranger. Chez un banquier, votre banque s'ouvre dans une fenêtre assortie.|r",
    ["Quality borders"] = "Bordures de qualité",
    ["Colour each item's border by its rarity."] = "Colore la bordure de chaque objet selon sa rareté.",
    ["Item count text size"] = "Taille du texte de quantité",
    ["Reset bag position"] = "Réinitialiser la position des sacs",
    ["Search & sorting"] = "Recherche et tri",
    ["Show search box"] = "Afficher le champ de recherche",
    ["A search field in the window header. Dims items that don't match."] = "Un champ de recherche dans l'en-tête de la fenêtre. Atténue les objets qui ne correspondent pas.",
    ["Show sort button"] = "Afficher le bouton de tri",
    ["A sort button in the window header. Right-click it to reverse the order."] = "Un bouton de tri dans l'en-tête de la fenêtre. Un clic droit inverse l'ordre.",
    ["Reverse sort order"] = "Inverser l'ordre de tri",
    ["Sort bags"] = "Trier les sacs",
    ["Bank contents"] = "Contenu de la banque",
    ["Shows what your bank holds - from the last bank visit, viewable anywhere."] = "Affiche le contenu de votre banque — d'après la dernière visite, consultable n'importe où.",
    ["As of: %s"] = "Au : %s",
    ["%d free slots"] = "%d emplacements libres",
    ["No bank visit recorded on this character yet."] = "Aucune visite à la banque enregistrée sur ce personnage pour l'instant.",
    ["Right-click to toggle sort order."] = "Clic droit pour inverser l'ordre de tri.",
    ["Can't sort bags in combat."] = "Impossible de trier les sacs en combat.",
    ["Sort order: reversed"] = "Ordre de tri : inversé",
    ["Sort order: normal"] = "Ordre de tri : normal",
    ["Sort order"] = "Ordre de tri",
    ["How the sort button arranges items. 'Blizzard' groups by category like the default UI; the others are a flat order."] = "Manière dont le bouton de tri range les objets. « Blizzard » regroupe par catégorie comme l'interface par défaut ; les autres produisent un ordre linéaire.",
    ["Blizzard (category)"] = "Blizzard (catégorie)",
    ["Quality"] = "Qualité",
    ["Item type"] = "Type d'objet",
    ["Sort in the opposite direction."] = "Trier dans le sens inverse.",
    ["Item level"] = "Niveau d'objet",
    ["Off"] = "Désactivé",
    ["Sort categories by"] = "Trier les catégories par",
    ["Display-only ordering of the items inside each category section. Never moves anything in your bags."] = "Ordre d'affichage seulement, à l'intérieur de chaque section de catégorie. Ne déplace jamais rien dans vos sacs.",
    ["Show free slots (OneBag)"] = "Afficher les emplacements libres (sac unique)",
    ["OneBag view: show the empty bag slots after the items, so you can drop things onto them directly."] = "Vue sac unique : affiche les emplacements vides après les objets, pour pouvoir y déposer directement des choses.",
    ["Fixed slot order (OneBag)"] = "Ordre d'emplacement fixe (sac unique)",
    ["Shows every slot in its natural bag order with the empty slots inline — items stay visually where you drop them, like one big real bag. Needs the free-slots option above."] = "Affiche chaque emplacement dans son ordre naturel, emplacements vides compris — les objets restent visuellement là où vous les déposez, comme dans un seul grand sac réel. Nécessite l'option d'emplacements libres ci-dessus.",
    ["Junk marker (C)"] = "Marqueur de camelote (C)",
    ["Marks vendor trash with a purple C in the icon corner - grey items a merchant pays gold for."] = "Marque la camelote d'un C violet dans le coin de l'icône — les objets gris qu'un marchand rachète.",
    ["BoE/BoU markers"] = "Marqueurs LqÉ / LqU",
    ["Tags equipment that is still tradeable (binds on equip or use, not yet soulbound) - handy for banking and the auction house."] = "Marque l'équipement encore échangeable (lié quand équipé ou utilisé, pas encore lié) — pratique pour la banque et l'hôtel des ventes.",
    ["Categories"] = "Catégories",
    ["Group items into categories"] = "Regrouper les objets en catégories",
    ["Show items in labelled sections (Quest, Consumables, Armor...). Off = one flat grid."] = "Affiche les objets dans des sections nommées (Quête, Consommables, Armure...). Désactivé = une seule grille.",
    ["Hide empty categories"] = "Masquer les catégories vides",
    ["Don't show a section header for a category that has no items."] = "N'affiche pas d'en-tête de section pour une catégorie sans objet.",
