    ["Marks the spot on the enemy cast bar where YOUR interrupt comes off cooldown — everything after the tick is kickable."] = "Marque sur la barre d'incantation ennemie l'endroit où VOTRE interruption sort de recharge — tout ce qui suit le repère est interruptible.",
