    ["Below the bar"] = "Sous la barre",
    ["Above the bar"] = "Au-dessus de la barre",
    ["Execute line"] = "Ligne d'Exécution",
    ["A thin marker line on the bar at the chosen health percentage (e.g. 20 for Execute)."] = "Une fine ligne repère sur la barre au pourcentage de vie choisi (p. ex. 20 pour Exécution).",
    ["Execute line only on your target"] = "Ligne d'Exécution seulement sur votre cible",
    ["Execute line colour"] = "Couleur de la ligne d'Exécution",
    ["Execute line percent"] = "Pourcentage de la ligne d'Exécution",
    ["Show remaining cast time"] = "Afficher le temps d'incantation restant",
    ["Own colour while your interrupt is on cooldown"] = "Couleur propre quand votre interruption est en recharge",
    ["Interruptible casts paint differently while YOUR interrupt ability is still on cooldown — you see at a glance whether kicking is even possible."] = "Les incantations interruptibles se colorent différemment tant que VOTRE interruption est encore en recharge — vous voyez d'un coup d'œil si interrompre est possible.",
    ["Interrupt-on-cooldown colour"] = "Couleur interruption en recharge",
    ["Own bar colour on your target"] = "Couleur de barre propre sur votre cible",
    ["Your current target's health bar uses this colour instead of reaction / class / threat colours."] = "La barre de vie de votre cible actuelle utilise cette couleur au lieu des couleurs de réaction, de classe ou de menace.",
    ["Target bar colour"] = "Couleur de la barre de cible",
    ["Mouseover highlight"] = "Surbrillance au survol",
    ["Lightens the health bar of the plate under your mouse cursor."] = "Éclaircit la barre de vie de l'unité survolée par le curseur.",
    ["Target plate scale"] = "Échelle de la barre d'unité de la cible",
    ["Your target's plate is drawn this much larger (100 = off)."] = "La barre d'unité de votre cible est agrandie d'autant (100 = désactivé).",
    ["Behaviour"] = "Comportement",
    ["|cffaaaaaaThese are the game's own nameplate settings, changed live (not part of the profile). Not changeable in combat.|r"] = "|cffaaaaaaCe sont les réglages de barres d'unité du jeu lui-même, modifiés en direct (hors profil). Non modifiables en combat.|r",
    ["Plate motion"] = "Mouvement des barres d'unité",
    ["Overlapping"] = "Superposées",
    ["Stacking"] = "Empilées",
    ["Stacked spacing"] = "Espacement de l'empilement",
    ["Vertical distance between stacked plates (a tenth of the game value)."] = "Distance verticale entre les barres d'unité empilées (un dixième de la valeur du jeu).",
    ["Line-of-sight opacity"] = "Opacité hors ligne de mire",
    ["Opacity of plates whose unit is out of your line of sight."] = "Opacité des barres d'unité dont l'unité est hors de votre ligne de mire.",
    ["Plate view distance"] = "Distance d'affichage des barres d'unité",
    ["|cffaaaaaaWhile the key is held (or your target matches), the main bar shows the chosen bar's abilities instead. Fully secure — works in combat.|r"] = "|cffaaaaaaTant que la touche est maintenue (ou que votre cible correspond), la barre principale affiche les capacités de la barre choisie. Entièrement sécurisé — fonctionne en combat.|r",
    ["Shift held"] = "Maj maintenue",
    ["Ctrl held"] = "Ctrl maintenue",
    ["Alt held"] = "Alt maintenue",
    ["Friendly target"] = "Cible alliée",
    ["Hostile target"] = "Cible hostile",
    ["Group visibility"] = "Visibilité selon le groupe",
    ["Always"] = "Toujours",
    ["Only in a group"] = "Seulement en groupe ou en raid",
    ["Only in a party"] = "Seulement en groupe",
    ["Only solo"] = "Seulement en solo",
    ["Hide when mounted"] = "Masquer en monture",
    ["Hide without target"] = "Masquer sans cible",
    ["Hide without enemy target"] = "Masquer sans cible ennemie",
    ["Quick keybind mode (/vkb)"] = "Mode raccourci rapide (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Survolez un bouton d'action et appuyez sur une touche pour l'assigner. Les barres masquées sont affichées pendant l'assignation.",
    ["Swipe colour"] = "Couleur du balayage",
    ["Icon opacity on cooldown"] = "Opacité de l'icône en recharge",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Atténue toute l'icône tant que la capacité est en recharge (100 = désactivé).",
    ["Show cooldown numbers"] = "Afficher les chiffres de recharge",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Les chiffres de décompte du jeu sur les recharges (réglage du jeu, modifié en direct).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaS'applique à toutes les barres d'action.|r",
    ["Cooldown swipe opacity"] = "Opacité du balayage de recharge",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Intensité de l'assombrissement du balayage de recharge (0 = invisible).",
    ["Desaturate icons on cooldown"] = "Désaturer les icônes en recharge",
    ["Out-of-range colouring"] = "Coloration hors de portée",
    ["Tints the whole icon while your target is out of range."] = "Teinte toute l'icône tant que votre cible est hors de portée.",
    ["Tooltips"] = "Infobulles",
    ["Hide in combat"] = "Masquer en combat",
    ["Hide always"] = "Toujours masquer",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Une barre d'expérience déplaçable et redimensionnable, avec superposition du repos. Masquée au niveau maximum. Remplace la barre de Blizzard quand elle est active.",
    ["Hide Blizzard's XP / reputation bar"] = "Masquer la barre d'XP / de réputation de Blizzard",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Retire la barre bleue d'expérience / de réputation restante sous la barre d'action.",
    ["Stance bar"] = "Barre de posture",
    ["Pet bar"] = "Barre du familier",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Prend en charge toutes les barres d'action avec ses propres fenêtres déplaçables : affichage / masquage réel en combat ou au survol, échelle et disposition en grille par barre, pagination correcte de la barre principale (formes druide/voleur/guerrier/prêtre) et vos raccourcis. EXPÉRIMENTAL — testez les clics de capacité et la pagination en combat ; /reload après désactivation.",
    ["Standard action bars are back. Reload the interface to restore every last piece of the default layout."] = "Les barres d'action standard sont de retour. Recharger l'interface rétablit jusqu'au dernier détail de la disposition par défaut.",
    ["Buttons per row"] = "Boutons par rangée",
    ["Button spacing"] = "Espacement des boutons",
    ["Overlays damage-absorption shields (e.g. Power Word: Shield) on the health bar."] = "Superpose les boucliers d'absorption de dégâts (par ex. Mot de pouvoir : Bouclier) sur la barre de vie.",
    ["Absorb colour"] = "Couleur de l'absorption",
    ["Absorb opacity"] = "Opacité de l'absorption",
    ["Colour by threat"] = "Colorer selon la menace",
    ["Colour the health bar by your threat on the unit — coloured for your role. Useful in dungeons."] = "Colore la barre de vie selon votre menace sur l'unité — teinte adaptée à votre rôle. Utile en donjon.",
    ["Your role"] = "Votre rôle",
    ["DPS / Healer"] = "DPS / Soigneur",
    ["Tank"] = "Tank",
    ["Secure (tank has aggro)"] = "Sûr (le tank a l'aggro)",
    ["Warning (gaining / losing)"] = "Alerte (menace en hausse / en baisse)",
    ["Danger (pulled / lost)"] = "Danger (aggro prise / perdue)",
    ["Show NPC title"] = "Afficher le titre des PNJ",
    ["Shows a friendly NPC's subtitle (e.g. <Innkeeper>) under its name in name-only mode."] = "Affiche le sous-titre d'un PNJ amical (par ex. <Aubergiste>) sous son nom en mode nom seul.",
    ["<Innkeeper>"] = "<Aubergiste>",
    ["Nameplates"] = "Barres d'unité",
    ["Vulo Fantasy 1"] = "Vulo Fantasy 1",
    ["Vulo Fantasy 2"] = "Vulo Fantasy 2",
    ["Vulo Epic"] = "Vulo Epic",
    ["Always shown"] = "Toujours affichée",
    ["Mouseover"] = "Au survol",
    ["In combat"] = "En combat",
    ["Out of combat"] = "Hors combat",
    ["Faded opacity"] = "Opacité atténuée",
    ["Fade speed (sec.)"] = "Vitesse d'atténuation (s)",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555Barres d'action : rétablissement des barres de Blizzard à la fin du combat…|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaDes boutons propres pour chaque barre d'action (1-5) : véritable affichage/masquage en combat ou au survol, échelle et disposition en grille, changement de page correct de la barre principale (formes de druide, voleur, guerrier, prêtre) et vos raccourcis. Déplacez chacune dans le mode Édition (/vedit). Après désactivation, faites /reload pour rétablir entièrement les barres de Blizzard.|r",
    ["Action Bar 1 (Main)"] = "Barre d'action 1 (principale)",
    ["Action Bar 2"] = "Barre d'action 2",
    ["Action Bar 3"] = "Barre d'action 3",
    ["Action Bar 4"] = "Barre d'action 4",
    ["Action Bar 5"] = "Barre d'action 5",
    ["Action Bar 6 (Extra)"] = "Barre d'action 6 (supplémentaire)",
    ["Grow from"] = "Croissance depuis",
    ["Left edge (rightwards)"] = "Bord gauche (vers la droite)",
    ["Right edge (leftwards)"] = "Bord droit (vers la gauche)",
    ["Rows grow"] = "Croissance des rangées",
    ["Mouseover reveals all mouseover bars"] = "Le survol révèle toutes les barres en mode survol",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "Survoler N'IMPORTE QUELLE barre en mode survol affiche d'un coup toutes les barres réglées sur survol.",
    ["Button text styling"] = "Style du texte des boutons",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaaCouleurs et décalages précis des textes de boutons, sur toutes les barres.|r",
    ["Keybind text colour"] = "Couleur du texte des raccourcis",
    ["Macro text colour"] = "Couleur du texte des macros",
    ["Count text colour"] = "Couleur du texte de quantité",
    ["Keybind offset X"] = "Décalage X des raccourcis",
    ["Keybind offset Y"] = "Décalage Y des raccourcis",
    ["Macro offset X"] = "Décalage X des macros",
    ["Macro offset Y"] = "Décalage Y des macros",
    ["Count offset X"] = "Décalage X de la quantité",
    ["Count offset Y"] = "Décalage Y de la quantité",
    ["0 = use the game's default size."] = "0 = utilise la taille par défaut du jeu.",
    ["Vertical layout"] = "Disposition verticale",
    ["Reverse order"] = "Ordre inversé",
    ["Hide keybind text"] = "Masquer le texte des raccourcis",
    ["Hide macro text"] = "Masquer le texte des macros",
    ["Game Menu"] = "Menu du jeu",
    ["Game menu: VuloUI look"] = "Menu du jeu : aspect VuloUI",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Restyle le menu Échap pour l'accorder à l'aspect de l'add-on : panneau sombre, boutons épurés, titre d'accentuation. Toute modification nécessite un /reload.",
    ["Game menu: VuloClassicUI button"] = "Menu du jeu : bouton VuloClassicUI",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Ajoute au menu Échap un bouton VuloClassicUI qui ouvre la fenêtre des options. La désactivation nécessite un /reload.",
    ["Hide the FPS / latency bar"] = "Masquer la barre FPS / latence",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "Masque la petite barre verte de performances (FPS / latence) de Blizzard.",
    ["Micro menu style"] = "Style du micro-menu",
    ["World map"] = "Carte du monde",
    ["Friends list"] = "Liste d'amis",
    ["Group finder"] = "Recherche de groupe",
    ["Bag bar style"] = "Style de la barre des sacs",
    ["Key ring"] = "Porte-clés",
    ["Timer decimals below 10 seconds"] = "Décimales du minuteur sous 10 secondes",
    ["Interrupted by %s"] = "Interrompu par %s",
    ["Value + percent"] = "Valeur + pourcentage",
    ["Value + percent layout"] = "Disposition valeur + pourcentage",
    ["Short values (12.3k)"] = "Valeurs abrégées (12,3k)",
    ["Show percent sign"] = "Afficher le signe %",
    ["Smooth health changes"] = "Transitions de vie adoucies",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "La barre glisse vers la nouvelle valeur ; une traînée claire marque les points de vie qui s'écoulent.",
    ["Tint background with bar colour"] = "Teinter le fond avec la couleur de la barre",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "La partie vide de la barre prend une nuance assombrie de la couleur de la barre au lieu d'un gris sombre uni.",
    ["Glow at the bar edge"] = "Lueur au bord de la barre",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "Une lueur douce suit l'extrémité du remplissage, teintée de la couleur propre de la barre. S'applique aussi à la barre d'incantation.",
    ["Edge glow width"] = "Largeur de la lueur de bord",
    ["Rounded bar corners"] = "Coins de barre arrondis",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "Découpe le remplissage et le fond selon une forme arrondie. La bordure reste carrée, une fine bordure peut donc légèrement dépasser aux coins.",
    ["Overall plate scale (%)"] = "Échelle globale des barres d'unité (%)",
    ["Scales every plate at once, on top of each individual size."] = "Redimensionne toutes les barres d'unité d'un coup, en plus de chaque taille individuelle.",
    ["Vertical offset"] = "Décalage vertical",
    ["Moves every plate up or down relative to its unit."] = "Déplace chaque barre d'unité vers le haut ou vers le bas par rapport à son unité.",
    ["Font outline"] = "Contour de la police",
    ["How plate text is lifted off the background."] = "Manière dont le texte des barres d'unité se détache du fond.",
    ["Thick outline"] = "Contour épais",
    ["Show level"] = "Afficher le niveau",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "Affiche le niveau de l'unité à gauche du nom ; ?? signifie que le niveau dépasse largement le vôtre.",
    ["Mark rare and elite"] = "Marquer les rares et les élites",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "Ajoute un rang après le niveau et le colore en doré : + élite, R rare, R+ rare élite, B boss de monde.",
    ["Level size"] = "Taille du niveau",
    ["0 = uses the name size."] = "0 = utilise la taille du nom.",
    ["Emphasise casting units"] = "Mettre en avant les unités qui incantent",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "Pendant une incantation, la barre de l'unité grandit un peu et reste lisible même si une autre cible est sélectionnée.",
    ["Casting scale (%)"] = "Échelle pendant l'incantation (%)",
    ["Casting opacity (%)"] = "Opacité pendant l'incantation (%)",
    ["Colour border by school"] = "Colorer la bordure selon l'école",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "Les bordures d'aura prennent la couleur de leur école : magie en bleu, malédiction en violet, maladie en orange, poison en vert.",
    ["Flash before running out"] = "Clignoter avant expiration",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "L'icône pulse sur la dernière partie de sa durée, pour voir quand la rafraîchir.",
    ["Flash below (%)"] = "Clignoter en dessous de (%)",
    ["Your Own Debuffs"] = "Vos propres affaiblissements",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaaUne rangée séparée pour les auras nocives que vous lancez vous-même — vos minuteurs de dégâts sur la durée, à l'écart de tout le reste sur la cible.|r",
    ["Show your own debuffs (separate row)"] = "Afficher vos propres affaiblissements (rangée séparée)",
    ["Max icons"] = "Icônes maximum",
    ["Icons per line"] = "Icônes par ligne",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = une seule ligne. Sinon la rangée passe à la ligne après ce nombre d'icônes.",
    ["Reminders"] = "Rappels",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaaAffiche une courte rangée d'icônes pour ce qui vous manque en ce moment. Hors combat, un clic lance ou utilise le correctif ; le survol explique ce qui est attendu. La rangée reste figée pendant le combat.|r",
    ["Also warn about empty equipment slots"] = "Signaler aussi les emplacements d'équipement vides",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "Désactivé par défaut : un anneau, un bijou ou une cape est souvent vide à juste titre pendant la montée en niveau.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "Affiche ce qui vous manque — améliorations de classe, enchantements d'arme, nourriture, posture, familier, munitions, usure, emplacements d'équipement vides et points de talent non dépensés.",
    ["What to watch"] = "Éléments à surveiller",
    ["Class buffs"] = "Améliorations de classe",
    ["Weapon enchants"] = "Enchantements d'arme",
    ["Stance and aura"] = "Posture et aura",
    ["Food and flask"] = "Nourriture et flacon",
    ["Ammo, durability, gear, talents"] = "Munitions, usure, équipement, talents",
    ["Most icons at once"] = "Nombre maximal d'icônes",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "Au-delà, tout est regroupé dans un seul compteur au lieu d'ajouter une icône.",
    ["Show labels"] = "Afficher les libellés",
    ["Settle time (seconds)"] = "Délai de stabilisation (secondes)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "Durée pendant laquelle un élément doit rester manquant avant l'apparition d'une icône. Évite le clignotement entre deux incantations.",
    ["Warn when under (seconds)"] = "Avertir en dessous de (secondes)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "Avertir aussi quand une amélioration ou un enchantement d'arme est sur le point d'expirer. 0 = avertir uniquement quand il a disparu.",
    ["Durability below (%)"] = "Usure en dessous de (%)",
    ["Ammo below"] = "Munitions en dessous de",
    ["Quiet while resting"] = "Silencieux en zone de repos",
    ["No reminders in a city or inn."] = "Aucun rappel dans une ville ou une auberge.",
    ["Quiet while eating or drinking"] = "Silencieux en train de manger ou de boire",
    ["Click to cast."] = "Cliquez pour lancer.",
    ["Missing: %s"] = "Manquant : %s",
    ["Main hand"] = "Main droite",
    ["Off hand"] = "Main gauche",
    ["No weapon enchant: %s"] = "Aucun enchantement d'arme : %s",
    ["Weapon enchant running out: %s"] = "Enchantement d'arme sur le point d'expirer : %s",
    ["Stance"] = "Posture",
    ["No stance active"] = "Aucune posture active",
    ["Aura"] = "Aura",
    ["No aura active"] = "Aucune aura active",
    ["Pet"] = "Familier",
    ["No pet out"] = "Aucun familier invoqué",
    ["Passive"] = "Passif",
    ["Pet is set to passive"] = "Le familier est en mode passif",
    ["Food"] = "Nourriture",
    ["Not well fed"] = "Pas bien nourri",
    ["Flask"] = "Flacon",
    ["No flask or elixir"] = "Aucun flacon ni élixir",
    ["Low ammo: %d left"] = "Munitions faibles : %d restantes",
    ["Equipment damaged: %d%% left"] = "Équipement usé : %d%% restants",
    ["Empty equipment slots: %d"] = "Emplacements d'équipement vides : %d",
    ["Unspent talent points: %d"] = "Points de talent non dépensés : %d",
    ["Racials"] = "Capacités raciales",
    ["Racial Cooldowns"] = "Recharges des capacités raciales",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Affiche la capacité raciale de l'adversaire et sa recharge dès qu'il l'utilise. Ce sont les recharges de cette extension, et aucune capacité raciale ne partage encore de recharge avec le bijou JcJ.",
    ["Show racial cooldown"] = "Afficher la recharge raciale",
    ["Shadow Sight"] = "Vision de l'ombre",
    ["Shadow Sight up"] = "Vision de l'ombre disponible",
    ["Shadow Sight up - next in %d s"] = "Vision de l'ombre disponible — prochaine dans %d s",
    ["Shadow Sight in %d s"] = "Vision de l'ombre dans %d s",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Décompte les orbes d'arène : la première paire apparaît 95 secondes après l'ouverture des portes, et chacun revient 122 secondes après avoir été pris.",
    ["Show Shadow Sight timer"] = "Afficher le minuteur de Vision de l'ombre",
    ["Aura on the class icon"] = "Aura sur l'icône de classe",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Place sur l'icône de classe de l'adversaire l'aura la plus pertinente : une immunité prime sur un contrôle, qui prime sur une défensive, qui prime sur une recharge offensive.",
    ["Show aura on the class icon"] = "Afficher l'aura sur l'icône de classe",
    ["Crowd control only"] = "Contrôles uniquement",
    ["Dispels"] = "Dissipations",
    ["Dispel Cooldowns"] = "Recharges de dissipation",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaLa plupart des dissipations n'ont pas de recharge dans cette extension : seuls Dissipation de masse et Dévorer la magie du chasseur corrompu peuvent apparaître ici.|r",
    ["Show dispel cooldown"] = "Afficher la recharge de dissipation",
    ["Range"] = "Portée",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Estompe la fenêtre tant que l'adversaire est hors de portée, mesurée avec un sort que votre classe connaît plutôt qu'avec une distance fixe.",
    ["Fade out-of-range opponents"] = "Estomper les adversaires hors de portée",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Abandonne les modifications et rétablit chaque fenêtre au dernier point d'enregistrement, ou à son état à l'ouverture du mode Édition.",
    ["Discard all changes made since the last save?"] = "Abandonner toutes les modifications effectuées depuis le dernier enregistrement ?",
    ["Grey out when you walk out of range"] = "Griser quand vous sortez de la portée",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Retire la couleur tant que vous êtes hors du rayon d'un totem, et la rétablit dès que vous y revenez. Détecté d'après l'amélioration que le totem vous applique : les totems qui n'en donnent aucune (incendiaire, magma, tremblement, ...) restent donc toujours allumés.",
    ["Limit to"] = "Limiter à",
    ["Everything"] = "Tout",
    ["Only mine"] = "Les miennes uniquement",
    ["Only removable"] = "Dissipables uniquement",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Restreint cette rangée aux auras que vous lancez vous-même, ou à celles qui peuvent être dissipées.",
    ["Nudges every aura row at once, on top of each row's own offset."] = "Décale toutes les rangées d'auras à la fois, en plus du décalage propre à chaque rangée.",
    ["Share of the remaining duration at which the pulse starts."] = "Part de la durée restante à laquelle la pulsation commence.",
    ["Own colour while your interrupt is ready"] = "Couleur propre quand votre interruption est prête",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "Les incantations interruptibles prennent cette couleur tant que votre interruption n'est pas en recharge — coupez à volonté.",
    ["Interrupt-ready colour"] = "Couleur d'interruption prête",
    ["Own colour while channelling"] = "Couleur propre pendant la canalisation",
    ["Channel colour"] = "Couleur de canalisation",
    ["Own colour when the cast targets YOU"] = "Couleur propre quand l'incantation VOUS vise",
    ["The bar turns this colour while the caster's target is you."] = "La barre prend cette couleur tant que vous êtes la cible de l'incantateur.",
    ["Targets-you colour"] = "Couleur « vous êtes visé »",
    ["Show who interrupted"] = "Afficher qui a interrompu",
    ["The interrupt flash shows the name of whoever landed the interrupt."] = "Le clignotement d'interruption affiche le nom de celui qui a interrompu.",
    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "Activé : 9,9 ; 3,4 … Désactivé : secondes entières (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "Moderne place les vrais boutons de sac sur une bande sombre et épurée dans le style VuloUI — l'ouverture, l'échange et les infobulles restent identiques.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "Moderne remplace les boutons de Blizzard par une bande d'icônes sombre et épurée dans le style VuloUI. Les clics et les infobulles restent identiques.",
    ["Classic (Blizzard buttons)"] = "Classique (boutons Blizzard)",
    ["Modern (flat icon strip)"] = "Moderne (bande d'icônes épurée)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Masque la rangée de boutons de menu (personnage, grimoire, …).",
    ["Hide the bag bar"] = "Masquer la barre des sacs",
    ["Hides the backpack and bag slots."] = "Masque le sac à dos et les emplacements de sac.",
    ["|cff9b6cffThe micro menu, bag bar, FPS/latency bar and the XP bar below are movable in Edit Mode (/vedit) like the action bars.|r"] = "|cff9b6cffLe micro-menu, la barre des sacs, la barre FPS / latence et la barre d'expérience ci-dessous se déplacent en mode Édition (/vedit) comme les barres d'action.|r",
    ["Micro menu"] = "Micro-menu",
    ["Bag bar"] = "Barre des sacs",
    ["FPS / latency bar"] = "Barre FPS / latence",
    ["XP bar"] = "Barre d'expérience",
    ["Show a custom XP bar"] = "Afficher une barre d'expérience personnalisée",
    ["Colour"] = "Couleur",
    ["Bar opacity"] = "Opacité de la barre",
    ["Show empty buttons"] = "Afficher les boutons vides",
    ["Off hides empty slots; they reappear automatically while you drag an ability."] = "Désactivé masque les emplacements vides ; ils réapparaissent automatiquement pendant que vous glissez une capacité.",
    ["Click through"] = "Clics traversants",
    ["The bar ignores the mouse entirely — clicks go through it. Keybinds still work."] = "La barre ignore totalement la souris — les clics la traversent. Les raccourcis continuent de fonctionner.",
    ["Keybind text size"] = "Taille du texte des raccourcis",
    ["Macro text size"] = "Taille du texte des macros",
    ["Count text size"] = "Taille du texte de quantité",
    ["Cooldown text size"] = "Taille du texte de recharge",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "Réinitialiser TOUS les réglages de VuloClassicUI pour chaque personnage de ce compte ? Cette action est irréversible.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "Minuteur d’attaque désactivé : il ne suit que les attaques automatiques en mêlée, que les talents de ce personnage n’utilisent pas.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555Échec de la migration des réglages %s :|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "Joue un son d’alerte de raid dès qu’un adversaire utilise son bijou JcJ.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "Fait clignoter brièvement l’icône quand un adversaire utilise son bijou JcJ.",
    ["Icon gap"] = "Écart de l’icône",
    ["Distance between the icon and the bar."] = "Distance entre l’icône et la barre.",
    ["Accent colour"] = "Couleur d’accent",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "Utilisée pour la barre quand le mode de remplissage n’est pas une texture, et pour les incantations canalisées sur la barre de Blizzard.",
    ["Cast finished"] = "Incantation terminée",
    ["The bar flashes in this colour when a cast completes."] = "La barre clignote dans cette couleur quand une incantation se termine.",
    ["Cast interrupted"] = "Incantation interrompue",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "La barre clignote dans cette couleur quand une incantation est interrompue ou échoue.",
    ["Fade-in time"] = "Durée d’apparition",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "Temps que met une icône à apparaître. 0 l’affiche instantanément.",
    [" and %d item(s)"] = " et %d objet(s)",
    ["/vlfg toggles the group board."] = "/vlfg ouvre ou ferme le tableau de groupes.",
    ["Auto-apply a lure when the pole has none"] = "Appliquer automatiquement un appât si la canne n’en a pas",
    ["Auto-equip a fishing pole if none is worn"] = "Équiper automatiquement une canne à pêche si aucune n’est portée",
    ["Auto-loot while fishing"] = "Ramassage automatique pendant la pêche",
    ["Bags are full — some items were left in the mail."] = "Sacs pleins — certains objets sont restés dans le courrier.",
    ["Boost fishing sound (hear the bite clearly)"] = "Amplifier le son de pêche (entendre la touche clairement)",
    ["Burning Crusade Dungeons"] = "Donjons de Burning Crusade",
    ["Burning Crusade Raids"] = "Raids de Burning Crusade",
    ["Can't change the fishing key in combat."] = "Impossible de changer la touche de pêche en combat.",
    ["Classic Dungeons"] = "Donjons Classic",
    ["Classic Raids"] = "Raids Classic",
    ["Clear key"] = "Effacer la touche",
    ["Extra items & macros"] = "Objets et macros supplémentaires",
    ["Fishing key cleared."] = "Touche de pêche effacée.",
    ["Fishing key set to: %s"] = "Touche de pêche définie sur : %s",
    ["Fishing key: %s  —  click to change"] = "Touche de pêche : %s  —  cliquez pour changer",
    ["Fishing sound volume"] = "Volume du son de pêche",
    ["Friends"] = "Amis",
    ["Guild"] = "Guilde",
    ["H"] = "H",
    ["Hide the reel error spam while fishing"] = "Masquer les erreurs de récupération pendant la pêche",
    ["In Progress"] = "En cours",
    ["Invite"] = "Inviter",
    ["Keep requests for (minutes)"] = "Conserver les demandes pendant (minutes)",
    ["Keep sound audible when the game is in the background"] = "Garder le son audible quand le jeu est en arrière-plan",
    ["Keep this many bag slots free"] = "Garder ce nombre d’emplacements de sac libres",
    ["Mail emptied: looted %s%s."] = "Courrier vidé : %s%s récupéré.",
    ["No contacts yet"] = "Aucun contact pour l’instant",
    ["No groups forming right now."] = "Aucun groupe en formation pour le moment.",
    ["One-key reel (soft-target interact)"] = "Récupération à une touche (interaction cible douce)",
    ["Open All"] = "Tout ouvrir",
    ["Press the key for fishing  (ESC to cancel)"] = "Appuyez sur la touche pour la pêche  (ÉCHAP pour annuler)",
    ["Print a looted summary"] = "Afficher un résumé du butin",
    ["Recently mailed"] = "Destinataires récents",
    ["Recipient dropdown on the Send tab"] = "Menu des destinataires dans l’onglet Envoyer",
    ["Scan guild chat"] = "Analyser le canal de guilde",
    ["Scan say / yell"] = "Analyser dire / crier",
    ["Scan world / trade / LFG channels"] = "Analyser les canaux monde / commerce / recherche de groupe",
    ["Set fishing key"] = "Définir la touche de pêche",
    ["Slot %d"] = "Emplacement %d",
    ["Speed (seconds between actions)"] = "Vitesse (secondes entre les actions)",
    ["Take item attachments"] = "Prendre les objets joints",
    ["Take money"] = "Prendre l’argent",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "Tant que le bouchon est à l’eau, le volume des effets et le volume général passent au maximum et la musique et l’ambiance sont atténuées pour bien entendre le plouf. Rétabli quand vous récupérez.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "Tant que le bouchon est à l’eau, la même touche interagit avec lui pour le récupérer. Nécessite l’interaction cible douce, activée seulement pendant la pêche puis rétablie.",
    ["Whisper"] = "Chuchoter",
    ["Who"] = "Qui",
    ["Your characters"] = "Vos personnages",
    ["now"] = "maintenant",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaaAjoute un bouton « Tout ouvrir » à la boîte aux lettres. Il prend toutes les pièces jointes et l’argent, en ignorant les envois contre remboursement et les courriers de MJ. Maj+clic sur le bouton pour ignorer les filtres et tout prendre.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaaObjets ou macros que la touche utilise aussi pendant la pêche — uniquement quand ils sont prêts (hors recharge, buff absent, conditions remplies), ensuite elle relance le lancer. Tapez un nom ou un ID d’objet, Maj+clic pour insérer un objet, ou collez une /macro.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaaUne touche fait tout : lancer, récupérer et appliquer un appât — puis ramassage automatique. Définissez une touche ci-dessous, tournez-vous vers l’eau et appuyez.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555Erreur à la désactivation du sous-module d’arène :|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "Langues",
    ["Reminders (new module)"] = "Rappels (nouveau module)",
    ["Arena"] = "Arène",
    ["Totems"] = "Totems",
    ["Fixes"] = "Correctifs",
    ["Resource Bar"] = "Barre de ressource",
    ["Settings Window"] = "Fenêtre des réglages",
    ["Character Window"] = "Fenêtre du personnage",
    ["Nameplates (German: Namensplaketten)"] = "Barres d'unité (en allemand : Namensplaketten)",
    ["German client"] = "Client allemand",
    ["Performance"] = "Performances",
    ["Equipment Sets"] = "Ensembles d'équipement",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "Espagnol, français, italien, portugais, russe et coréen. Les six langues sont complètes — chacun des 2244 textes est traduit, rien ne retombe sur l'anglais. L'espagnol couvre aussi les clients d'Amérique latine. Choisissez votre langue dans Général, ou laissez sur Auto.",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "Affiche ce qui vous manque avant un pull : huiles et pierres d'arme, bénédictions, améliorations de nourriture et de flacons, l'aura ou la posture que vous avez oubliée. Cliquez sur un rappel pour le lancer ou l'utiliser. Désactivé par défaut, dans Confort de jeu.",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "Une étincelle au point de remplissage de la barre, des coins arrondis, des rangées d'auras à assigner librement, et vos propres effets de dégâts sur la durée sur une rangée dédiée.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "Les bordures d'aura prennent la couleur de leur école de sorts, et une aura clignote peu avant d'expirer.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "Texte de niveau et d'élite, plus échelle globale et décalage vertical par barre d'unité.",
    ["A window can take its width or height from another window and keep it."] = "Une fenêtre peut reprendre la largeur ou la hauteur d'une autre fenêtre et la conserver.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "Bouton Enregistrer. Pendant le déplacement, maintenez Maj pour verrouiller un axe.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "Recharges des bijoux et des capacités raciales, minuteur de Vision de l'ombre, un anneau sur l'icône de classe pour l'aura la plus importante, et vérification de la portée.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "Les icônes de totem deviennent grises dès que vous sortez de la portée du totem et retrouvent leurs couleurs à votre retour.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "La feuille de personnage et le grimoire s'ouvrent de nouveau en combat. Les barres d'action ne modifient plus un champ protégé depuis notre propre code, ce qui était la véritable cause.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "Le minuteur d'attaque est désactivé par défaut et ne se charge que pour les classes et spécialisations de mêlée.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "Les curseurs ont désormais un vrai style : bords adoucis, ombre intérieure et survol plus fluide.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "Des icônes dédiées pour les trois pages de collection, et des icônes de classe sur les onglets de classe.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "Ancrez une fenêtre au bord d'une autre (gauche/droite/haut/bas) — l'écart est conservé de bord à bord et survit donc au redimensionnement de l'une ou l'autre fenêtre.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "Ancrage par clic : appuyez sur « Ancrer à une fenêtre... » dans le panneau d'une fenêtre, puis cliquez sur la fenêtre cible. Les boucles et l'auto-ancrage sont bloqués.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "Pendant le déplacement, les lignes d'alignement affichent désormais aussi la distance en pixels jusqu'à la fenêtre avec laquelle vous vous alignez.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "Bouton Abandonner — prend un instantané de la disposition à l'ouverture du mode Édition et la rétablit (positions, échelle, ancrages et liaisons) si vous abandonnez.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "La zone de déplacement couvre désormais tout le panneau sombre de discussion jusqu'à la zone de saisie, et plus seulement l'étroite bande des messages.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "Correction : le clic droit sur la fenêtre de discussion n'ouvrait pas son panneau de réglages dans le mode Édition.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "Aide à l'interruption sur la barre d'incantation : couleurs distinctes selon que votre interruption est en recharge ou prête, un repère indiquant où elle redevient disponible en cours d'incantation, un bouclier sur les incantations ininterruptibles et un flash d'interruption qui peut indiquer qui a placé l'interruption.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "Suite pour la barre d'incantation : côté et échelle de l'icône, temps restant, arrière-plan dédié, couleur de canalisation, une couleur d'alerte quand l'incantation VOUS vise — et sur votre cible, la barre d'incantation s'aligne au ras de la barre de vie, bordure comprise.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "Ligne d'exécution, effets de cible et de survol, section de contrôle des foules, formes et placement des points de combo, réglages de position, de taille et de taille de texte par élément, plus un sélecteur de police.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "La page d'options intègre un aperçu en direct cliquable qui reste épinglé pendant le défilement — cliquez sur un élément pour accéder à ses réglages.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "Transitions de vie adoucies avec traînée de dégâts, affichages de texte en valeur et en pourcentage avec nombres abrégés, et une option de décimales pour les minuteurs d'aura.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "Conditions de visibilité par barre (instances, monture, cible, groupe), changement de page par touche de modification, mode raccourci rapide (/vkb), une sixième barre, directions de croissance, style du texte des boutons et options d'apparence des recharges.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "Style moderne pour le micro-menu et la barre des sacs : bandes sombres et plates avec un jeu d'icônes monochromes dédié, plus des boutons de carte du monde, de liste d'amis, de recherche de groupe, de boutique et de porte-clés.",
    ["The experience bar width now adjusts in single steps."] = "La largeur de la barre d'expérience se règle désormais pas par pas.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "Conditions de visibilité, modes de couleur avec dégradé, couleurs d'arrière-plan et de bordure, transitions de valeur adoucies, graduations et couleur de seuil.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "Le panneau des caractéristiques de la feuille de personnage ne déborde plus sur les autres onglets ; la barre latérale des ensembles s'aligne sur la feuille de personnage moderne.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "Le panneau et le bouton du calculateur de points d'arène adoptent l'aspect de l'add-on et s'ancrent à côté de la feuille de personnage.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Le menu Échap adopte désormais l'aspect sombre de l'add-on — boutons plats, titre en couleur d'accent — et gagne un bouton VuloClassicUI qui ouvre la fenêtre des options. Chacun possède son propre interrupteur dans Général.",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "La fenêtre d'ajout d'ami est habillée à l'identique : panneau sombre, titre en couleur d'accent, champ de saisie sombre et boutons plats.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "Le survol et le clic des en-têtes de colonnes du registre de guilde ne dépassent plus de la ligne d'en-tête plate.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "La barre de filtres du journal de combat partage désormais exactement la largeur et la hauteur de la ligne d'onglets de discussion, au ras du bord du panneau.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "Après une mise à jour, un point clignotant sur l'entrée « Notes de version » signale les nouvelles notes jusqu'à leur première ouverture — pour tout le compte, par version.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "Avec le style Modern, la barre latérale des ensembles d'équipement s'ancre désormais à droite du panneau des caractéristiques, exactement à la hauteur de la fenêtre, au lieu de le chevaucher. Changer de style avec la fenêtre ouverte la déplace immédiatement.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "Les boutons du micro-menu que le jeu masque selon la situation sont de nouveau affichés, la rangée n'a donc plus de trou.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "La barre d'unité par défaut ne transparaît plus sous forme de barre translucide sous la barre personnalisée — elle est désormais masquée complètement et le reste tant que la barre personnalisée est active.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "Tous les boutons du micro-menu ouvrent de nouveau leurs fenêtres — la coquille vidée du micro-menu par défaut avalait invisiblement les clics sur les boutons déplacés.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "Correction d'une erreur d'action bloquée quand la barre de posture se mettait à jour en combat ; la visibilité des boutons de posture ne change plus qu'hors combat, tandis que la teinte des icônes, la recharge et le marqueur actif continuent de se mettre à jour en direct.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "Un module Barres d'action place chaque barre d'action sur son propre cadre déplaçable — barres d'action 1 à 5, barre de posture et barre du familier — chacune positionnée et redimensionnée dans le mode Édition et configurée séparément.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "La barre principale change correctement de page avec les formes de druide, de voleur, de guerrier et de prêtre, et vos raccourcis continuent de fonctionner sur chaque barre, la touche étant affichée sur les boutons.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "Par barre : visibilité (toujours, au survol, en combat ou hors combat), opacité, taille des icônes, boutons par ligne, espacement, disposition verticale, ordre inversé, et masquage du texte des raccourcis ou des macros — avec des tailles de texte réglables pour les raccourcis, les macros, la quantité et les chiffres de recharge.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "Les emplacements vides peuvent être masqués et réapparaissent automatiquement pendant que vous glissez une capacité sur la barre, et une barre peut laisser passer les clics.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "Réglages de recharge et d'apparence pour toutes les barres : assombrissement du balayage de recharge, désaturation des icônes en recharge, coloration des icônes quand la cible est hors de portée, et masquage des infobulles des boutons en permanence ou seulement en combat.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "Une barre d'expérience dédiée avec largeur, hauteur et couleur réglables, superposition de repos et texte de progression — elle remplace la barre par défaut tant qu'elle est activée et se masque au niveau maximal.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "Le micro-menu, la barre des sacs et la barre de performances reposent sur des supports déplaçables, et chacun peut être masqué — tout comme la barre d'expérience par défaut.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "Désactivé par défaut : les barres standard restent intactes tant que vous n'activez pas le module, et la désactivation rend tout en l'état (un /reload rétablit entièrement les barres par défaut).",
    ["The dark button skin now also covers the new action-bar buttons."] = "L'habillage sombre des boutons couvre désormais aussi les nouveaux boutons des barres d'action.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "Un module Barres d'unité personnalisé dessine ses propres barre de vie, barre d'incantation et textes de nom et de vie sur les barres d'unité des ennemis et des PNJ — entièrement configurable, avec un aperçu en direct qui se met à jour à chaque modification.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "Barre de vie avec texture, largeur, hauteur et arrière-plan au choix, et une bordure tracée en lignes fines ou en texture, le tout dans vos propres couleurs.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "Coloration par réaction (hostile, neutre, amical, marqué) et par classe pour les joueurs, plus une coloration de menace selon le rôle pour les tanks et les DPS.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "Anneaux de surbrillance pour la cible et le focus, et une atténuation facultative des barres d'unité qui ne sont pas votre cible.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "Barre d'incantation avec icône et nom du sort, et une couleur distincte pour les incantations impossibles à interrompre.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "Rangées d'auras : vos affaiblissements (ou tous), les améliorations ennemies, et une rangée distincte et bien visible pour les contrôles comme Métamorphose, Peur et Assommer. Une lueur signale les améliorations ennemies que vous pouvez voler ou dissiper.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "Pastilles de points de combo sur votre cible pour les voleurs et les druides en forme de félin.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "Marqueurs de raid (crâne, croix et les autres) avec taille et position réglables.",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "Les barres d'unité alliées peuvent afficher le nom seul, la barre complète ou rien — réglé séparément pour les joueurs et les PNJ — et peuvent afficher le sous-titre d'un PNJ allié sous son nom.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "Un seul module « Habillage sombre » couvre désormais l'habillage sombre des boutons d'action et de WeakAuras ainsi que le mode sombre facultatif qui assombrit les fenêtres par défaut de Blizzard — c'étaient auparavant deux modules distincts. Vos réglages existants sont conservés.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "Les modules d'habillage (habillages, fenêtre du personnage, discussion, liste d'amis, minicarte) forment désormais une seule entrée à onglets, à l'image de l'organisation des autres groupes.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "Les groupes consolidés listent désormais leurs modules dans une colonne verticale avec icônes au lieu d'une rangée d'onglets sur plusieurs lignes — plus lisible quand ils sont nombreux.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "Une page « Notes de version » dans Vue d'ensemble affiche les modifications de chaque version directement en jeu.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "Des noms d'onglets plus propres pour quelques outils : Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "Les compléments de la fenêtre de cible et la bordure d'élite de la fenêtre du joueur forment désormais un seul module nommé « Fenêtres du joueur et de la cible ». Vos réglages existants et l'état activé ou désactivé par personnage sont repris automatiquement.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "Les réglages utilisent désormais par défaut un profil distinct par classe : ce que vous réglez sur une classe ne change plus une autre. Vos réglages actuels sont copiés dans chaque profil de classe, et vous pouvez toujours partager ou épingler des profils comme avant.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "Les messages défilants déclenchés au même moment s'empilent désormais avec un écart au lieu de se chevaucher.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "Correction d'une erreur qui pouvait apparaître quand le combat commençait alors que votre ligne était lancée. Les réglages de son et d'interaction sont désormais rétablis à la fin du combat.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "Texte de temps de la barre d'incantation allégé, barres de recharge qui regroupent leurs rafraîchissements dans les moments chargés, une vérification du journal de combat moins coûteuse pour l'impulsion de recharge, et une vérification de survol de la minicarte allégée.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "Les caractéristiques de sorts sont ordonnées : puissance des sorts, soins, critique des sorts, puis toucher des sorts.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "Les onglets Pêche et Courrier affichent désormais « Angeln » et « Post ».",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "Un menu déroulant de style en haut des options du module. Classic+ conserve l'aspect actuel ; Modern est un nouveau style sombre à fenêtre unique.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern habille toute la fenêtre du personnage en sombre avec une bordure d'accent et un panneau de caractéristiques à droite : un grand niveau d'objet équipé, puis des catégories repliables — caractéristiques, corps à corps, sorts, défense et résistances — avec un détail au survol par caractéristique et un défilement à la molette.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "Avec Modern, les caractéristiques intégrées, les icônes de résistance et les flèches de rotation du modèle sont masquées, et les sous-onglets de réputation, de compétences et de JcJ ainsi que les onglets du bas sont habillés à l'identique. Tout rebascule vers Classic+ en direct et s'adapte au client (caractéristiques de score uniquement là où elles existent).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "Habillage sombre pour une fenêtre d'options de carte du monde, avec son propre interrupteur dans les options d'Habillages d'add-ons.",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "L'horloge se trouve désormais sur la même ligne que la date et la zone au lieu de flotter plus haut.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "Habillage sombre pour un add-on de distribution du butin — ses fenêtres d'attribution et de jets, ses fenêtres de réglages et de vue d'ensemble, et les deux barres de jets et d'enchères toujours visibles reçoivent le panneau maison, la bordure d'accent et le bouton de fermeture plat.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "Habillage sombre pour un suivi d'harmonisation — la fenêtre principale et ses boutons adoptent l'aspect sombre ; les lignes d'état colorées restent telles quelles pour que les couleurs d'état restent lisibles.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "Les deux disposent d'interrupteurs distincts dans les options d'Habillages d'add-ons, à côté des autres.",
    ["NEW:"] = "NOUVEAU :",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "Une seule fenêtre d'inventaire unifiée : tous les sacs dans une même grille, avec bordures de qualité, quantités, recharges, argent et emplacements libres. Déplaçable et redimensionnable.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "Corrige les bugs d'inspection figée (aucune inspection de joueur possible après une fermeture défectueuse ou un délai dépassé). Réinitialisation automatique après expiration, nouvelle tentative automatique quand la fenêtre reste vide, nettoyage à la fermeture d'InspectFrame + commande /inspectreset.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "Une minicarte moderne : ronde avec un anneau sombre épuré et une ligne d'accent, texte de zone et horloge dans un panneau fin, zoom à la molette, déplaçable et redimensionnable. Peut masquer les boutons des autres add-ons jusqu'au survol.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "Barres d'unité personnalisées pour les ennemis et les PNJ, avec aperçu en direct : barre de vie, barre d'incantation, texte de nom et de vie, couleurs de réaction et de classe, surbrillance de la cible et coloration de menace.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "Survolez un emplacement d'équipement pour obtenir une bande compacte des objets compatibles de vos sacs, ou utilisez la touche de modification pour un sélecteur plus grand. Cliquez sur un objet pour l'équiper.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "Déplacez chaque fenêtre VuloUI et les fenêtres par défaut de Blizzard dans un seul éditeur.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "Pêche à une touche : une seule touche lance la ligne, ferre et applique un leurre, puis ramasse automatiquement votre prise.",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "Ajoute un bouton « Tout ouvrir » à votre boîte aux lettres qui récupère toutes les pièces jointes et tout l'argent en un clic.",
    ["Top"] = "Haut",
    ["Bottom"] = "Bas",
    ["Top-Left"] = "Haut gauche",
    ["Top-Right"] = "Haut droite",
    ["Bottom-Left"] = "Bas gauche",
    ["Bottom-Right"] = "Bas droite",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets : tous les bijoux ignorés ou masqués ont été effacés.",
    ["Trinkets usage:"] = "Utilisation de Trinkets :",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket ou /Trinkets : afficher ou masquer la fenêtre",
    ["/trinket reset : reset all settings"] = "/trinket reset : réinitialiser tous les réglages",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : effacer tous les bijoux ignorés ou masqués",
    ["/trinket opt : summon options window"] = "/trinket opt : ouvrir la fenêtre des options",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : verrouiller ou déverrouiller la fenêtre",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (nombre) : définir une échelle exacte",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom nomduprofil : charger un profil sur le bijou du haut ou du bas",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Voulez-vous vraiment réinitialiser Trinkets à son état par défaut et recharger l'interface ?",
    ["Queued: %s"] = "En attente : %s",
    ["Priority"] = "Priorité",
    ["Pause Queue"] = "Suspendre la file",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "Le paramètre doit être 0 pour le bijou du haut ou 1 pour celui du bas.",
    ["No profiles saved yet."] = "Aucun profil enregistré pour l'instant.",
    -- Patch notes 1.37.1
    ["Visuals"] = "Apparence",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "L'option de langue dans Général s'applique désormais vraiment. Elle n'avait silencieusement jamais d'effet : l'addon lisait la langue du client avant le chargement de votre choix enregistré. Après un /reload, chaque libellé, liste déroulante et fenêtre contextuelle suit votre choix.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "La page des notes de mise à jour est traduite dans toutes les langues, y compris toutes les versions précédentes.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "Le panneau des bijoux, sa fenêtre de file d'attente et l'aide /trinket sont également traduits.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "Allemand : seize traductions en double nettoyées, dont cinq se contredisaient.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "Troisième passage sur les chemins de code les plus sollicités : les auras des plaques de nom sont analysées une fois au lieu de quatre, les événements du journal de combat et d'auras s'épargnent une enveloppe de sécurité, les textes des minuteries ne se redessinent que lorsque le nombre affiché change, et plusieurs écouteurs d'arrière-plan dorment tant que leur fonction est désactivée ou masquée. Moins de saccades en raid et en arène.",
    ["The frames can be turned off again without leftovers."] = "Les cadres peuvent de nouveau être désactivés sans laisser de restes.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "Un sort ennemi interrompu affiche désormais brièvement INTERROMPU — il disparaissait auparavant au même instant.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "Les icônes des rendements décroissants se nettoient correctement après avoir basculé le suivi en pleine arène.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "Sept réglages fonctionnels invisibles dans les options sont de nouveau affichés, et plusieurs interrupteurs sans effet sont maintenant branchés.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "Les modules rangent derrière eux à la désactivation : l'assombrissement de portée des totems, la fenêtre d'inspection, le minuteur de file d'attente, le journal de quêtes et les barres de police ne laissent plus de morceaux périmés.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "Trois modules ont reçu leurs propres icônes de barre latérale au lieu de l'image de remplacement, et les Rappels une plus jolie cloche.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "Marqueur de départ de quête (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "Superpose un point d'exclamation jaune sur les objets qui lancent une quête que vous n'avez pas encore acceptée.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555La page d'options '%s' n'a pas pu être construite :|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555Cette page n'a pas pu être construite. Faites /reload et signalez-le si cela persiste.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f ms/image |cff666666(%.1f%% pour nous, pic %.1f ms)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaaL'en-tête indique le temps d'image que coûte VuloClassicUI. Votre client le mesure lui-même, en permanence, sans réglage ni rechargement.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "Classic Era, Hardcore et Season of Discovery",
    ["Under the hood"] = "Sous le capot",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "L'addon se charge de nouveau sans cocher « Charger les AddOns obsolètes ». La mise à jour d'interface de Blizzard de juillet a fait passer ces royaumes à un nouveau numéro de version.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "Correction d'un plantage qui désactivait toute la page du Maître de classe sur Season of Discovery : une seule capacité inconnue du royaume emportait le module entier.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "La bordure d'élite de votre cadre de joueur est de nouveau bien placée. Elle était calée sur l'ancienne disposition du cadre, que cette même mise à jour a remplacée.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "Correction d'une rare avalanche d'erreurs en fin de combat. Le travail de nettoyage de dix-neuf fichiers pouvait être sauté et le chat se remplissait de lignes d'erreur.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "Les fonctions liées au journal de combat (minuteur de coup, pulsation de recharge, textes de combat, suivi d'arène, plaques de nom, indicateur de mana) ne dépendent plus d'un réglage désactivable.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "Un sort ennemi interrompu affiche désormais vraiment l'interruption pendant un instant.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "Les objets qui lancent une quête que vous n'avez pas encore acceptée portent un point d'exclamation jaune, dans les sacs, la banque et le porte-clés.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "Sept des huit traductions livrées ne construisent plus du tout leur table de correspondance. Seule la langue que vous lisez réellement est assemblée, ce qui libère environ un mégaoctet à chaque connexion.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "Mode édition : trois pilotes d'arrière-plan ne tournent plus en permanence, déplacer une fenêtre génère bien moins de déchets, et retrouver une fenêtre est une consultation directe au lieu d'une recherche.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "Désactiver un module le détache maintenant complètement : plusieurs laissaient des écouteurs actifs pour le reste de la session.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "L'indicateur de performance de l'en-tête utilise la mesure toujours active de votre client : ni réglage ni rechargement nécessaires.",
    -- Patch notes 1.37.2
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "Rien de mesuré pour l'instant. Jouez un moment, puis relisez.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "Mesuré sur %.1f s : %.1f ms au total, dont %.2f%% pour nous :",
    ["Measurement off."] = "Mesure désactivée.",
    ["Measurement reset."] = "Mesure réinitialisée.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "Mesure activée. Jouez un moment, puis retapez /vcuiprof pour la lire.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "Page du Maître de classe",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "Correction de la page qui était abandonnée juste après son ouverture, vous renvoyant sur un onglet de classe. Le grimoire réinitialise sa propre page dès que vos sorts changent, et la nôtre se trouve au-delà du dernier onglet réel : c'était donc toujours elle qui sautait. Surtout visible en Season of Discovery, où la gravure modifie sans cesse les sorts.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` mesure le temps d'image que coûte chaque partie de l'addon et affiche une liste. Il est livré désactivé et ne coûte alors rien : le code de mesure n'est mis en place qu'à l'activation. Tapez-le une fois pour démarrer, une seconde fois pour lire.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "Cliquer sur un bouton de bijou alors que l'emplacement est vide ne provoque plus d'erreur. Le raccourci du jeu pour « utiliser l'objet de l'emplacement N » ne tolère plus un emplacement vide depuis la mise à jour d'interface de juillet ; le bouton emprunte donc un autre chemin vers la même action.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "Correction d'une saccade de près de deux images à chaque entrée et sortie de combat, si vous utilisez WeakAuras avec notre habillage WeakAuras activé. Chaque changement de combat repeignait toutes les auras jamais enregistrées — y compris celles absentes de l'écran — avec une apparence inchangée. Les auras ne sont désormais repeintes que si les réglages ou leur taille ont réellement changé. Mesuré : de 28 ms à moins de 2 ms. L'habillage lui-même est inchangé.",
    -- Patch notes 1.39.0
    ["Download"] = "Téléchargement",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "Position de la récupération décroissante – Place la rangée d'un côté ou de l'autre du cadre, avec son propre décalage X et Y",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "La rangée de récupération décroissante ne se pose plus sur l'icône de bijou ou de capacité raciale. Elle était fixée à une distance figée du bord droit, exactement là où se trouve l'icône latérale, si bien que les deux se superposaient une fois activée. La nouvelle valeur par défaut la dégage, et sur le bord gauche la rangée s'étend vers l'extérieur au lieu de traverser le cadre.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "Les icônes de bijou et de capacité raciale sont placées plus loin du cadre ennemi et sont un peu plus petites, si bien que les barres de vie et de mana se lisent comme le centre du cadre au lieu de rivaliser avec une icône sur chaque épaule. Ce sont deux curseurs, vos propres valeurs sont donc conservées.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "Le dossier de l'addon n'embarque plus les outils de compilation ni les fichiers source dont aucun joueur n'a besoin. Les fichiers de licence restent en place.",
    ["The release notes on the distribution pages are written in English now."] = "Les notes de version des pages de distribution sont désormais rédigées en anglais.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "Six langues manquaient sept textes qui n'existaient qu'en allemand. Les neuf sont de nouveau complètes.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "L'aide aux mots-clés de la recherche d'objets était trompeuse en chinois : elle donnait en exemple un nom de type en anglais qu'un client chinois n'aurait jamais trouvé. L'exemple est désormais écrit dans la langue du lecteur.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "Aide au changement de sceau – Une barre de frappe avec la fenêtre de changement marquée et la prochaine action sensée",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "La barre décompte jusqu'à votre prochaine attaque automatique avec deux repères : le vert marque le dernier instant où le second sceau peut encore s'appliquer, le violet indique combien de temps un Jugement tient encore avant lui. La prochaine action est calculée en direct à partir de votre rythme de frappe, du temps de recharge global et des sceaux réellement actifs sur vous — et non d'une rotation figée. Frappe du croisé n'est proposée que tant qu'il reste de la place pour elle et pour le sceau que vous conservez. Le Jugement n'en reçoit volontairement aucune : il consomme le sceau, et un mauvais conseil y coûte plus cher que pas de conseil du tout. Désactivé par défaut.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "Sacs et objets",
    ["Chat & Social"] = "Discussion et social",
    ["Extras"] = "Divers",
    ["Tools"] = "Outils",
    -- Overview page
    ["peak %.1f ms"] = "pic %.1f ms",
    ["%.2f ms"] = "%.2f ms",
    ["%.1f MB"] = "%.1f Mo",
    ["%d KB"] = "%d Ko",
    ["%d of %d"] = "%d sur %d",
    ["moved"] = "déplacées",
    ["Modules"] = "Modules",
    ["Frame time"] = "Temps par image",
    ["Memory"] = "Mémoire",
    ["Windows"] = "Fenêtres",
    ["%d modules are switched off."] = "%d modules sont désactivés.",
    ["The edit mode grid is switched on."] = "La grille du mode édition est activée.",
    ["There are patch notes you have not read yet."] = "Des notes de version n’ont pas encore été lues.",
    ["What would you like to change?"] = "Que souhaitez-vous régler ?",
    ["Worth knowing"] = "Bon à savoir",
    ["Recently visited"] = "Visité récemment",
    -- Talent overrides
    ["active"] = "actifs",
    ["Talent Overrides"] = "Réglages par groupe de talents",
    ["Talent group %d"] = "Groupe de talents %d",
    ["%d settings overridden"] = "%d réglages remplacés",
    ["Forget all overrides for this talent group"] = "Oublier tous les réglages de ce groupe de talents",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Les réglages s’appliquent seuls au changement de groupe de talents. Ce client n’a pas de spécialisations, l’axe est donc le système de double talent.",
    -- Override groups
    ["Talent group %d (%s)"] = "Groupe de talents %d (%s)",
    ["Name for the new group"] = "Nom du nouveau groupe",
    ["Editing as"] = "Édition en tant que",
    ["Yourself"] = "Vous-même",
    ["Manage groups..."] = "Gérer les groupes...",
    ["Owns the current talent group"] = "S'applique au groupe de talents actuel",
    ["Delete this group"] = "Supprimer ce groupe",
    ["No groups yet."] = "Aucun groupe pour l'instant.",
    -- Anchor points
    ["Centre"] = "Centre",
    ["Thin outline"] = "Contour fin",
    ["Bar Setups"] = "Configurations de barre",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "Déplacé de la barre latérale vers les Réglages globaux, dans son propre onglet à côté des Profils. Tes configurations enregistrées sont conservées.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "Elles étaient stockées une fois par profil de classe : sept copies de la même bibliothèque de macros. Elles ne le sont plus qu'une seule fois, ce qui a réduit le fichier de réglages d'un tiers. Les copies identiques sont fusionnées, celles qui diffèrent sont conservées côte à côte.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "La fenêtre de discussion ne revient plus en arrière dès que tu ouvres le mode édition. Un changement de disposition réancre toutes les fenêtres connues du jeu, y compris celles que nous plaçons nous-mêmes.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "Un menu déroulant avec une entrée longue ne déborde plus sur la ligne du dessous.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "La première page montre l'état de ton interface au lieu d'une seconde barre latérale : modules actifs, temps par image et mémoire, fenêtres déplacées et pages consultées en dernier.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "Remplacements de talents – Des groupes nommés conservent leurs propres valeurs pour certains réglages et s'appliquent au changement de spécialisation de talents",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "Un groupe peut aussi nommer une situation : raid, donjon, arène, champ de bataille, en groupe, en solo. Tout ce que tu modifies pendant qu'un groupe est actif y est enregistré, et chaque ligne remplacée est signalée.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "Les curseurs tiennent sur une ligne comme tous les autres réglages, leur valeur peut être saisie au clavier, et les libellés s'alignent dans une colonne mesurée sur toute la page. Une traduction longue ne pousse plus un bloc de valeur dans la colonne voisine ni un bouton hors de sa carte.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "Chaque section démarre repliée : une page longue s'ouvre donc comme une liste de titres.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "La file de remplacement automatique a de nouveau des commandes : ordre, délai et repère de fin, sur la page des bijoux. Elles n'existaient que dans une fenêtre que cet accessoire masque.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "Les icônes de bijoux réapparaissent : sur les boutons, sur le repère de file et sur tes bijoux équipés dès la connexion, au lieu d'attendre un clic.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s n'a pas encore de gestionnaire — c'est un bogue, merci de le signaler.",
    ["%s belongs to %s, which is switched off."] = "%s appartient à %s, qui est désactivé.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffCommandes|r — %d au total. Les grises appartiennent à un module désactivé.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s est également revendiqué par un autre accessoire (%s) — un seul des deux l'emporte.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555Le module des configurations de barre n'est pas chargé.|r",
    ["Bar setup '%s' saved."] = "Configuration de barre '%s' enregistrée.",
    ["Bar setup '%s' deleted."] = "Configuration de barre '%s' supprimée.",
    ["Not in combat — bars can't be changed while fighting."] = "Hors combat — les barres ne peuvent pas être modifiées pendant un combat.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Configuration de barre '%s' chargée : %d emplacements remplis, %d vidés, |cffff8800%d ignorés|r (sort inconnu / objet ou macro manquant).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Configuration de barre '%s' chargée : %d emplacements remplis, %d vidés.",
    ["on"] = "activé",
    ["Overridden settings: %s"] = "Réglages remplacés : %s",
    ["Situation"] = "Situation",
    ["Everywhere"] = "Partout",
    ["Raid instance"] = "Raid",
    ["5-player instance"] = "Donjon (5 joueurs)",
    ["Battleground"] = "Champ de bataille",
    ["In a group"] = "En groupe",
    ["Alone"] = "En solo",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Ne s'applique que dans cette situation. Combinée à une spécialisation de talents, les deux doivent être vraies — et ce groupe l'emporte alors sur un groupe qui ne nomme que la spécialisation.",
    ["Icon"] = "Icône",
    ["No icon"] = "Aucune icône",
    ["Shown in front of the group name in the menu and on the header button."] = "Apparaît devant le nom du groupe dans le menu et sur le bouton d'en-tête.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Désactiver supprime uniquement ce remplacement. Le réglage suit ensuite de nouveau le profil.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "Les configurations de barre sont désormais stockées une seule fois pour tout le compte : %d conservées, %d doublons fusionnés.",
    ["Trinket window settings now live in this addon's own database."] = "Les réglages de la fenêtre des bijoux résident maintenant dans la base de données de cet accessoire.",
    ["Auto queue: top slot"] = "File automatique : emplacement du haut",
    ["Auto queue: bottom slot"] = "File automatique : emplacement du bas",
    ["Auto queue for this slot"] = "File automatique pour cet emplacement",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "Le même interrupteur qu'un alt-clic sur l'emplacement. Activée, la file échange ce bijou en combat en suivant l'ordre ci-dessous.",
    ["Order"] = "Ordre",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "La file parcourt cette liste depuis le haut. Choisis une entrée pour la déplacer ou modifier ses réglages.",
    ["- empty -"] = "- vide -",
    ["— queue stops here —"] = "— la file s'arrête ici —",
    ["Add from bags"] = "Ajouter depuis les sacs",
    ["Adds a trinket you are carrying to the end of this list."] = "Ajoute à la fin de cette liste un bijou que tu transportes.",
    ["Swap delay"] = "Délai d'échange",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Secondes pendant lesquelles ce bijou reste équipé avant que la file ne l'échange à nouveau. 0 = aucune attente.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Ce bijou est équipé avant ceux du dessus dès qu'il est prêt.",
    ["Pause while equipped"] = "Suspendre tant qu'il est équipé",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Tant que ce bijou est porté, la file reste immobile — pour un bijou dont tu ne veux pas écourter l'effet.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaAstuce : clic gauche sur un emplacement pour utiliser le bijou, clic droit pour la liste. Alt-clic arme la file automatique de cet emplacement.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d instantané(s) portaient le même nom avec un contenu différent et ont été conservés sous un nouveau nom.",
    ["GAP"] = "ÉCART",
    ["Distance from that edge, in pixels. 0 is flush."] = "Distance par rapport à ce bord, en pixels. 0 = au ras.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Ancre cette fenêtre sur ce côté de la cible et l'y centre. 'Centré' ne la déplace pas — elle ne fait que suivre. L'écart est maintenu de bord à bord, il survit donc au redimensionnement de l'une ou l'autre fenêtre.",
    ["waiting for a swing"] = "en attente d'un coup",
    ["  -  lag %.0fms"] = "  -  latence %.0fms",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Aucun sceau depuis lequel basculer. Seuls le Sceau de commandement et le Sceau de droiture s'appliquent encore à un coup après avoir été remplacés : il faut connaître l'un des deux.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Un seul sceau connu. Il en faut un second vers lequel basculer.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800Impossible de basculer depuis le sceau que vous gardez. Seuls le Sceau de commandement et le Sceau de droiture s'appliquent encore au coup qui les remplace.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Seuls le Sceau de commandement et le Sceau de droiture conviennent ici : ce sont les deux dont l'effet s'applique encore au coup qui les remplace.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "Les réglages des barres de nom ont été remplacés. Change de profil pour retrouver les précédents.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "Remplace les réglages des barres de nom de ce profil par un rendu large, plat et sombre. Les autres profils ne sont pas touchés.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaaRemplace les réglages des barres de nom de ce profil par un rendu large, plat et sombre. Les autres profils ne sont pas touchés.|r",
    ["Apply the wide, flat look"] = "Appliquer le rendu large et plat",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Positions principales",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaUne chose par emplacement. Ce que tu donnes à un emplacement est retiré à celui qui le portait.|r",
    ["Debuffs"] = "Affaiblissements",
    ["Buffs"] = "Améliorations",
    ["Crowd control"] = "Contrôle de foule",
    ["Your own debuffs"] = "Tes propres affaiblissements",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "Lueur à faible santé",
    ["A coloured ring around the bar once the unit drops below the mark."] = "Un anneau coloré autour de la barre dès que la cible passe sous le repère.",
    ["Glow below (%)"] = "Lueur en dessous de (%)",
    ["Low health colour"] = "Couleur à faible santé",
    ["Glow in the aura's own school colour"] = "Briller dans la couleur d'école de l'aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Magie bleu, malédiction violet, maladie orange, poison vert — au lieu d’une seule couleur pour tout.",
    -- Absorptionsstil
    ["Absorb style"] = "Style d'absorption",
    ["Flat colour"] = "Couleur unie",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "Afficher la cible du sort",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "La cible actuelle du lanceur, à côté de la barre d'incantation. Ton propre nom est coloré.",
    ["Cast target size"] = "Taille de la cible du sort",
    -- Zielpfeile
    ["Arrows beside your target"] = "Flèches à côté de ta cible",
    ["Two arrows pointing in at the target's bar, one on each side."] = "Deux flèches pointant vers la barre de la cible, une de chaque côté.",
    ["Arrow size"] = "Taille des flèches",
    ["Arrow distance"] = "Distance des flèches",
    ["Arrow colour"] = "Couleur des flèches",
    -- Fokus-Merkzeichen
    ["Mark on the focus plate"] = "Marque sur la barre du focus",
    ["A short text on your focus target's plate. A ring says this one is special; the mark says which."] = "Un texte court sur la barre de ta cible de focus. Un anneau dit que celle-ci est spéciale ; la marque dit laquelle.",
    ["Mark text"] = "Texte de la marque",
    ["Mark position"] = "Position de la marque",
    ["Mark size"] = "Taille de la marque",
    -- Kleine Plaketten
    ["Back to the small plates"] = "Revenir aux petites barres",
    ["Puts the same settings back to the small plates this addon ships with."] = "Remet les mêmes réglages sur les petites barres livrées avec cet accessoire.",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaGardez le Sceau de commandement, puis lancez le second sceau dans la dernière fraction de seconde avant votre attaque automatique : ce coup portera les deux. En dessous du niveau 64, le second sceau est celui de Droiture ; à partir de là, Sang et Martyr le remplacent.|r",
    ["|cffaaaaaaThe bar counts down to the swing in zones: |cff5c8aebblue|r is free for a filler, |cffd93636red|r is the stretch where a cast would still be on the global cooldown when the window opens, and |cff33ff66green|r is the twist window. The last mark inside the green is the late twist, which leaves room for a judgement in front of the seal.|r"] = "|cffaaaaaaLa barre décompte jusqu'au coup par zones : |cff5c8aebbleu|r est libre pour un sort de remplissage, |cffd93636rouge|r est la portion où un lancement serait encore en temps de recharge global à l'ouverture de la fenêtre, et |cff33ff66vert|r est la fenêtre de bascule. La dernière marque dans le vert est la bascule tardive, qui laisse la place à un jugement devant le sceau.|r",
    ["Late twist window (seconds)"] = "Fenêtre de bascule tardive (secondes)",
    ["The tail of the twist window, marked separately. Twisting that late still leaves room for a judgement in front of the seal. Set it as long as the twist window to hide the mark."] = "La fin de la fenêtre de bascule, marquée à part. Basculer aussi tard laisse encore la place à un jugement devant le sceau. Réglez-la sur la même durée que la fenêtre de bascule pour masquer la marque.",
    ["Second cue for the late window"] = "Second signal pour la fenêtre tardive",
    ["A different sound at the late twist mark, so the two ends of the window can be told apart without looking at the bar."] = "Un son différent à la marque de bascule tardive, pour distinguer les deux extrémités de la fenêtre sans regarder la barre.",
    ["Shade the zones"] = "Colorer les zones",
    ["Tints the part of the swing still to come in the colour of the zone it runs into."] = "Teinte la partie du coup encore à venir dans la couleur de la zone où elle arrive.",
    ["Show the marks"] = "Afficher les marques",
    ["The three boundary lines: danger zone, twist window, late twist."] = "Les trois lignes de limite : zone de danger, fenêtre de bascule, bascule tardive.",
    ["Show seal indicators"] = "Afficher les indicateurs de sceau",
    ["The seals currently on you and how long they last, right of the bar. Both show while the twist is in -- that overlap is the pay-off."] = "Les sceaux actuellement sur vous et leur durée restante, à droite de la barre. Les deux apparaissent pendant la bascule : ce chevauchement est le gain.",
    ["Seal icon size"] = "Taille des icônes de sceau",
    ["Head start for the prompt (ms)"] = "Avance du signal (ms)",
    ["Shows the twist prompt and plays its cue this far before the window actually opens, so there is time to see it and press. The colours on the bar stay exact."] = "Affiche le signal de bascule et joue son son ce laps de temps avant l'ouverture réelle de la fenêtre, pour laisser le temps de le voir et d'appuyer. Les couleurs de la barre restent exactes.",
    ["auto"] = "Auto",
    ["Twist only"] = "Bascule seule",
    ["Rotation"] = "Rotation",
    ["Show the rotation helper"] = "Afficher l'aide de rotation",
    ["A row of steps above the bar: which sequence fits your weapon and haste, and where in it you are. It steps forward on what you actually cast and on your swings."] = "Une rangée d'étapes au-dessus de la barre : quelle séquence correspond à votre arme et à votre hâte, et où vous en êtes. Elle avance selon ce que vous lancez réellement et selon vos coups.",
    ["Sequence"] = "Séquence",
    ["Automatic follows your attack speed and spell haste, which is what decides how many twists fit between two strikes. Pick one by hand to drill a single sequence."] = "Automatique suit votre vitesse d'attaque et votre hâte de sorts, qui déterminent combien de bascules tiennent entre deux frappes. Choisissez-en une à la main pour travailler une seule séquence.",
    ["Rotation icon size"] = "Taille des icônes",
    ["Sound when the twist lands"] = "Son quand la bascule réussit",
    ["Hit sound"] = "Son de réussite",
    ["Listen"] = "Écouter",
    ["Chime"] = "Carillon",
    ["Raid warning"] = "Avertissement de raid",
    ["Ready check"] = "Vérification de préparation",
    ["Click"] = "Clic",
    -- Patch notes 1.41.0
    ["Moving a frame could throw a blocked-action error if you happened to be in combat while the frames were built. The keyboard is only taken over once a mover is on screen."] = "Déplacer une fenêtre pouvait provoquer une erreur d'action bloquée si tu étais en combat pendant la construction des fenêtres. Le clavier n'est repris qu'une fois un déplaceur affiché.",
    ["The trinket window's settings were being written to the saved file a second time under their old names. They are stored once now."] = "Les réglages de la fenêtre des bijoux étaient écrits une seconde fois dans le fichier de sauvegarde sous leurs anciens noms. Ils ne le sont plus qu’une fois.",
    ["42 texts existed in German only, among them the whole talent override interface and the trinket queue. All nine languages are complete again."] = "42 textes n’existaient qu’en allemand, dont toute l’interface des remplacements de talents et la file des bijoux. Les neuf langues sont de nouveau complètes.",
    ["Main positions – Six slots around the plate, each holding one thing: debuffs, buffs, crowd control or your own damage-over-time"] = "Positions principales – Six emplacements autour de la barre, chacun tenant une seule chose : affaiblissements, améliorations, contrôle de foule ou tes propres dégâts sur la durée",
    ["Glow when low on health – A coloured ring once the unit drops past your mark"] = "Lueur à faible santé – Un anneau coloré dès que la cible passe sous ton repère",
    ["Arrows beside your target – Two arrows pointing in at the bar"] = "Flèches à côté de ta cible – Deux flèches pointant vers la barre des deux côtés",
    ["Mark on the focus plate – A short text, so target and focus stay apart at a glance"] = "Marque sur la barre du focus – Un texte court pour distinguer cible et focus en un coup d’œil",
    ["Preset – One click for a wide, flat, dark look, and one to put the small plates back"] = "Modèle – Un clic pour un rendu large, plat et sombre, et un autre pour revenir aux petites barres",
    ["Two of the six slots sit beside the plate as a column, which was not possible before. And two rows can no longer land on top of each other: giving a slot something takes it away from the slot that had it."] = "Deux des six emplacements se placent à côté de la barre en colonne, ce qui était impossible avant. Et deux rangées ne peuvent plus se superposer : ce que tu donnes à un emplacement est retiré à celui qui le portait.",
    ["The cast bar can name who the cast is aimed at, your own name coloured."] = "La barre d’incantation peut nommer la cible du sort, ton propre nom étant coloré.",
    ["Twist zones – The swing bar answers what you may press now instead of counting down"] = "Zones de twist – La barre de swing répond à ce que tu peux presser maintenant au lieu de décompter",
    ["Rotation helper – A short sequence rather than a single next step, worked out from your weapon and cast speed"] = "Aide de rotation – Une courte séquence plutôt qu’une seule étape suivante, calculée depuis ta vitesse d’arme et d’incantation",
    ["The seal you twist into may be any other seal, not only the two that arrive at level 64."] = "Le sceau vers lequel tu bascules peut être n’importe quel autre sceau, pas seulement les deux qui arrivent au niveau 64.",
    ["Sections no longer fold away. Long pages fold at the gear on a row instead, which says something a section expander never could: the rows behind it belong to the switch it sits on."] = "Les sections ne se replient plus. Les pages longues se replient sur la roue dentée d’une ligne, qui dit ce qu’un repli de section n’a jamais dit : les lignes derrière appartiennent à l’interrupteur sur lequel elle se trouve.",
    ["Controls line up down a page now, and a switch sits in the middle of its row."] = "Les contrôles sont alignés le long de la page, et un interrupteur se place au milieu de sa ligne.",
    -- Vier Nachzuegler
    ["Darken enemies out of combat"] = "Assombrir les ennemis hors combat",
    ["Dims enemies that are not fighting anyone, so the ones that are stand out. Never your own target."] = "Atténue les ennemis qui ne combattent personne, pour faire ressortir ceux qui combattent. Jamais ta propre cible.",
    ["Darken to (%)"] = "Assombrir à (%)",
    ["Cast bars in front of other plates"] = "Barres d'incantation devant les autres barres",
    ["In a pull the plates overlap and a cast bar can end up behind the plate in front of it."] = "Lors d’un pull les barres se chevauchent et une barre d’incantation peut passer derrière celle de devant.",
    ["Highlight strength"] = "Intensité de la surbrillance",
    ["Hitbox width (%)"] = "Largeur de la zone cliquable (%)",
    ["Clickable plate area. 100 leaves the game's own size untouched. Stored in the profile."] = "Zone cliquable de la barre. 100 laisse la taille du jeu intacte. Enregistré dans le profil.",
    ["Hitbox height (%)"] = "Hauteur de la zone cliquable (%)",
    -- Wechsel verloren
    -- Gewehrschuss
    ["Rifle"] = "Coup de fusil",
    -- Aktionszeile
    ["Action text size"] = "Taille du texte d'action",
    ["The line that names what to press. 0 follows the general text size."] = "La ligne qui dit quoi presser. 0 suit la taille de texte générale.",
    -- Tempo- und Siegel-Timer-Groesse
    ["Seal timer text size"] = "Taille du minuteur de sceau",
    ["The countdown on the seal icons. 0 scales it with the icon."] = "Le décompte sur les icônes de sceau. 0 le met à l’échelle de l’icône.",
    -- Warnzeile
    ["Warning text size"] = "Taille du texte d'avertissement",
    ["The red and yellow warnings on the bar. 0 follows the action text size."] = "Les avertissements rouges et jaunes sur la barre. 0 suit la taille du texte d’action.",
    -- Bedingungen je Eintrag
    ["Narrows this icon to a number of stacks, or to the last seconds before it runs out."] = "Limite cette icône à un nombre de cumuls, ou aux dernières secondes avant expiration.",
    ["Only from stacks"] = "Seulement à partir de cumuls",
    ["0 = any number of stacks."] = "0 = n’importe quel nombre de cumuls.",
    ["Only in the last seconds"] = "Seulement dans les dernières secondes",
    ["0 = at any time. Otherwise the icon appears only this close to running out."] = "0 = à tout moment. Sinon l’icône n’apparaît qu’aussi près de l’expiration.",
    -- Einheit je Gruppe
    ["Watch this unit"] = "Surveiller cette unité",
    ["Whose auras this group reads. The default is what the group type has always used."] = "Les auras de qui ce groupe lit. Par défaut, ce que le type de groupe a toujours utilisé.",
    ["You"] = "Toi",
    ["Target"] = "Cible",
    ["Focus"] = "Focus",
    -- Nur eigene Auren
    ["Only what I cast myself"] = "Seulement ce que je lance moi-même",
    ["Off counts the aura no matter who put it there - for a raid debuff that anyone may apply."] = "Désactivé, l’aura compte quel que soit son auteur — pour un affaiblissement de raid que n’importe qui peut poser.",
    -- Sortierung
    ["Fixed keeps the order you added them in. The other two reorder live by what is left."] = "Fixe garde l’ordre dans lequel tu les as ajoutés. Les deux autres réordonnent en direct selon le temps restant.",
    ["As added"] = "Dans l’ordre d’ajout",
    ["Least time left first"] = "Temps restant le plus court d’abord",
    ["Most time left first"] = "Temps restant le plus long d’abord",
    ["Practice"] = "Entraînement",
    ["|cffaaaaaaA swing clock that runs on its own, with no target and nothing spent. Press your bound keys against it and every swing is graded: the twist landed, it was too early, or nothing was attempted. The seal model is the real one -- a replaced seal keeps resolving for 0.4 seconds -- so the timing you learn here is the timing that works.|r"] = "|cffaaaaaaUne horloge de coup qui tourne toute seule, sans cible et sans rien dépenser. Appuyez sur vos touches assignées face à elle et chaque coup est noté : le twist est passé, il était trop tôt, ou rien n'a été tenté. Le modèle des sceaux est le vrai -- un sceau remplacé continue de se résoudre pendant 0,4 seconde -- si bien que le timing appris ici est celui qui fonctionne.|r",
    ["Start / stop practice"] = "Démarrer / arrêter l'entraînement",
    ["Stop practice"] = "Arrêter l'entraînement",
    ["Simulated weapon speed"] = "Vitesse d'arme simulée",
    ["0 uses whatever you have equipped. Any other value drills a speed you do not own yet, which is how you find out that the weapon you are saving for needs a different sequence."] = "0 utilise ce que vous avez équipé. Toute autre valeur fait travailler une vitesse que vous ne possédez pas encore, et c'est ainsi que l'on découvre que l'arme que vous convoitez demande une autre séquence.",
    ["Spell queue window (ms)"] = "Fenêtre de file d'attente des sorts (ms)",
    ["A key pressed this far before the global cooldown ends is held and fires the moment it does, exactly as the client does it. Practising without it teaches a rhythm the game never asks for."] = "Une touche pressée à cette avance avant la fin du temps de recharge global est retenue et se déclenche à l'instant où il se termine, exactement comme le fait le client. S'entraîner sans elle enseigne un rythme que le jeu ne demande jamais.",
    ["Result text size"] = "Taille du texte de résultat",
    ["Result text duration (seconds)"] = "Durée du texte de résultat (secondes)",
    ["Landed colour"] = "Couleur de réussite",
    ["Missed colour"] = "Couleur d'échec",
    ["Show the fight timeline"] = "Afficher la frise du combat",
    ["Every swing and every cast on one strip against a ruler. The ruler is the point: without it you can see that two swings were close together but not how close, which is the only number practice is about."] = "Chaque coup et chaque incantation sur une seule bande, face à une règle graduée. La règle est l'essentiel : sans elle, vous voyez que deux coups étaient proches, mais pas à quel point, et c'est le seul chiffre dont l'entraînement s'occupe.",
    ["Timeline width"] = "Largeur de la frise",
    ["Timeline pixels per second"] = "Pixels par seconde de la frise",
    ["TWIST"] = "TWIST",
    ["MISS"] = "RATÉ",
    ["TOO EARLY"] = "TROP TÔT",
    ["speed %.2fs  -  GCD %.2fs  -  %d of %d"] = "vitesse %.2fs  -  GCD %.2fs  -  %d sur %d",
    ["|cffffffffPRACTICE|r"] = "|cffffffffENTRAÎNEMENT|r",
    ["|cffffffffRESULT|r"] = "|cffffffffRÉSULTAT|r",
    ["|cffffffffTIMELINE|r"] = "|cffffffffFRISE|r",
    ["|cffffcc33Twist practice|r"] = "|cffffcc33Entraînement au twist|r",
    ["Practice needs two seals: pick them under Seals first."] = "L'entraînement demande deux sceaux : choisissez-les d'abord sous Sceaux.",
    ["Practice mode on. Press your bound keys; the swing runs on its own."] = "Mode entraînement activé. Appuyez sur vos touches assignées ; le coup tourne tout seul.",
    ["Practice mode off. %d of %d swings carried the twist."] = "Mode entraînement désactivé. %d coups sur %d ont porté le twist.",
    ["Bloodlust"] = "Furie sanguinaire",
    ["Haste potion"] = "Potion de hâte",
    ["Abacus"] = "Abaque",
    ["Time warp"] = "Distorsion temporelle",
    ["Crusader Strike"] = "Frappe du croisé",
    ["Judgement"] = "Jugement",
    ["Cast the held seal"] = "Lancer le sceau maintenu",
    ["Cast the twist seal"] = "Lancer le sceau de twist",
    ["Filler"] = "Remplissage",
    ["Start / stop attack"] = "Démarrer / arrêter l'attaque",
    ["wait"] = "attendre",
    ["Next action"] = "Action suivante",
    ["|cffffffffNEXT ACTION|r"] = "|cffffffffACTION SUIVANTE|r",
    ["Next action mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Déplacement de l'action suivante actif. |cff9b6cffFaites glisser le cadre violet|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Cliquez à nouveau sur « Déverrouiller / Tester » pour terminer.",
    ["Next action mover disabled."] = "Déplacement de l'action suivante désactivé.",
    ["|cffaaaaaaAn icon of the one thing to press, wherever you want it. It answers the same question as the line under the bar -- the three switches below feed both, so the word and the picture can never disagree.|r"] = "|cffaaaaaaUne icône de la seule chose à presser, là où vous la voulez. Elle répond à la même question que la ligne sous la barre -- les trois options ci-dessous alimentent les deux, si bien que le mot et l'image ne peuvent jamais se contredire.|r",
    ["Show the next action guide"] = "Afficher le guide d'action suivante",
    ["When to show it"] = "Quand l'afficher",
    ["Show a hold instead of nothing"] = "Afficher une attente plutôt que rien",
    ["While the right move is to press nothing on purpose -- the twist is coming and anything else would cost it -- the guide keeps showing the seal, drained and outlined. An empty box says the same thing much less clearly."] = "Tant que le bon geste est de ne rien presser volontairement -- le twist arrive et tout le reste le coûterait -- le guide continue d'afficher le sceau, délavé et cerné d'un contour. Un cadre vide dit la même chose bien moins clairement.",
    ["Suggest Judgement"] = "Suggérer Jugement",
    ["Judging consumes the seal, so it is only ever offered with room to re-seal afterwards. Off by default: a mistimed judgement costs more than no suggestion at all."] = "Juger consomme le sceau : il n'est donc proposé que s'il reste la place de re-sceller ensuite. Désactivé par défaut, car un jugement mal calé coûte plus cher que pas de suggestion du tout.",
    ["Suggest a filler"] = "Suggérer un remplissage",
    ["Consecration, or Exorcism where the target can take it, in the stretch of the swing that is free for it. Exorcism is offered by asking the client whether the spell can be aimed at your target, which is right in every language."] = "Consécration, ou Exorcisme là où la cible y est sensible, dans la portion du coup qui est libre pour cela. Exorcisme est proposé en demandant au client si le sort peut viser votre cible, ce qui reste juste dans toutes les langues.",
    ["Consecration mana floor (%)"] = "Seuil de mana pour Consécration (%)",
    ["Below this share of your mana the filler is not worth it."] = "En dessous de cette part de votre mana, le remplissage n'en vaut pas la peine.",
    ["Exorcism mana floor (%)"] = "Seuil de mana pour Exorcisme (%)",
    ["Longest Crusader Strike delay (ms)"] = "Délai maximal de Frappe du croisé (ms)",
    ["Once leaving the strike any longer than this would waste it, it stops being a suggestion and becomes the answer. Measured against the earliest moment you could actually cast it, not against now."] = "Dès que retarder la frappe au-delà de cette durée la gâcherait, elle cesse d'être une suggestion et devient la réponse. Mesuré à partir du premier instant où vous pourriez réellement la lancer, et non à partir de maintenant.",
    ["Twist!"] = "Twist !",
    ["|cffffffffTWIST TEXT|r"] = "|cffffffffTEXTE TWIST|r",
    ["Twist text mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Déplacement du texte de twist actif. |cff9b6cffFaites glisser le cadre violet|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Cliquez à nouveau sur « Déverrouiller / Tester » pour terminer.",
    ["Twist text mover disabled."] = "Déplacement du texte de twist désactivé.",
    ["Twist landed"] = "Twist réussi",
    ["|cffaaaaaaAll three cues below wait for PROOF, not for a prediction. A swing has to land with both seals up, and the held seal's own damage has to follow it in the combat log. Nothing fires without that second line -- a confirmation that is right most of the time is one you cannot practise against.|r"] = "|cffaaaaaaLes trois signaux ci-dessous attendent une PREUVE, pas une prédiction. Un coup doit toucher avec les deux sceaux actifs, et les dégâts propres au sceau maintenu doivent le suivre dans le journal de combat. Rien ne se déclenche sans cette seconde ligne -- une confirmation juste la plupart du temps est une confirmation contre laquelle on ne peut pas s'entraîner.|r",
    ["Sound channel"] = "Canal sonore",
    ["Master"] = "Principal",
    ["Sound effects"] = "Effets sonores",
    ["Master ignores the sound effects slider, which is what a confirmation wants: it is feedback about the fight rather than part of it."] = "Le canal principal ignore le curseur des effets sonores, ce qui convient à une confirmation : elle est un retour sur le combat plutôt qu'une partie de celui-ci.",
    ["The sniper and rifle cracks are bundled; the rest are the client's own cues. Below them stand any sounds other addons have registered as shared media."] = "Les détonations de sniper et de fusil sont fournies avec ; le reste provient des signaux du client. En dessous figurent les sons que d'autres modules ont enregistrés comme médias partagés.",
    ["Sniper"] = "Sniper",
    ["Level up"] = "Passage de niveau",
    ["Quest complete"] = "Quête terminée",
    ["Bonus objective"] = "Objectif bonus",
    ["Map ping"] = "Signal sur la carte",
    ["Glow on the bar when the twist lands"] = "Halo sur la barre quand le twist passe",
    ["Glow style"] = "Style de halo",
    ["Pixel border"] = "Bordure de pixels",
    ["Autocast ring"] = "Anneau d'incantation automatique",
    ["Pixel border traces the bar's own outline at any width. Autocast pins the client's own ring to the four corners, so it stays a ring however wide the bar gets."] = "La bordure de pixels suit le contour même de la barre, quelle que soit sa largeur. L'anneau d'incantation automatique fixe l'anneau du client aux quatre coins, si bien qu'il reste un anneau quelle que soit la largeur de la barre.",
    ["Glow colour"] = "Couleur du halo",
    ["Glow duration (seconds)"] = "Durée du halo (secondes)",
    ["Text when the twist lands"] = "Texte quand le twist passe",
    ["A line somewhere on screen, with its own position. Useful where the bar is in the corner of the eye and the confirmation should be in the middle of it."] = "Une ligne quelque part à l'écran, avec sa propre position. Utile quand la barre se trouve du coin de l'œil et que la confirmation doit se trouver au centre du regard.",
    ["Text font"] = "Police du texte",
    ["Text outline"] = "Contour du texte",
    ["Text colour"] = "Couleur du texte",
    ["Text duration (seconds)"] = "Durée du texte (secondes)",
    ["|cffffffffSEALS|r"] = "|cffffffffSCEAUX|r",
    ["Seal indicator mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Test' again to finish."] = "Déplacement de l'indicateur de sceaux actif. |cff9b6cffFaites glisser le cadre violet|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Cliquez à nouveau sur « Déverrouiller / Tester » pour terminer.",
    ["Seal indicator mover disabled."] = "Déplacement de l'indicateur de sceaux désactivé.",
    ["Match the bar height"] = "Aligner sur la hauteur de la barre",
    ["Sizes the icons to the bar instead of to their own setting, so the pair keeps lining up with it when the bar height changes."] = "Dimensionne les icônes d'après la barre plutôt que d'après leur propre réglage, de sorte que la paire reste alignée sur elle quand la hauteur de la barre change.",
    ["Ignored while the icons match the bar height."] = "Ignoré tant que les icônes s'alignent sur la hauteur de la barre.",
    ["Seal icon spacing"] = "Espacement des icônes de sceau",
    ["Centre the icons"] = "Centrer les icônes",
    ["Keeps the midpoint of the pair still when the second seal appears or falls off. Left-aligned keeps the first icon still instead, which is what an attached pair wants -- that edge is the bar."] = "Maintient le milieu de la paire immobile quand le second sceau apparaît ou disparaît. L'alignement à gauche immobilise plutôt la première icône, ce qui convient à une paire attachée -- ce bord-là, c'est la barre.",
    ["Show the cooldown sweep"] = "Afficher le balayage de recharge",
    ["The client's own sweep across the icon. It says the same thing as the number under it, but it says it without being read."] = "Le balayage du client sur l'icône. Il dit la même chose que le chiffre en dessous, mais il le dit sans avoir à être lu.",
    ["Seal timer colour"] = "Couleur du minuteur de sceau",
    ["Detach from the bar"] = "Détacher de la barre",
    ["Gives the pair its own position anywhere on screen. They stay tied to the bar in every other way: when it is hidden, they are too."] = "Donne à la paire sa propre position n'importe où à l'écran. Elles restent liées à la barre pour tout le reste : quand elle est masquée, elles le sont aussi.",
    ["Twist lost"] = "Twist perdu",
    ["Swing ready -- restart your attack"] = "Coup prêt -- relancez votre attaque",
    ["(none available)"] = "(aucun disponible)",
    ["Solid"] = "Uni",
    ["Attack speed"] = "Vitesse d'attaque",
    ["Swing timer"] = "Minuteur de coup",
    ["Latency (ms)"] = "Latence (ms)",
    ["Global cooldown left"] = "Temps de recharge global restant",
    ["Nothing"] = "Rien",
    ["Left readout"] = "Affichage de gauche",
    ["What the left end of the bar shows. Attack speed turns into the warning colour below two global cooldowns per swing -- under that the twist and the seal going back up no longer both fit, so wait for the cooldown before twisting."] = "Ce qu'affiche l'extrémité gauche de la barre. La vitesse d'attaque passe à la couleur d'avertissement en dessous de deux temps de recharge globaux par coup -- en dessous, le twist et le sceau remis en place ne tiennent plus tous les deux, il faut donc attendre la recharge avant de faire un twist.",
    ["Right readout"] = "Affichage de droite",
    ["Readout text size"] = "Taille du texte d'affichage",
    ["The two numbers inside the bar. 0 follows the general text size."] = "Les deux chiffres à l'intérieur de la barre. 0 suit la taille de texte générale.",
    ["Global cooldown bar texture"] = "Texture de la barre de recharge globale",
    ["Border"] = "Bordure",
    ["Solid draws four flat edges in the colour below. Texture takes an edge file from shared media, which is what a border from another interface pack looks like."] = "Uni dessine quatre bords plats dans la couleur ci-dessous. Texture prend un fichier de bordure dans les médias partagés, ce qui donne l'aspect d'une bordure venue d'un autre habillage d'interface.",
    ["Only used while the border is set to texture."] = "Utilisé uniquement lorsque la bordure est réglée sur texture.",
    ["Border width"] = "Largeur de la bordure",
    ["Marker texture"] = "Texture du repère",
    ["Marker width"] = "Largeur du repère",
    ["Font colour"] = "Couleur de la police",
    ["Frame strata"] = "Strate du cadre",
    ["Which layer of the interface the helper sits in. Raise it to lift the bar over another addon that draws in the same place."] = "La couche de l'interface dans laquelle l'assistant se place. Augmentez-la pour faire passer la barre au-dessus d'un autre module qui dessine au même endroit.",
    ["Draw level"] = "Niveau de dessin",
    ["The order inside the chosen layer. Higher draws on top."] = "L'ordre à l'intérieur de la couche choisie. Plus la valeur est élevée, plus le dessin passe au-dessus.",
    ["Colour the bar by"] = "Colorer la barre selon",
    ["The zone the swing is in"] = "La zone du coup en cours",
    ["The seal you are carrying"] = "Le sceau que vous portez",
    ["Zones colour the fill by the stretch of the swing you are in, which is what this helper is built around. Seal colours it by what you are carrying, which is the faster read once the timing is in your fingers. Either way the special colours below outrank the choice."] = "Les zones colorent le remplissage d'après la portion du coup où vous vous trouvez, ce autour de quoi cet assistant est bâti. Le sceau le colore d'après ce que vous portez, ce qui se lit plus vite une fois le timing dans les doigts. Dans les deux cas, les couleurs spéciales ci-dessous priment sur ce choix.",
    ["Seal of Command"] = "Sceau de commandement",
    ["Seal of Righteousness"] = "Sceau de piété",
    ["Seal of Blood / the Martyr"] = "Sceau de sang / du martyr",
    ["Seal of Vengeance"] = "Sceau de vengeance",
    ["Seal of the Crusader"] = "Sceau du croisé",
    ["Seal of Justice"] = "Sceau de justice",
    ["Seal of Light"] = "Sceau de Lumière",
    ["Seal of Wisdom"] = "Sceau de sagesse",
    ["No twist possible"] = "Aucun twist possible",
    ["The fill while this swing's twist is already gone, and the tail of the swing a cast can no longer reach."] = "Le remplissage lorsque le twist de ce coup est déjà perdu, ainsi que la fin du coup qu'une incantation ne peut plus atteindre.",
    ["Warning"] = "Avertissement",
    ["The warnings on the bar, and the attack speed once the weapon is too fast to twist with."] = "Les avertissements sur la barre, et la vitesse d'attaque dès que l'arme devient trop rapide pour faire un twist.",
    ["Twisting"] = "Twist en cours",
    ["The fill while both seals are up: the twist is in and this swing carries it."] = "Le remplissage tant que les deux sceaux sont actifs : le twist est en place et ce coup le porte.",
    ["Default"] = "Par défaut",
    ["The fill with no seal up and between swings."] = "Le remplissage sans aucun sceau actif et entre deux coups.",
    ["Global cooldown"] = "Temps de recharge global",
    ["Deadzone"] = "Zone morte",
    ["Twist window padding"] = "Marge de la fenêtre de twist",
    ["Pulls the twist window earlier so the cast still reaches the server inside it. Dynamic follows your calibrated latency; fixed is a number you choose yourself."] = "Avance la fenêtre de twist pour que l'incantation atteigne encore le serveur à l'intérieur de celle-ci. Dynamique suit votre latence calibrée ; fixe est une valeur que vous choisissez vous-même.",
    ["Fixed twist padding (ms)"] = "Marge de twist fixe (ms)",
    ["Only used while the padding mode is set to fixed."] = "Utilisé uniquement lorsque le mode de marge est réglé sur fixe.",
    ["Dynamic (follows latency)"] = "Dynamique (suit la latence)",
    ["Fixed"] = "Fixe",
    ["Latency"] = "Latence",
    ["|cffaaaaaaThe round trip your client reports is not the delay a twist has to beat: the client adds a slice of its own, so the figure everything below works from is (world latency x multiplier) + offset. Raise the multiplier if you keep missing twists that looked in time.|r"] = "|cffaaaaaaL'aller-retour rapporté par votre client n'est pas le délai qu'un twist doit battre : le client ajoute sa propre part, si bien que le chiffre dont tout ce qui suit se sert vaut (latence monde x multiplicateur) + décalage. Augmentez le multiplicateur si vous ratez sans cesse des twists qui semblaient dans les temps.|r",
    ["Latency multiplier"] = "Multiplicateur de latence",
    ["Latency offset (ms)"] = "Décalage de latence (ms)",
    ["Shade the deadzone"] = "Ombrer la zone morte",
    ["The tail of the swing a cast can no longer cross, shaded at the end of the bar. Its size follows your raw world latency rather than the calibrated figure, because this one is the wire and not a prediction. This switch only draws it -- the timing itself always accounts for it, so set the scale to 0 if you want no compensation at all."] = "La fin du coup qu'une incantation ne peut plus franchir, ombrée au bout de la barre. Sa taille suit votre latence monde brute plutôt que le chiffre calibré, car celle-ci est le câble et non une prédiction. Cette option ne fait que la dessiner -- le calcul du timing en tient toujours compte, réglez donc l'échelle sur 0 si vous ne voulez aucune compensation.",
    ["Deadzone scale"] = "Échelle de la zone morte",
    ["Multiplies your world latency. Raise it if you cannot twist just outside the shaded stretch, lower it if you still can inside it. 0 switches the compensation off entirely."] = "Multiplie votre latence monde. Augmentez-la si vous n'arrivez pas à faire un twist juste en dehors de la portion ombrée, réduisez-la si vous y arrivez encore à l'intérieur. 0 désactive complètement la compensation.",
    ["Deadzone texture"] = "Texture de la zone morte",
    ["Deadzone transparency"] = "Transparence de la zone morte",
    ["Global cooldown padding"] = "Marge du temps de recharge global",
    ["Pulls the global cooldown boundary earlier by part of your latency, so a cast started right at the mark still clears the cooldown in time."] = "Avance la limite du temps de recharge global d'une partie de votre latence, afin qu'une incantation lancée pile sur le repère franchisse encore la recharge à temps.",
    ["Fixed global cooldown padding (ms)"] = "Marge fixe du temps de recharge global (ms)",
    ["Show the judgement mark"] = "Afficher le repère de jugement",
    ["A fourth line where Judgement comes off cooldown during this swing, so a judgement can be put in front of the twist instead of on top of it. Only drawn while a seal is up."] = "Une quatrième ligne à l'endroit où Jugement redevient disponible pendant ce coup, afin de pouvoir placer un jugement avant le twist plutôt que par-dessus. Dessinée uniquement lorsqu'un sceau est actif.",
    ["Show the global cooldown bar"] = "Afficher la barre de recharge globale",
    ["A strip along the bottom of the bar reaching to the moment the global cooldown frees up, so you can see how much of this swing is already spoken for."] = "Une bande le long du bas de la barre allant jusqu'au moment où le temps de recharge global se libère, pour voir quelle part de ce coup est déjà prise.",
    ["Global cooldown bar height"] = "Hauteur de la barre de recharge globale",
    ["When to show the bar"] = "Quand afficher la barre",
    ["Always keeps it on screen, which is the easier way to practise the timing on a dummy. Seal active shows it whenever you are carrying a seal, in or out of a fight."] = "Toujours la garde à l'écran, ce qui est la façon la plus simple de travailler le timing sur un mannequin. Sceau actif l'affiche dès que vous portez un sceau, en combat ou non.",
    ["Seal active"] = "Sceau actif",
    ["In combat or seal active"] = "En combat ou sceau actif",
    ["Only with Two-Handed Weapon Specialization"] = "Uniquement avec Spécialisation arme à deux mains",
    ["Hides the helper unless you have a point in the talent. Twisting works without it, but the slow swing it is built around is what makes the whole habit pay."] = "Masque l'assistant tant que vous n'avez pas de point dans ce talent. Le twist fonctionne sans lui, mais le coup lent autour duquel il est bâti est ce qui rend toute cette habitude payante.",
    ["Neck"] = "Cou",
    ["Shoulder"] = "Épaules",
    ["Waist"] = "Taille",
    ["Legs"] = "Jambes",
    ["Wrist"] = "Poignets",
    ["Hands"] = "Mains",
    ["Finger 2"] = "Doigt 2",
    ["Trinket 2"] = "Bijou 2",
    ["Off Hand"] = "Main gauche",
    ["Ranged"] = "Distance",
    -- Patch notes 1.42.0
    ["Practice – A swing clock that runs on its own, with your own keys and a verdict on every swing"] = "Entraînement – Une horloge de coup qui tourne toute seule, avec vos propres touches et une note sur chaque coup",
    ["Next action – An icon of the one thing to press, wherever you put it"] = "Action suivante – Une icône de la seule chose à presser, là où vous la placez",
    ["Latency – Calibrate the delay a twist has to beat, with its own multiplier and offset"] = "Latence – Calibrez le délai qu'un twist doit battre, avec son propre multiplicateur et son décalage",
    ["Shade the deadzone – The tail of the swing a cast can no longer cross"] = "Ombrer la zone morte – La fin du coup qu'une incantation ne peut plus franchir",
    ["Show the global cooldown bar – A strip reaching to the moment the cooldown frees up"] = "Afficher la barre de recharge globale – Une bande jusqu'à l'instant où la recharge se libère",
    ["When to show the bar – Always, in combat, while a seal is up, or either"] = "Quand afficher la barre – Toujours, en combat, tant qu'un sceau est actif, ou les deux",
    ["Colour the bar by – The zone the swing is in, or the seal you are carrying"] = "Colorer la barre selon – La portion où se trouve le coup, ou le sceau que vous portez",
    ["Detach from the bar – The seal icons take their own position, with a cooldown sweep"] = "Détacher de la barre – Les icônes de sceau prennent leur propre position, avec le balayage de recharge",
    ["Suggest Judgement – Offered only with room to re-seal afterwards, and off until you ask"] = "Suggérer Jugement – Proposé seulement s'il reste la place de re-sceller, et désactivé jusqu'à ce que vous le demandiez",
    ["Textures, border, font, frame layer, marker width and the two readouts inside the bar are yours to set, and every seal has its own colour."] = "Textures, bordure, police, strate du cadre, largeur des repères et les deux affichages à l'intérieur de la barre vous appartiennent, et chaque sceau a sa propre couleur.",
    -- Patch notes 1.42.0
    ["The twist is now called twist in every language, the word paladins use themselves. German called it Siegelwechsel; the helper and its window are named after the twist instead."] = "Le twist s'appelle twist dans toutes les langues, le mot que les paladins emploient eux-mêmes. L'allemand disait Siegelwechsel ; l'assistant et sa fenêtre portent désormais le nom du twist.",
    ["The cue for a landed twist no longer guesses. It used to fire the moment a seal went out inside the window, which is a prediction the server can disagree with. Now the combat log has to show a swing landing with both seals up and the held seal's own damage behind it. Without that, nothing sounds."] = "Le signal d'un twist réussi ne devine plus. Il se déclenchait dès qu'un sceau partait dans la fenêtre, une prédiction que le serveur peut contredire. Désormais le journal de combat doit montrer un coup qui touche avec les deux sceaux actifs, suivi des dégâts propres au sceau maintenu. Sans cela, rien ne sonne.",
    -- Patch notes 1.42.0
    ["Switching the module off used to leave the bag bar, the latency bar and Action Bar 1's twelve buttons behind until a /reload. All three come back on their own now."] = "Désactiver le module laissait derrière lui la barre de sacs, celle de latence et les douze boutons de la Barre d'action 1 jusqu'à un /reload. Les trois reviennent d'elles-mêmes désormais.",
    ["Rows that span the page now start their control where their neighbours do, instead of each sizing its own label."] = "Les lignes qui occupent toute la largeur commencent leur contrôle là où le font leurs voisines, au lieu que chacune mesure sa propre étiquette.",
    -- Patch notes 1.42.0
    ["Watch this unit – A group can follow your target, your focus or your pet instead of you"] = "Surveiller cette unité – Un groupe peut suivre votre cible, votre focus ou votre familier plutôt que vous",
    ["Only what I cast myself – A group can require the aura to be your own, not anyone's"] = "Seulement ce que je lance moi-même – Un groupe peut exiger que l'aura soit la vôtre et non celle de n'importe qui",
    ["Order – Sort a group by the time left instead of the order you added things in"] = "Ordre – Trier un groupe par le temps restant plutôt que par l'ordre dans lequel vous l'avez rempli",
    ["Conditions belong to the individual entry now, not only to the kind of group it sits in. One entry can ask for a stack count or for the last few seconds while its neighbours ask for nothing."] = "Les conditions appartiennent désormais à l'entrée elle-même, et plus seulement au type de groupe où elle se trouve. Une entrée peut demander un nombre de cumuls ou les dernières secondes alors que ses voisines ne demandent rien.",
    ["Cast bars in front of other plates – So the cast you are watching is not hidden behind the plate beside it"] = "Barres d'incantation devant les autres barres – Pour que l'incantation que vous suivez ne disparaisse pas derrière celle d'à côté",
    ["Darken enemies out of combat – With its own strength, so an idle mob reads as idle at a glance"] = "Assombrir les ennemis hors combat – Avec sa propre intensité, si bien qu'un ennemi inactif se lit comme inactif d'un coup d'œil",
    ["Highlight strength – How far the plate under your cursor lifts out of the row"] = "Intensité de la surbrillance – De combien la barre sous votre curseur se détache du rang",
    ["The clickable area is measured from the plate now instead of assumed, so the width and height settings land where your cursor really is."] = "La zone cliquable est maintenant mesurée sur la barre au lieu d'être supposée : les réglages de largeur et de hauteur tombent donc là où se trouve vraiment votre curseur.",
    ["A dropdown with more entries than fit on screen scrolls instead of running off the bottom, and a label that had grown too long fits its row again."] = "Un menu déroulant comptant plus d'entrées que l'écran n'en affiche défile désormais au lieu de sortir par le bas, et un libellé devenu trop long tient à nouveau dans sa ligne.",
    -- Patch notes 1.43.0
    ["Compatibility"] = "Compatibilité",
    ["The character window stayed empty on clients we had never named. The panel asked whether the client called itself one of two specific versions and refused every other one, including clients that have exactly the frames it needs. It now asks for the one thing it cannot work without. Enchants, sockets and item stats were missing for the same reason and return with it."] = "La fenêtre de personnage restait vide sur des clients que nous n'avions jamais nommés. Le panneau demandait si le client se disait l'une de deux versions précises et refusait toutes les autres, y compris celles qui possèdent exactement les cadres dont il a besoin. Il demande désormais la seule chose sans laquelle il ne peut pas fonctionner. Les enchantements, les châsses et les caractéristiques d'objet manquaient pour la même raison et reviennent avec lui.",
    ["Hit rating, haste rating and spell hit rating appear on Wrath-based clients too. They were tied to a single version by name, although the game there has those stats."] = "Le score de toucher, le score de hâte et le score de toucher des sorts apparaissent aussi sur les clients fondés sur Wrath. Ils étaient liés par leur nom à une seule version, alors que le jeu y possède bel et bien ces caractéristiques.",
    ["The stat rows Wrath draws in pages with two dropdowns are hidden underneath our own panel now, instead of showing through it."] = "Les lignes de caractéristiques que Wrath affiche en pages avec deux menus déroulants sont maintenant cachées sous notre propre panneau, au lieu de transparaître au travers.",
    ["Titan Reforged – The addon no longer reports itself out of date on the Chinese client, whose build is listed now"] = "Titan Reforged – L'addon ne se déclare plus obsolète sur le client chinois, dont la version figure désormais dans la liste",
    ["Version detection falls back to the build number whenever a client reports an identifier we have no name for. Such a client used to end up with every version flag false, which left it worse off than a client with no identifier at all, because that one at least fell back to something."] = "La détection de version se rabat sur le numéro de build dès qu'un client annonce un identifiant dont nous ignorons le nom. Un tel client se retrouvait auparavant avec tous les indicateurs de version à faux, ce qui le laissait plus mal loti qu'un client sans identifiant du tout, puisque celui-ci se rabattait au moins sur quelque chose.",
    ["242 texts that nothing in the interface looks up any more are gone from all nine language files, roughly eight percent of each. Renamed settings left them behind: the action bars were given clearer names a while ago and the old entries simply stayed. A check now asks the reverse question after every change, whether every translated text is still in use, so they cannot pile up again."] = "242 textes que plus rien dans l'interface ne consulte ont disparu des neuf fichiers de langue, environ huit pour cent de chacun. Ce sont les réglages renommés qui les ont laissés derrière eux : les barres d'action ont reçu des noms plus clairs il y a quelque temps et les anciennes entrées sont simplement restées. Une vérification pose désormais la question inverse après chaque modification, à savoir si chaque texte traduit sert encore, afin qu'ils ne s'accumulent plus.",
    ["Call button – A fifth totem button for the spells that summon a whole saved totem set, shown only to characters who know one"] = "Bouton d'appel – Un cinquième bouton de totem pour les sorts qui invoquent tout un ensemble de totems enregistré, visible uniquement pour les personnages qui en connaissent un",
    ["Icon Strip"] = "Bande d'icônes",
    ["Distance from frame"] = "Distance à la fenêtre",
    ["Spacing between icons"] = "Espacement entre les icônes",
    ["Racial, PvP trinket and the DR row sit on the same edge of the frame and are placed one after the other, in that order, outwards from the frame."] = "La capacité raciale, le bijou JcJ et la rangée de réductions occupent le même bord de la fenêtre et sont placés l'un après l'autre, dans cet ordre, vers l'extérieur.",
    ["Where it sits is set once for all three trackers under Layout, Icon Strip."] = "Sa position se règle une seule fois pour les trois suivis, sous Disposition, Bande d'icônes.",
    ["Gap below each frame. The opponent's pet bar hangs off the bottom of the frame, so a small gap lets it reach into the next one."] = "Espace sous chaque fenêtre. La barre du familier de l'adversaire dépasse sous la fenêtre : avec un espace réduit, elle empiète sur la suivante.",
    ["Arena: racial, PvP trinket and the DR row now share one icon strip; your chosen side was kept."] = "Arène : la capacité raciale, le bijou JcJ et la rangée de réductions partagent désormais une seule bande d'icônes ; le côté que vous aviez choisi a été conservé.",
    ["|cffff5555Arena layout failed:|r %s"] = "|cffff5555Échec de la disposition de l'arène :|r %s",
    ["|cffff5555Arena icon strip error:|r %s"] = "|cffff5555Erreur de la bande d'icônes de l'arène :|r %s",
    ["Nothing in this bar yet. Add a spell or trinket below, or drag one onto the bar."] = "Rien sur cette barre pour l'instant. Ajoutez un sort ou un bijou ci-dessous, ou glissez-en un sur la barre.",
    ["+  New cooldown bar"] = "+  Nouvelle barre de recharges",
    ["+  New buff / proc bar"] = "+  Nouvelle barre de bonus et procs",
    ["+  New target debuff bar"] = "+  Nouvelle barre de malus sur la cible",
    ["+  New missing-buff reminder"] = "+  Nouveau rappel de bonus manquants",
    ["Buffs & Procs"] = "Bonus et procs",
    ["Target debuffs"] = "Malus sur la cible",
    ["Missing buffs"] = "Bonus manquants",
    ["New name for this bar"] = "Nouveau nom pour cette barre",
    ["Delete this bar and everything on it?"] = "Supprimer cette barre et tout ce qui est dessus ?",
    ["That is the last bar — there has to be one."] = "C'est la dernière barre — il en faut une.",
    ["Drag to reorder bars"] = "Glissez pour réordonner les barres",
    ["Rename this bar"] = "Renommer cette barre",
    ["Delete this bar"] = "Supprimer cette barre",
    ["Duplicate bar"] = "Dupliquer la barre",
    ["Copies the selected bar with all entries and layout settings."] = "Copie la barre sélectionnée avec toutes ses entrées et ses réglages de disposition.",
    ["Bar layout"] = "Disposition de la barre",
    ["Icon appearance"] = "Apparence des icônes",
    ["Icon display"] = "Affichage des icônes",
    ["Movable cooldown bars grouped however you like — procs, defensives, offensives, each with its own look and position."] = "Des barres de recharge déplaçables, regroupées à votre guise — effets déclenchés, défensifs, offensifs, chacune avec son apparence et sa position.",
    ["Which IDs should be shown in tooltips? Some types do not exist on this game version and are ignored (e.g. TraitNodeID, SourceID)."] = "Quels identifiants afficher dans les infobulles ? Certains types n'existent pas sur cette version du jeu et sont ignorés (p. ex. TraitNodeID, SourceID).",
    ["CDM Bars"] = "Barres CDM",
    ["Bug Fixes"] = "Correctifs",
    ["Bar Glows"] = "Lueurs de barre",
    ["Click to edit this icon's glow."] = "Cliquez pour modifier la lueur de cette icône.",
    ["Click an icon to edit its glow."] = "Cliquez sur une icône pour modifier sa lueur.",
    ["Nothing in this bar yet. Add a spell or trinket on the CDM Bars tab first."] = "Rien sur cette barre pour l'instant. Ajoutez d'abord un sort ou un bijou dans l'onglet Barres CDM.",
    ["|cffaaaaaaEach icon can glow while a buff of yours is active — or missing. Click an icon in the preview above, then add one or more watchers; the first whose condition holds paints the icon.|r"] = "|cffaaaaaaChaque icône peut luire tant qu'un de vos bonus est actif — ou manquant. Cliquez sur une icône dans l'aperçu ci-dessus, puis ajoutez un ou plusieurs guetteurs ; le premier dont la condition est remplie colore l'icône.|r",
    ["|cff888888No icon picked yet.|r"] = "|cff888888Aucune icône choisie.|r",
    ["Glows: %s"] = "Lueurs : %s",
    ["Glow when"] = "Luire quand",
    ["Buff is active"] = "Le bonus est actif",
    ["Buff is missing"] = "Le bonus est manquant",
    ["Action button glow"] = "Lueur de bouton d'action",
    ["Pulsing fill"] = "Remplissage pulsant",
    ["Gold (default)"] = "Or (par défaut)",
    ["Pick color..."] = "Choisir la couleur...",
    ["Remove this glow"] = "Retirer cette lueur",
    ["Watches: %s"] = "Surveille : %s",
    ["Add watcher (buff name / ID)"] = "Ajouter un guetteur (nom du sort / ID)",
    ["|cffaaaaaaNo watcher yet. Most spells put a buff of the same name on you when used — one click below makes this icon glow while that buff is on you. Or type any other buff into the field.|r"] = "|cffaaaaaaAucun guetteur pour l'instant. La plupart des sorts posent sur vous un bonus du même nom — un clic ci-dessous fait luire cette icône tant que ce bonus est actif sur vous. Ou saisissez n'importe quel autre bonus dans le champ.|r",
    ["Glow while '%s' is on me"] = "Luire tant que « %s » est sur moi",
    -- Patch notes 1.44.0
    ["Icon Strip – Racial, trinket and the diminishing-returns row share one edge of the frame in a fixed order, with one set of controls — they can no longer land on top of each other"] = "Bande d'icônes – La capacité raciale, le bijou et la rangée de réductions partagent un bord du cadre dans un ordre fixe, avec un seul jeu de réglages — ils ne peuvent plus se recouvrir",
    ["The frame layout — order, spacing, grow direction — never actually applied: its hooks were installed before the arena interface had loaded. The frames now report their own moves and the layout follows; during a fight they are protected, so a move mid-round is corrected when it ends."] = "La disposition des cadres d'arène — ordre, espacement, sens de croissance — ne s'appliquait jamais : ses crochets étaient posés avant le chargement de l'interface d'arène. Les cadres signalent désormais leurs propres déplacements et la disposition suit ; en combat ils sont protégés, et un déplacement en pleine manche est corrigé à la fin.",
    ["The default gap between frames clears the opponent's pet bar, and the drag box in edit mode covers the whole stack instead of a fixed area."] = "L'espacement par défaut entre les cadres laisse la place à la barre du familier de l'adversaire, et la zone de déplacement du mode édition couvre toute la pile au lieu d'une surface fixe.",
    ["Bar Glows – Any icon can glow while a buff of yours is active or missing: three styles, gold, class or custom color, and one click watches the spell's own buff"] = "Lueurs de barre – N'importe quelle icône peut luire tant qu'un de vos bonus est actif ou manquant : trois styles, or, couleur de classe ou couleur personnalisée, et un clic surveille le propre bonus du sort",
    ["The page is built around a preview that stays put while you scroll: the bar picker with rename, delete and drag-to-reorder on top, under it every icon of the bar at its real size and shape with the real cooldown sweep. Drag reorders, right-click removes."] = "La page est construite autour d'un aperçu qui reste en place pendant le défilement : en haut le sélecteur de barres avec renommer, supprimer et glisser pour réordonner, en dessous chaque icône de la barre à sa taille et sa forme réelles avec le vrai balayage de recharge. Glisser réordonne, le clic droit retire.",
    ["The page is split into tabs, and the resource bar moved in as one of them. Spells you add belong to the class that added them and no longer show up on your other characters."] = "La page est découpée en onglets, et la barre de ressources y a emménagé comme l'un d'eux. Les sorts que vous ajoutez appartiennent à la classe qui les a ajoutés et n'apparaissent plus sur vos autres personnages.",
    ["The third extra-item slot no longer stretches across the page with its box flung to the far edge."] = "Le troisième emplacement d'objets supplémentaires ne s'étire plus sur toute la page avec son champ projeté au bord.",
    ["The interface no longer compares itself with the other game version anywhere; a check keeps such wording out for good."] = "L'interface ne se compare plus nulle part à l'autre version du jeu ; un contrôle tient définitivement ce genre de formulation à l'écart.",
    ["Modules with several pages show them as a tab row along the top; when the tabs outgrow the row, two arrows page through it instead of wrapping into a second line."] = "Les modules à plusieurs pages les affichent en une rangée d'onglets le long du bord supérieur ; quand les onglets dépassent la rangée, deux flèches la font défiler au lieu de passer à la ligne.",
    ["The sidebar got shorter: player and target frames, font bars, castbar and cooldown pulse are one entry now, and a new General entry under Reminders collects the former Extras, Character and Bug Fixes rows — the bug fixes as a single tab."] = "La barre latérale a raccourci : les cadres de joueur et de cible, les barres de police, la barre d'incantation et la pulsation de recharge ne font plus qu'une entrée, et une nouvelle entrée Général sous Rappels rassemble les anciennes lignes Divers, Personnage et Correctifs — les correctifs en un seul onglet.",
    ["Typing into an add field and then clicking the button beside it silently did nothing; the typed text only counted after pressing Enter. Buttons now take the field's text with them."] = "Taper dans un champ d'ajout puis cliquer sur le bouton voisin ne faisait rien, en silence ; le texte saisi ne comptait qu'après Entrée. Les boutons emportent désormais le texte du champ.",
    ["Developer"] = "Développeur",
    ["Suppress Lua Errors"] = "Masquer les erreurs Lua",
    ["Hides the game's own Lua error popup (CVar scriptErrors). Errors still happen and error-collecting addons still see them - they just stop interrupting you."] = "Masque la fenêtre d'erreurs Lua du jeu (CVar scriptErrors). Les erreurs se produisent toujours et les addons qui les collectent les voient encore - elles ne vous interrompent simplement plus.",
    ["Show IDs in Tooltips"] = "Afficher les identifiants dans les infobulles",
    ["Shows spell, item, NPC and other IDs in tooltips. Which ID types appear can be fine-tuned on the Tooltip IDs page in the Extras group."] = "Affiche les identifiants des sorts, objets, PNJ et plus dans les infobulles. Les types affichés se règlent sur la page Identifiants dans les infobulles du groupe Divers.",
    ["Reset All Settings"] = "Réinitialiser tous les paramètres",
    ["Optimize My FPS and Graphics"] = "Optimiser mes FPS et mes graphismes",
    ["Applies a proven set of graphics settings that noticeably raises FPS while keeping the game looking good - shadows, liquids, ambient occlusion and view distance go down, textures and spell effects stay sharp. Your current values are saved first and the restore button brings them back. Only settings this client knows are touched."] = "Applique un ensemble éprouvé de réglages graphiques qui augmente nettement les FPS tout en gardant un beau rendu - ombres, liquides, occlusion ambiante et distance d'affichage baissent, les textures et les effets de sorts restent nets. Vos valeurs actuelles sont d'abord sauvegardées et le bouton de restauration les ramène. Seuls les réglages connus de ce client sont touchés.",
    ["Restore My Graphics Settings"] = "Restaurer mes réglages graphiques",
    ["Returns every graphics setting the optimize button changed to its previous value and removes the backup."] = "Ramène chaque réglage graphique modifié par le bouton d'optimisation à sa valeur précédente et supprime la sauvegarde.",
    ["Graphics optimized: %d settings applied."] = "Graphismes optimisés : %d réglages appliqués.",
    ["Graphics settings restored."] = "Réglages graphiques restaurés.",
    ["Global Font"] = "Police globale",
    ["The font for the whole VuloClassicUI interface. Fonts shared by other addons appear here too.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "La police de toute l'interface VuloClassicUI. Les polices partagées par d'autres addons apparaissent ici aussi.\n\n|cffaaaaaaNécessite /reload pour s'appliquer partout.|r",
    ["Outline Mode"] = "Mode de contour",
    ["Default outline for VuloClassicUI text. Elements with their own outline setting keep it.\n\n|cffaaaaaaRequires /reload to apply everywhere.|r"] = "Contour par défaut des textes de VuloClassicUI. Les éléments avec leur propre réglage de contour le gardent.\n\n|cffaaaaaaNécessite /reload pour s'appliquer partout.|r",
    ["Apply to All Game Texts"] = "Appliquer à tous les textes du jeu",
    ["Replaces the font of the game's own texts (chat, tooltips, quest log and more) with the global font.\n\n|cffaaaaaaTurning it off requires /reload to restore the original fonts.|r"] = "Remplace la police des textes du jeu (discussion, infobulles, journal de quêtes et plus) par la police globale.\n\n|cffaaaaaaLa désactivation nécessite /reload pour restaurer les polices d'origine.|r",
    ["Class Colors"] = "Couleurs de classe",
    ["Resource Colors"] = "Couleurs de ressources",
    ["Font changed. /reload required to apply it everywhere."] = "Police modifiée. /reload nécessaire pour l'appliquer partout.",
    ["Reset to default"] = "Réinitialiser par défaut",
    ["Rename..."] = "Renommer...",
    ["Rename loadout '%s'. Enter new name:"] = "Renommer l'ensemble « %s ». Nouveau nom :",
    ["A loadout named '%s' already exists."] = "Un ensemble nommé « %s » existe déjà.",
    ["Loadout '%s' renamed to '%s'."] = "Ensemble « %s » renommé en « %s ».",
    -- Patch notes 1.45.0
    ["The item level on equipment links sits after the link now, not inside its brackets. Some clients re-check link text against their own data, and the changed text turned the link into the name of whatever quest carried that number."] = "Le niveau d'objet des liens d'équipement se place désormais après le lien, plus entre ses crochets. Certains clients revérifient le texte des liens contre leurs propres données, et le texte modifié transformait le lien en nom de la quête portant ce numéro.",
    ["A spell no longer shows up on another class just because that class owns a different spell with the same name. Entries respect their class stamp on the bars, and old entries are adopted by spell ID instead of by name."] = "Un sort n'apparaît plus chez une autre classe simplement parce qu'elle possède un sort différent du même nom. Les entrées respectent leur marque de classe sur les barres, et les anciennes sont adoptées par identifiant de sort plutôt que par nom.",
    ["The bundled media library silently dropped font registrations when no other addon shipped a newer copy of it; the addon font now registers on every install."] = "La bibliothèque de médias incluse rejetait en silence des enregistrements de polices quand aucun autre addon n'apportait une copie plus récente ; la police de l'addon s'enregistre désormais à chaque installation.",
    ["Rename... – In the set's right-click menu and on the sets page; icon, contents and talent binding move along with the name"] = "Renommer... – Dans le menu contextuel de l'ensemble et sur la page des ensembles ; icône, contenu et liaison de talents déménagent avec le nom",
    ["Optimize My FPS and Graphics – A proven set of graphics settings with a one-time backup; the restore button next to it brings your old values back"] = "Optimiser mes FPS et mes graphismes – Un ensemble éprouvé de réglages graphiques avec sauvegarde unique ; le bouton de restauration voisin ramène vos anciennes valeurs",
    ["Fonts & Colors – A new tab: global font with outline mode, optionally for all game texts, plus class and resource colors with a reset on every row"] = "Polices et couleurs – Un nouvel onglet : police globale avec mode de contour, au besoin pour tous les textes du jeu, plus couleurs de classe et de ressources avec réinitialisation à chaque ligne",
    ["Developer – Suppress Lua errors, switch tooltip IDs and reset all settings from a new section on the General tab"] = "Développeur – Masquer les erreurs Lua, activer les identifiants dans les infobulles et réinitialiser tous les réglages, dans une nouvelle section de l'onglet Général",
    ["The General tab is organised in sections on a two-column grid like the rest of the window. The new tab ships a texture file: restart the client once after updating, a /reload alone will not show the reset arrows."] = "L'onglet Général est organisé en sections sur une grille à deux colonnes, comme le reste de la fenêtre. Le nouvel onglet apporte un fichier de texture : redémarrez le client une fois après la mise à jour, un /reload seul n'affiche pas les flèches de réinitialisation.",
    ["The enlargement stays off on Wrath-based clients (Titan Reforged): their quest log is already the wide two-pane frame, and enlarging it pushed the detail pane into the button row."] = "L'agrandissement reste désactivé sur les clients basés sur Wrath (Titan Reforged) : leur journal de quêtes est déjà la large fenêtre à deux volets, et l'agrandir poussait le volet de détails sur la rangée de boutons.",
    ["Long dropdown lists open upwards when there is no room below. They used to run off the bottom edge of the screen, where the last entries could never be scrolled into view."] = "Les longues listes déroulantes s'ouvrent vers le haut quand la place manque en dessous. Elles débordaient jusqu'ici du bas de l'écran, où les dernières entrées ne pouvaient jamais être atteintes.",
    ["On"] = "Activé",
    ["Select all"] = "Tout sélectionner",
    ["Deselect all"] = "Tout désélectionner",
    ["Interface layout (window positions and links)"] = "Disposition de l'interface (positions et liaisons de fenêtres)",
    ["Fonts & colors (account-wide)"] = "Polices et couleurs (tout le compte)",
    ["Also carries your account-wide font and color settings; they apply immediately when the string is imported."] = "Emporte aussi vos réglages de police et de couleurs valables pour tout le compte ; ils s'appliquent immédiatement à l'import de la chaîne.",
    ["|cffaaaaaaThe export will include %d of %d modules.|r"] = "|cffaaaaaaL'export comprendra %d des %d modules.|r",
    ["Nothing selected to export."] = "Rien de sélectionné à exporter.",
    ["|cffaaaaaaUntick modules to share only a part - a partial string merges onto the importer's active profile.|r"] = "|cffaaaaaaDécochez des modules pour ne partager qu'une partie - une chaîne partielle fusionne avec le profil actif de l'importateur.|r",
    ["Standard Action Bars"] = "Barres d'action standard",
    ["Modern"] = "Moderne",
    ["|cffaaaaaaThe game's own action bars stay in place. Frame style and Dark Mode below come from the Dark Skin module and style Blizzard's buttons directly.|r"] = "|cffaaaaaaLes barres d'action du jeu restent en place. Le style de cadre et le Mode Sombre ci-dessous viennent du module Dark Skin et habillent directement les boutons de Blizzard.|r",
    ["Apply layout to all bars"] = "Appliquer la disposition à toutes les barres",
    ["Copies this bar's layout - scale, icon size, buttons per row, spacing, direction - to every other bar."] = "Copie la disposition de cette barre - échelle, taille d'icône, boutons par rangée, espacement, direction - vers toutes les autres.",
    ["Layout applied to all bars."] = "Disposition appliquée à toutes les barres.",
    ["Text sizes"] = "Tailles de texte",
    ["Bar Display"] = "Affichage des barres",
    ["Menu, Bags & XP Bar"] = "Menu, sacs et barre d'XP",
    ["|cffaaaaaaOnly active in Modern mode (Bar Display tab).|r"] = "|cffaaaaaaActif uniquement en mode Moderne (onglet Affichage des barres).|r",
    ["Click: layout settings. Right-click: text sizes."] = "Clic : réglages de disposition. Clic droit : tailles de texte.",
    ["Bar Animations"] = "Animations des barres",
    ["Tint the pressed state"] = "Teinter l'état enfoncé",
    ["Colours the flash a button shows while it is pressed down."] = "Colore l'éclair qu'un bouton affiche pendant qu'il est enfoncé.",
    ["Tint the hover highlight"] = "Teinter la surbrillance au survol",
    ["Colours the glow a button shows under the mouse."] = "Colore la lueur qu'un bouton affiche sous la souris.",
    ["Use class colour"] = "Utiliser la couleur de classe",
    ["Enable bar background"] = "Activer le fond de barre",
    ["A flat colour panel behind the bar, sized with it."] = "Un panneau de couleur unie derrière la barre, dimensionné avec elle.",
    ["Padding"] = "Marge",
    ["Flat (default)"] = "Uni (par défaut)",
    ["Core"] = "Principal",
    ["Opacity"] = "Opacité",
    ["Durability"] = "Durabilité",
    ["Talent points"] = "Points de talent",
    ["Pulse"] = "Pulsation",
    ["Steady"] = "Constant",
    ["Background"] = "Arrière-plan",
    ["Low"] = "Bas",
    ["Medium"] = "Moyen",
    ["High"] = "Élevé",
    ["Dialog"] = "Dialogue",
    ["Click an icon to jump to its settings."] = "Cliquez sur une icône pour accéder à son réglage.",
    ["Middle-click: hide until the next loading screen."] = "Clic molette : masquer jusqu'au prochain écran de chargement.",
    ["Nothing to preview: every reminder is switched off."] = "Rien à prévisualiser : tous les rappels sont désactivés.",
    ["Show effects missing on others"] = "Afficher les effets manquants chez les autres",
    ["Scans your party or raid for class buffs you could cast and reminds you when someone lacks one."] = "Parcourt votre groupe ou raid à la recherche des améliorations de classe que vous pourriez lancer et vous prévient quand quelqu'un en manque une.",
    ["Missing on %s: %s"] = "Manque à %s : %s",
    ["In raids (minutes)"] = "En raid (minutes)",
    ["In dungeons (minutes)"] = "En donjon (minutes)",
    ["0 uses the global warn threshold."] = "0 utilise le seuil d'alerte global.",
    ["Preferred food"] = "Nourriture préférée",
    ["Preferred flask or elixir"] = "Flacon ou élixir préféré",
    ["Preferred weapon enhancement"] = "Amélioration d'arme préférée",
    ["Automatic (best in bags)"] = "Automatique (le meilleur des sacs)",
    ["Click to use."] = "Cliquez pour utiliser.",
    ["Attach reminders to the cursor"] = "Attacher les rappels au curseur",
    ["Shows small copies of the current reminders next to the mouse cursor."] = "Affiche de petites copies des rappels actuels près du curseur de la souris.",
    ["Helpers"] = "Assistants",
    ["Queue countdown, buff minigame helper and class trainer book in one place."] = "Compte à rebours de file d'attente, assistant du mini-jeu d'améliorations et livre du maître de classe au même endroit.",
    ["Open group board"] = "Ouvrir la recherche de groupe",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the button below)."] = "Analyse la discussion à la recherche de joueurs formant des groupes et les liste par instance Classic/TBC dans une fenêtre (/vlfg ou le bouton ci-dessous).",
    ["Show minimap button"] = "Afficher le bouton de minicarte",
    ["PvP Settings"] = "Réglages JcJ",
    ["Fullscreen"] = "Plein écran",
    ["Fullscreen dialog"] = "Dialogue plein écran",
    ["Tooltip"] = "Info-bulle",
    ["Orientation"] = "Orientation",
    ["Horizontal"] = "Horizontal",
    ["Vertical (up)"] = "Vertical (vers le haut)",
    ["Vertical (down)"] = "Vertical (vers le bas)",
    ["Fill opacity"] = "Opacité du remplissage",
    ["Below 100 the world shows through the filled part of the bar."] = "En dessous de 100, le monde transparaît à travers la partie remplie de la barre.",
    ["The fill fades into a second colour towards its end."] = "Le remplissage se fond dans une seconde couleur vers son extrémité.",
    ["Name inside the bar"] = "Nom dans la barre",
    ["Anchors the name at the left edge inside the health bar instead of above it — the right edge stays free for the health text."] = "Ancre le nom au bord gauche à l'intérieur de la barre de vie plutôt qu'au-dessus — le bord droit reste libre pour le texte de vie.",
    ["Show plates for enemy pets"] = "Afficher les plaques des familiers ennemis",
    ["Divider line on the target's bar"] = "Ligne de séparation sur la barre de la cible",
    ["Draws a thin vertical line at the given percent of the health bar — an execute marker."] = "Trace une fine ligne verticale au pourcentage indiqué de la barre de vie — un repère d'exécution.",
    ["Line position (%)"] = "Position de la ligne (%)",
    ["Only on your target"] = "Seulement sur votre cible",
    ["Spell name"] = "Nom du sort",
    ["Colour the last tick"] = "Colorer le dernier tic",
    ["Show latency text"] = "Afficher le texte de latence",
    ["Vertical"] = "Vertical",
    ["Automatic stacks a side slot as a column and a top or bottom slot as a row."] = "Automatique empile un emplacement latéral en colonne et un emplacement supérieur ou inférieur en ligne.",
    ["Show older versions"] = "Afficher les anciennes versions",
    ["%d broken numeric values were removed from the settings so they can be saved again."] = "%d valeurs numériques corrompues ont été retirées des réglages pour pouvoir les sauvegarder à nouveau.",
    ["Widen window"] = "Élargir la fenêtre",
    ["Extra width for the friends window so long names, notes and zones fit on one line. 0 keeps Blizzard's width."] = "Largeur supplémentaire pour la fenêtre des amis afin que les longs noms, notes et zones tiennent sur une ligne. 0 garde la largeur de Blizzard.",
    ["Classic+ keeps Blizzard's layout with extras. Modern adds the dark chrome and moves all stats into a panel on the right of the character window."] = "Classic+ garde la disposition de Blizzard avec des extras. Modern ajoute l'habillage sombre et déplace toutes les stats dans un panneau à droite de la fenêtre de personnage.",
    ["Overrides the group switch for this entry alone - e.g. to track a buff someone else casts on you."] = "Remplace le réglage de groupe pour cette entrée seule - p. ex. pour suivre un buff que quelqu'un d'autre lance sur toi.",
    ["Group default"] = "Défaut du groupe",
    ["Anyone's"] = "De n'importe qui",
    ["Use conditions"] = "Utiliser les conditions",
    ["Unticked parks this entry: it keeps its settings but never shows. The gear holds moving, removing and per-entry settings."] = "Décoché met cette entrée de côté : elle garde ses réglages mais ne s'affiche jamais. L'engrenage regroupe le déplacement, la suppression et les réglages par entrée.",
    ["Talent Window"] = "Fenêtre des talents",
    ["Shows all three talent trees side by side in one window."] = "Affiche les trois arbres de talents côte à côte dans une seule fenêtre.",
    ["Points left: %d"] = "Points restants : %d",
    ["TALENTS"] = "TALENTS",
    ["Open Blizzard's talent window"] = "Ouvrir la fenêtre de talents de Blizzard",
    ["For glyphs and everything this window does not cover."] = "Pour les glyphes et tout ce que cette fenêtre ne couvre pas.",
    ["|cffaaaaaaAll three talent trees side by side, with live ranks and click-to-learn. Glyphs stay in Blizzard's window, one button away.|r"] = "|cffaaaaaaLes trois arbres de talents côte à côte, avec rangs en direct et apprentissage au clic. Les glyphes restent dans la fenêtre de Blizzard, accessibles d'un simple bouton.|r",
    ["Replace Blizzard's talent window"] = "Remplacer la fenêtre de talents de Blizzard",
    ["Opening talents shows this window instead. Turn it off to get Blizzard's one-tree window back."] = "Ouvrir les talents affiche cette fenêtre à la place. Désactive l'option pour retrouver la fenêtre à un seul arbre de Blizzard.",
    ["Open talent window"] = "Ouvrir la fenêtre des talents",
    ["See-through"] = "Transparence",
    ["Hide the box fill and labels while editing, so you can see the interface you are aligning. The thin borders stay."] = "Masque le remplissage et les libellés des cadres pendant l'édition pour voir l'interface que tu alignes. Les fines bordures restent.",
    -- Patch notes 1.46.0
    ["Options"] = "Options",
    ["Talents"] = "Talents",
    ["The page opens with two modes: Standard keeps Blizzard's bars with the skin rows, Modern runs the addon's own bars with a live preview, a per-bar background, button press and hover tints and an XP bar texture"] = "La page s'ouvre avec deux modes : Standard garde les barres de Blizzard avec les lignes d'habillage, Moderne fait tourner les barres du addon avec aperçu en direct, fond par barre, teintes d'appui et de survol des boutons et une texture pour la barre d'expérience",
    ["Modern – Third player cast bar style: flat look with name and timer on the bar, plus bar texture, border, a coloured last tick and a latency readout"] = "Moderne – Troisième style de la barre d'incantation du joueur : look plat avec nom et temps sur la barre, plus texture de barre, bordure, un dernier tic coloré et un affichage de latence",
    ["The options page carries a live preview; clicking its icon or bar jumps to the matching section"] = "La page d'options porte un aperçu en direct ; cliquer sur son icône ou sa barre saute à la section correspondante",
    ["Enchant and gem displays no longer displace each other on non-English clients, and Chinese enchant text is no longer cut mid-character"] = "L'affichage des enchantements et des gemmes ne se chassent plus l'un l'autre sur les clients non anglais, et le texte d'enchantement chinois n'est plus coupé au milieu d'un caractère",
    ["Tracked entries sit two per row, each with a gear: park an entry without deleting it, move or remove it, set conditions, and override Only what I cast myself for that entry alone"] = "Les entrées suivies vont par deux par ligne, chacune avec un engrenage : garer une entrée sans la supprimer, la déplacer ou la retirer, poser des conditions et surcharger Seulement ce que je lance moi-même pour cette entrée seule",
    ["See-through – Hides the box fill and labels while editing, so you can see the interface you are aligning"] = "Transparence – Masque le remplissage et les libellés des cadres pendant l'édition pour voir l'interface que tu alignes",
    ["Coordinates appear on the box while dragging or nudging, and the window being snapped to pulses white"] = "Les coordonnées apparaissent sur le cadre pendant le déplacement, et la fenêtre sur laquelle on s'aligne pulse en blanc",
    ["The loot window can be moved on Wrath clients"] = "La fenêtre de butin peut être déplacée sur les clients Wrath",
    ["Widen window – Extra width so long names, notes and zones fit on one line"] = "Élargir la fenêtre – Largeur en plus pour que les longs noms, notes et zones tiennent sur une ligne",
    ["The close glyph of every window is larger now"] = "Le signe de fermeture de toutes les fenêtres est plus grand",
    ["Three tabs with a pinned live preview, a name-in-bar option and thousands separators on health numbers"] = "Trois onglets avec aperçu épinglé, une option nom dans la barre et des séparateurs de milliers sur les chiffres de vie",
    ["Gear rows open inside their own column, aura rows align per row, helper tools share one tab, and the pinned page header of the last visited tab is cleared on switching"] = "Les lignes à engrenage s'ouvrent dans leur propre colonne, les lignes d'auras s'alignent par ligne, les outils d'aide partagent un onglet, et l'en-tête épinglé du dernier onglet visité est nettoyé au changement",
    ["Only the last five versions build at once; a button loads the older ones"] = "Seules les cinq dernières versions se construisent d'un coup ; un bouton charge les plus anciennes",
    ["Orientation, fill opacity, frame strata and a live preview on the options page"] = "Orientation, opacité du remplissage, strate du cadre et un aperçu sur la page d'options",
    ["A profile string can carry a selection: chosen modules, the window layout, talent overrides, and the account-wide fonts and colours"] = "Une chaîne de profil peut porter une sélection : modules choisis, disposition des fenêtres, surcharges de talents et les polices et couleurs du compte",
    ["Per-rule switches with class-coloured names, a group scan for missing buffs, preferred food, flask and weapon oil, raid and dungeon thresholds, glow styles, scale and a live preview; middle-click hides a reminder until the next loading screen"] = "Interrupteurs par règle avec noms aux couleurs de classe, un scan du groupe pour les buffs manquants, nourriture, flacon et huile d'arme préférés, seuils pour raid et donjon, styles de lueur, échelle et un aperçu ; le clic du milieu masque un rappel jusqu'au prochain écran de chargement",
    ["Broken numeric values are removed before saving and reported at the next login. A single such value used to reset every setting of the account to defaults"] = "Les valeurs numériques cassées sont retirées avant la sauvegarde et signalées à la connexion suivante. Une seule valeur de ce genre remettait tous les réglages du compte par défaut",
    ["Totemic Recall stands as its own button after the elements on Wrath clients"] = "Le rappel des totems a son propre bouton après les éléments sur les clients Wrath",
    ["Talent Window – All three talent trees side by side with live ranks and click-to-learn on Wrath clients; glyphs stay one button away"] = "Fenêtre des talents – Les trois arbres de talents côte à côte avec rangs en direct et apprentissage au clic sur les clients Wrath ; les glyphes restent à un bouton",
    ["The string is selected - press Ctrl+C to copy it."] = "La chaîne est sélectionnée : appuyez sur Ctrl+C pour la copier.",
    ["%d characters"] = "%d caractères",
    ["Paste the string here with Ctrl+V."] = "Collez la chaîne ici avec Ctrl+V.",
    ["String captured - %d characters."] = "Chaîne capturée : %d caractères.",
    ["Partial string: anything missing is taken from your active profile."] = "Chaîne partielle : ce qui manque est repris de votre profil actif.",
    ["Unticked parts keep your current settings."] = "Les éléments décochés conservent vos réglages actuels.",
    ["Profile '%s' imported. Switch to it now and reload the UI?"] = "Profil '%s' importé. Basculer dessus maintenant et recharger l'interface ?",
    ["Switch and reload"] = "Basculer et recharger",
    ["Save a backup copy"] = "Créer une copie de sauvegarde",
    ["Creates a dated copy of the active profile as a restore point. Nothing switches - the copy just sits in the profile list."] = "Crée une copie datée du profil actif comme point de restauration. Rien ne change : la copie reste simplement dans la liste des profils.",
    ["Backup '%s' created."] = "Copie de sauvegarde '%s' créée.",
    ["Go back"] = "Retour",
    ["Pixel-true plate size"] = "Taille des plaques au pixel près",
    ["Sizes the plates in screen pixels instead of interface units: height 27 is then 27 pixels on any monitor and UI scale."] = "Dimensionne les plaques en pixels d'écran au lieu d'unités d'interface : une hauteur de 27 fait alors 27 pixels sur tout écran et à toute échelle.",
    -- Patch notes 1.47.0
    ["The boxes now cover their window exactly, in the same dark look as the rest of the interface, with the name centred and shown in orange when the window is docked to another one"] = "Les cadres couvrent désormais exactement leur fenêtre, dans le même style sombre que le reste de l'interface, avec le nom centré et affiché en orange quand la fenêtre est ancrée à une autre",
    ["Outside the editor the small drag handle stays, so an unlocked cooldown bar still accepts dropped spells and test previews stay visible"] = "Hors de l'éditeur, la petite poignée reste, si bien qu'une barre de recharges déverrouillée accepte toujours les sorts déposés et que les aperçus de test restent visibles",
    ["The cloak equipment slot was translated with the navigation word for back in six languages and now reads correctly everywhere"] = "L'emplacement d'équipement de la cape était traduit dans six langues par le mot de navigation retour et se lit désormais correctement partout",
    ["Pixel-true plate size – Sizes the plates in screen pixels, so height 27 is 27 pixels on any monitor and interface scale"] = "Taille des plaques au pixel près – Dimensionne les plaques en pixels d'écran : une hauteur de 27 fait 27 pixels sur tout écran et à toute échelle d'interface",
    ["Plate sizes now mean exactly what the sliders say: the game no longer secretly enlarges the target's plate or shrinks distant ones, and the live preview matches the game — making the target larger is now solely the job of the target plate scale option"] = "Les tailles de plaques correspondent désormais exactement aux réglages : le jeu n'agrandit plus en douce la plaque de la cible et ne rétrécit plus les plaques lointaines, et l'aperçu en direct correspond au jeu — agrandir la cible relève désormais uniquement de l'option d'échelle de la plaque de cible",
    ["Save a backup copy – One click keeps a dated copy of the active profile as a restore point"] = "Créer une copie de sauvegarde – Un clic conserve une copie datée du profil actif comme point de restauration",
    ["Exporting opens a proper window with the string already selected, and importing shows a preview first: rename the profile and untick the parts you do not want before anything is written"] = "L'export ouvre une vraie fenêtre avec la chaîne déjà sélectionnée, et l'import affiche d'abord un aperçu : renommez le profil et décochez ce que vous ne voulez pas avant que quoi que ce soit ne soit écrit",
    ["Export strings are compressed to a fraction of their old length and fit in a chat message; strings from older versions still import"] = "Les chaînes d'export sont compressées à une fraction de leur ancienne longueur et tiennent dans un message de discussion ; les chaînes des versions précédentes s'importent toujours",
    ["On the Wrath client the talent tooltip showed a placeholder instead of the description, and the talent key would open the window but not close it — both fixed"] = "Sur le client Wrath, l'infobulle de talent affichait un espace réservé au lieu de la description, et la touche des talents ouvrait la fenêtre sans pouvoir la fermer — les deux sont corrigés",
    ["%s Locked"] = "%s verrouillée",
    ["|cffffffffLOSS OF CONTROL|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffPERTE DE CONTRÔLE|r\n|cffaaaaaaGlisser ou touches fléchées|r",
    ["%.1f seconds"] = "%.1f secondes",
    ["Loss of control mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Déplacement de la perte de contrôle actif. |cff9b6cffFaites glisser la boîte violette|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Appuyez de nouveau sur le bouton pour terminer.",
    ["Preview"] = "Aperçu",
    ["Loss of Control"] = "Perte de contrôle",
    ["Shows what is controlling you right now -- stun, fear, root, silence, disarm or a school lockout -- with the effect icon, its name and the time left. Where two effects run at once the one that matters is shown large, and the next one as a small icon beside it."] = "Affiche ce qui vous contrôle en ce moment – étourdissement, peur, entrave, silence, désarmement ou école verrouillée – avec l’icône de l’effet, son nom et le temps restant. Si deux effets sont actifs en même temps, le plus important est affiché en grand et le suivant sous forme de petite icône à côté.",
    ["Show loss of control alert"] = "Afficher l’alerte de perte de contrôle",
    ["Show in"] = "Afficher dans",
    ["Arena and battlegrounds"] = "Arènes et champs de bataille",
    ["Arena only"] = "Arènes uniquement",
    ["Name font size"] = "Taille de police du nom",
    ["Timer font size"] = "Taille de police du temps",
    ["Background and red lines"] = "Fond et lignes rouges",
    ["Show the next effect"] = "Afficher l’effet suivant",
    ["Profile changed. Use /reload when you are out of combat."] = "Profil changé. Utilisez /reload une fois hors combat.",
    ["Profile keybind"] = "Raccourci du profil",
    ["Switches to this profile outside combat and then asks to reload the UI. Override bindings are restored at login."] = "Bascule vers ce profil hors combat, puis propose de recharger l’interface. Les raccourcis sont restaurés à la connexion.",
    ["Use the global font"] = "Utiliser la police globale",
    ["Name color"] = "Couleur du nom",
    ["Timer color"] = "Couleur du temps",
    ["|cffffffffINTERRUPTS|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffINTERRUPTIONS|r\n|cffaaaaaaGlisser ou touches fléchées|r",
    ["Interrupt bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Press the button again to finish."] = "Déplacement de la barre d’interruptions actif. |cff9b6cffFaites glisser la boîte violette|r ou utilisez les |cff9b6cfftouches fléchées|r (MAJ = 5 px). Appuyez de nouveau sur le bouton pour terminer.",
    ["Interrupts"] = "Interruptions",
    ["Watches the combat log for enemy interrupts and starts a cooldown for each one, tracked per caster -- two enemies of the same class get an icon each. The border carries the caster's class colour."] = "Surveille le journal de combat pour repérer les interruptions ennemies et lance un temps de recharge pour chacune, par lanceur : deux ennemis de la même classe obtiennent chacun une icône. La bordure porte la couleur de classe du lanceur.",
    ["Show interrupt bar"] = "Afficher la barre d’interruptions",
    ["Show interrupts that are still ready"] = "Afficher aussi les interruptions disponibles",
    ["Timer text on the icons"] = "Texte du temps sur les icônes",
    ["Cooldown swipe on the icons"] = "Balayage de recharge sur les icônes",
    ["Only take over the key while a fishing pole is worn"] = "Occuper la touche uniquement avec une canne équipée",
    ["Without a pole in hand the key keeps whatever you bound it to, so it stays usable outside fishing. A cast already in the water keeps the key. This switches off auto-equipping a pole, which needs the key exactly while none is worn."] = "Sans canne en main la touche garde ce que vous lui avez assigné, elle reste donc utilisable en dehors de la pêche. Un lancer déjà à l’eau conserve la touche. Cela désactive l’équipement automatique de la canne, qui a besoin de la touche précisément quand aucune n’est portée.",
    ["Stand-in for an enemy frame: the side strip is placed by the settings below."] = "Substitut de cadre ennemi : la bande latérale est placée par les réglages ci-dessous.",
    -- Patch notes 1.48.0
    ["Options Window"] = "Fenêtre des options",
    ["Loss of Control – Shows the stun, fear, root, silence or lockout holding you, with its icon, its name and the time left"] = "Perte de contrôle – Affiche l’étourdissement, la peur, l’entrave, le silence ou le verrouillage qui vous tient, avec son icône, son nom et le temps restant",
    ["Interrupts – Tracks enemy interrupts from the combat log, one icon per caster, bordered in the caster's class colour"] = "Interruptions – Suit les interruptions ennemies dans le journal de combat, une icône par lanceur, bordée de la couleur de sa classe",
    ["Timer Text On The Icons – Seconds left on the interrupt icons, with their own font, outline and colour"] = "Texte du temps sur les icônes – Secondes restantes sur les icônes d’interruption, avec leur propre police, contour et couleur",
    ["Cooldown Swipe On The Icons – Drop the sweeping shade and keep only the number"] = "Balayage de recharge sur les icônes – Retire l’ombre qui tourne et ne garde que le nombre",
    ["The icon strip beside the enemy frames has a live preview on the General tab. Those frames exist only inside an arena, so its sliders used to move something you could not see."] = "La bande d’icônes à côté des cadres ennemis dispose d’un aperçu en direct dans l’onglet Général. Ces cadres n’existent que dans une arène, ses réglages déplaçaient donc quelque chose d’invisible.",
    ["An unlocked mover box no longer vanished a moment after the button put it there. The box and a running preview now ignore the zone filter: you place a bar where you are standing, and that is rarely an arena."] = "Une boîte de déplacement déverrouillée ne disparaît plus un instant après que le bouton l’a affichée. La boîte et un aperçu en cours ignorent désormais le filtre de zone : on place une barre là où l’on se trouve, et c’est rarement une arène.",
    ["The pinned icon strip also appears on the Layout tab, where icon size, spacing, shape and zoom read back off it while the slider moves."] = "La bande d’icônes épinglée apparaît maintenant aussi dans l’onglet Disposition, où la taille, l’espacement, la forme et le zoom se lisent dessus pendant que le curseur bouge.",
    ["Moving Blizzard frames no longer marks every Edit Mode window as touched by this addon, which had the pet frame refused in combat. Selecting a layout caused it, and that ran on every editor entry even when nothing had been placed."] = "Déplacer les cadres de Blizzard ne marque plus chaque fenêtre du mode édition comme touchée par cet accessoire, ce qui faisait refuser l’affichage du cadre de familier en combat. La cause était la sélection d’une disposition, et cela se produisait à chaque entrée dans l’éditeur même si rien n’avait jamais été placé.",
    ["The icon picker has a close button, and no longer floats over the game after the character sheet is shut."] = "Le sélecteur d’icônes possède un bouton de fermeture et ne flotte plus au-dessus du jeu une fois la feuille de personnage refermée.",
    ["Only Take Over The Key While A Fishing Pole Is Worn – Without a pole the key keeps whatever you bound it to"] = "Occuper la touche uniquement avec une canne équipée – Sans canne la touche garde ce que vous lui avez assigné",
    ["The mouse wheel scrolls the sidebar and the page. The window also shrinks to fit a screen smaller than itself, which is what left it undraggable on a high interface scale."] = "La molette fait défiler la barre latérale et la page. La fenêtre se réduit aussi pour tenir sur un écran plus petit qu’elle, ce qui est précisément ce qui la rendait impossible à déplacer à forte échelle d’interface.",
    ["Profile Keybind – Put a profile on a key and switch to it out of combat"] = "Raccourci du profil – Placez un profil sur une touche et basculez dessus hors combat",
    ["The bag sweep behind the food, flask and weapon oil reminders is kept until the bags change, instead of walking every bag three times over twice a second."] = "Le balayage des sacs derrière les rappels de nourriture, de flacon et d’huile d’arme est conservé jusqu’à ce que les sacs changent, au lieu de parcourir tous les sacs trois fois deux fois par seconde.",
    ["The modern player frame style no longer reaches into the pet and totem frames."] = "Le style moderne du cadre de joueur ne touche plus les cadres de familier et de totem.",
    ["Fine tuning for this slot"] = "Réglage fin de cet emplacement",
    ["Slot settings"] = "Réglages de l'emplacement",
    ["Border settings"] = "Réglages de la bordure",
    ["Border size"] = "Épaisseur de la bordure",
    ["How solid the empty part of the bar is."] = "Opacité de la partie vide de la barre.",
    ["Absorb settings"] = "Réglages de l'absorption",
    ["Border around the cast bar"] = "Bordure autour de la barre de sort",
    ["Off leaves the cast bar without its own outline; the health bar keeps one."] = "Désactivé laisse la barre de sort sans contour propre ; la barre de vie garde le sien.",
    ["Top text"] = "Texte du haut",
    ["Left text"] = "Texte de gauche",
    ["Right text"] = "Texte de droite",
    ["Centred text"] = "Texte centré",
    ["Unit name"] = "Nom de l'unité",
    ["Main text positions"] = "Positions principales du texte",
    ["|cffaaaaaaOne thing per slot. The level rides at the name's left edge and follows it.|r"] = "|cffaaaaaaUne chose par emplacement. Le niveau se place au bord gauche du nom et le suit.|r",
    ["Health and cast bar"] = "Barre de vie et de sort",
    ["Health bar width"] = "Largeur de la barre de vie",
    ["Health bar height"] = "Hauteur de la barre de vie",
    ["Cast icon"] = "Icône de sort",
    ["Cast icon settings"] = "Réglages de l’icône de sort",
    ["Cast background"] = "Fond de la barre de sort",
    ["Cast bar border"] = "Bordure de la barre de sort",
    ["Thickness of the cast bar's own border. 0 removes it; the health bar keeps its own."] = "Épaisseur de la bordure propre à la barre de sort. 0 la supprime ; la barre de vie garde la sienne.",
    ["Cast bar border colour"] = "Couleur de la bordure de la barre de sort",
    ["Cast timer"] = "Minuteur de sort",
    ["Cast timer settings"] = "Réglages du minuteur",
    ["Cast bar Y offset"] = "Décalage Y de la barre de sort",
    ["Cast colours and effects"] = "Couleurs et effets des sorts",
    ["The bar's colour while a spell is being cast."] = "La couleur de la barre pendant l’incantation.",
    ["More cast colours"] = "Autres couleurs de sort",
    ["Interrupt ready"] = "Interruption prête",
    ["Interrupt flash"] = "Éclair d’interruption",
    ["Interrupt-ready hint"] = "Indice : interruption prête",
    ["Show cast bars in front of nameplates"] = "Afficher les barres de sort devant les barres de nom",
    ["Casts draw above every plate, so a cast you care about is never hidden behind another unit's bar."] = "Les incantations sont dessinées au-dessus de toutes les barres de nom, pour qu’une incantation importante ne soit jamais masquée par celle d’une autre unité.",
    ["The enemy's cast bar flashes and reads 'Interrupted' for a moment when their cast is stopped."] = "La barre de sort de l’ennemi clignote et affiche brièvement « Interrompu » lorsque son incantation est stoppée.",
    ["Interrupt flash settings"] = "Réglages de l’éclair d’interruption",
    ["Target, focus and hover effects"] = "Effets de cible, de focus et de survol",
    ["Target effect"] = "Effet de cible",
    ["A coloured edge around the plate you have targeted."] = "Une bordure colorée autour de la barre que vous ciblez.",
    ["Target effect settings"] = "Réglages de l’effet de cible",
    ["Target arrows"] = "Flèches de cible",
    ["Arrow settings"] = "Réglages des flèches",
    ["Target bar colour on"] = "Activer la couleur de cible",
    ["Focus bar colour on"] = "Activer la couleur de focus",
    ["A coloured edge around the plate you have set as your focus."] = "Une bordure colorée autour de la barre définie comme focus.",
    ["Mouseover effect"] = "Effet de survol",
    ["Mouseover effect settings"] = "Réglages de l’effet de survol",
    ["General text"] = "Texte général",
    ["Debuff duration"] = "Durée des affaiblissements",
    ["Buff duration"] = "Durée des améliorations",
    ["Crowd control duration"] = "Durée du contrôle",
    ["Aura stacks"] = "Cumuls d’aura",
    ["Timer text colour"] = "Couleur du minuteur",
    ["Stack text colour"] = "Couleur des cumuls",
    ["Text settings"] = "Réglages du texte",
    ["Spell target"] = "Cible du sort",
    ["Background settings"] = "Réglages du fond",
    ["Hide the gryphons"] = "Masquer les griffons",
    ["Removes the two beasts at the ends of Blizzard's main action bar. The bar itself stays."] = "Retire les deux bêtes aux extrémités de la barre d’action d’origine. La barre elle-même reste.",
    ["Extra indicators"] = "Indicateurs supplémentaires",
    ["Enemy colours"] = "Couleurs des ennemis",
    ["Enemy types"] = "Types d’ennemis",
    ["The health bar colour a unit takes from its reaction to you."] = "La couleur que la barre prend selon l’attitude de l’unité envers vous.",
    ["Neutral enemies"] = "Ennemis neutres",
    ["Units that are not hostile until you make them so."] = "Des unités qui ne deviennent hostiles que si vous les provoquez.",
    ["Other nameplates"] = "Autres barres de nom",
    ["Nameplate spacing"] = "Espacement des barres de nom",
    ["|cffaaaaaaThe game's own settings, changed live and not part of the profile — except the hitbox. Not changeable in combat.|r"] = "|cffaaaaaaRéglages propres au jeu, appliqués aussitôt et hors du profil — sauf la zone de clic. Non modifiables en combat.|r",
    ["Stackable nameplates"] = "Barres de nom empilables",
    ["Extra aura options"] = "Options d’auras supplémentaires",
    ["Target and focus effects"] = "Effets de cible et de focus",
    ["Plate scale while casting"] = "Taille de la barre pendant l’incantation",
    ["A casting unit's plate grows to this size, so the one that matters stands out. 100 = off."] = "La barre d’une unité qui incante grandit jusqu’à cette taille, pour que celle qui compte ressorte. 100 = désactivé.",
    ["Opacity while casting"] = "Opacité pendant l’incantation",
    ["A casting unit's plate is at least this opaque, even when something else is targeted."] = "La barre d’une unité qui incante garde au moins cette opacité, même si vous ciblez autre chose.",
    ["The unit's name gives way to the spell name for as long as the cast runs."] = "Le nom de l’unité cède la place au nom du sort pendant toute l’incantation.",
    ["Active talent group"] = "Groupe de talents actif",
    ["Left-click: show this talent group"] = "Clic gauche : afficher ce groupe de talents",
    ["Right-click: activate this talent group"] = "Clic droit : activer ce groupe de talents",
    ["Talent group %d (not active)"] = "Groupe de talents %d (inactif)",
    ["Talents can only be learned in the active talent group."] = "Les talents ne peuvent être appris que dans le groupe de talents actif.",
    ["Talent groups cannot be switched in combat."] = "Impossible de changer de groupe de talents en combat.",
    ["This client refused to switch the talent group."] = "Ce client a refusé de changer de groupe de talents.",
    ["Input line above the chat"] = "Ligne de saisie au-dessus du chat",
    ["Puts the chat input line above the message area instead of below it. The panel and the tab bar follow it."] = "Place la ligne de saisie au-dessus de la zone des messages plutôt qu’en dessous. Le panneau et la barre d’onglets la suivent.",
    ["Own background for the input line"] = "Fond personnalisé pour la ligne de saisie",
    ["Draws the input line on our own dark background instead of Blizzard's. The dark background panel already covers the input line, so this shows once that panel is off."] = "Dessine la ligne de saisie sur notre propre fond sombre au lieu de celui de Blizzard. Le panneau de fond sombre couvre déjà la ligne de saisie, cela se voit donc une fois ce panneau désactivé.",
    ["Addon buttons"] = "Boutons d’addons",
    ["Click to show or hide the collected buttons."] = "Cliquez pour afficher ou masquer les boutons regroupés.",
    ["Where other addons' minimap buttons sit: around the map, hidden until the mouse is over it, or gathered in one box under it."] = "Où se placent les boutons de minicarte des autres addons : autour de la carte, masqués jusqu’au survol de la souris, ou regroupés dans une boîte en dessous.",
    ["Around the minimap"] = "Autour de la minicarte",
    ["Only on mouseover"] = "Seulement au survol",
    ["Collected in a box"] = "Regroupés dans une boîte",
    -- Patch notes 1.49.0
    ["Hide The Gryphons – Takes the two beasts off the ends of Blizzard's main bar without dimming anything else"] = "Masquer les griffons – Retire les deux bêtes aux extrémités de la barre principale de Blizzard sans assombrir quoi que ce soit d’autre",
    ["Switching the module off now switches it off. Its handlers are registered when the addon loads, so a module that was already off at login never ran its shutdown: being stunned in a battleground still popped the loss-of-control display, and the interrupt bar filled up and never emptied again, because the ticker that clears its icons only starts when the module is switched on."] = "Désactiver le module le désactive vraiment maintenant. Ses gestionnaires sont enregistrés au chargement, donc un module déjà désactivé à la connexion n’exécutait jamais son extinction : être étourdi dans un champ de bataille faisait quand même apparaître l’affichage de perte de contrôle, et la barre d’interruptions se remplissait sans jamais se vider, parce que le minuteur qui nettoie ses icônes ne démarre qu’à l’activation.",
    ["The interrupt bar no longer reads the whole world's combat log. It registered on load and never unregistered, so every combat line anywhere — several thousand a second in a raid — was taken apart for a bar whose own default is arena and battlegrounds only. It uses the same zone filter as the display beside it now."] = "La barre d’interruptions ne lit plus le journal de combat du monde entier. Elle s’enregistrait au chargement et ne se désenregistrait jamais, si bien que chaque ligne de combat où que ce soit — plusieurs milliers par seconde en raid — était décortiquée pour une barre dont la valeur par défaut est arène et champs de bataille uniquement. Elle utilise désormais le même filtre de zone que l’affichage voisin.",
    ["Switching the module on inside an arena counts as arriving. The zone decision used to live in the loading screen alone, so anyone who enabled it while already in there got no diminishing-returns ticker until the next one."] = "Activer le module dans une arène compte comme une arrivée. La décision de zone ne vivait que dans l’écran de chargement, donc quiconque l’activait déjà à l’intérieur n’avait pas de minuteur de réduction jusqu’à la suivante.",
    ["The item level text size slider works again. It looked for the numbers in two places it hoped they would be, and where a client parents its paper doll buttons elsewhere it found none and quietly did nothing — which from the outside is indistinguishable from the text simply being too small."] = "Le curseur de taille du texte de niveau d’objet fonctionne de nouveau. Il cherchait les nombres à deux endroits où il espérait les trouver, et là où un client rattache ses boutons d’équipement ailleurs, il n’en trouvait aucun et ne faisait rien en silence — ce qui, de l’extérieur, ne se distingue pas d’un texte simplement trop petit.",
    ["Input Line Above The Chat – Puts the input line over the message area instead of under it, with the panel and the tab bar following it; Wrath client only"] = "Ligne de saisie au-dessus du chat – Place la ligne de saisie au-dessus de la zone des messages plutôt qu’en dessous, le panneau et la barre d’onglets la suivent ; client Wrath uniquement",
    ["Own Background For The Input Line – Draws the input line on its own dark background instead of Blizzard's, which is what you saw once the dark panel was off; Wrath client only"] = "Fond personnalisé pour la ligne de saisie – Dessine la ligne de saisie sur son propre fond sombre au lieu de celui de Blizzard, celui que vous voyiez une fois le panneau sombre désactivé ; client Wrath uniquement",
    ["Icon zoom is now called Icon crop and reads in percent. It is the same question the nameplate sliders ask, and it was answering in hundredths while they answered in percent."] = "Le zoom des icônes s’appelle maintenant rognage des icônes et se lit en pourcentage. C’est la même question que posent les curseurs des barres de nom, et elle répondait en centièmes tandis que ceux-ci répondaient en pourcentage.",
    ["The extra width belongs to the friends tab alone now. The row texts there stretch with the window, but the column headers on the who, guild and raid tabs sit at fixed offsets and stay put, so every point of width you added landed in an empty right half. Those three tabs go back to Blizzard's own proportions, which is what their columns were measured for."] = "La largeur supplémentaire appartient désormais au seul onglet des amis. Les textes des lignes s’y étirent avec la fenêtre, mais les en-têtes de colonne des onglets recherche, guilde et raid sont à des décalages fixes et ne bougent pas, si bien que chaque point de largeur ajouté finissait dans une moitié droite vide. Ces trois onglets reviennent aux proportions de Blizzard, celles pour lesquelles leurs colonnes ont été mesurées.",
    ["The set list and the icon picker take the character panel's style. In the classic style they used to be a flat dark surface with a purple edge holding Blizzard's red buttons — two materials in a hand's width. They now carry Blizzard's dialog frame there and stand in the same material as the window they hang off, while the modern style keeps the flat look."] = "La liste des ensembles et le sélecteur d’icônes prennent le style de la fenêtre de personnage. Dans le style classique, c’était une surface sombre et plate à bord violet contenant les boutons rouges de Blizzard — deux matières sur une largeur de main. Elles portent désormais le cadre de dialogue de Blizzard et se tiennent dans la même matière que la fenêtre à laquelle elles s’accrochent, tandis que le style moderne garde l’aspect plat.",
    ["The character panel no longer breaks when the sidebar builds its first set row. The marker bar on the row still reached for an accent colour that had been removed, so the list stayed empty and the panel came up bare."] = "La fenêtre de personnage ne casse plus quand la barre latérale construit sa première ligne d’ensemble. La barre de marquage de la ligne cherchait encore une couleur d’accentuation qui avait été retirée, la liste restait donc vide et la fenêtre s’ouvrait nue.",
    ["Addon Buttons – Choose where other addons' buttons sit: around the map, hidden until you mouse over it, or gathered in one box below it; Wrath client only"] = "Boutons d’addons – Choisissez où se placent les boutons des autres addons : autour de la carte, masqués jusqu’au survol de la souris, ou regroupés dans une boîte en dessous ; client Wrath uniquement",
    ["Icon Crop (%) – How much of the border the game bakes into its icons is cut away, set per aura row and for the cast bar icon"] = "Rognage des icônes (%) – Quelle part de la bordure que le jeu intègre à ses icônes est retirée, réglable par rangée d’auras et pour l’icône de la barre d’incantation",
    ["The rounded bar style no longer leaves dead space at both ends. The round shape does not fill its own image — a transparent border runs all the way round it — and stretching that border across a wide, short bar put roughly eleven points of empty bar at each end and barely one above and below, which is why it showed up sideways and not upright."] = "Le style de barre arrondie ne laisse plus d’espace mort aux deux extrémités. La forme ronde ne remplit pas sa propre image — une bordure transparente en fait tout le tour —, et étirer cette bordure sur une barre large et basse laissait environ onze points de barre vide à chaque bout et à peine un en haut et en bas, d’où une gêne à l’horizontale et pas à la verticale.",
    ["The options page is cut by question instead of by mechanism. Sixteen sections had settings that belong together lying far apart, with the bar texture under one heading and the cast bar's texture under another; eight settings were reachable from two sections at once."] = "La page d’options est découpée par questions plutôt que par mécanique. Seize sections avaient des réglages qui vont ensemble éloignés les uns des autres, la texture de la barre sous un titre et celle de la barre d’incantation sous un autre ; huit réglages étaient accessibles depuis deux sections à la fois.",
    ["Every text on the plate sits in a slot now, the way the aura rows already did: top, left, right or centred, filled with the unit name or the health text. Four on/off switches became position pickers, each starting on the place its text already had."] = "Chaque texte de la barre de nom occupe maintenant un emplacement, comme le faisaient déjà les rangées d’auras : en haut, à gauche, à droite ou centré, rempli du nom de l’unité ou du texte de vie. Quatre interrupteurs sont devenus des sélecteurs de position, chacun démarrant à l’endroit que son texte occupait déjà.",
    ["The stacking dropdown had no readable value at all. It was reading a setting this client does not have; the one it does have is now read and written, measured in the running game."] = "Le menu déroulant d’empilement n’affichait aucune valeur lisible. Il lisait un réglage que ce client n’a pas ; celui qu’il a est désormais lu et écrit, mesuré dans le jeu en marche.",
    ["A gear icon on a half-width row opens a small floating window instead of unfolding inside the cell. Half a cell has no room for a slider, and six of them had been squeezed into stubs."] = "Un engrenage sur une ligne de demi-largeur ouvre une petite fenêtre flottante au lieu de se déplier dans la cellule. Une demi-cellule n’a pas la place d’un curseur, et six d’entre eux y avaient été réduits à des moignons.",
    ["Colour swatches, eyes, gears and arrows sit directly beside the control they belong to rather than in the icon strip on the right, which stays reserved for the gear and the info dot."] = "Les pastilles de couleur, les yeux, les engrenages et les flèches se placent juste à côté du contrôle auquel ils appartiennent plutôt que dans la bande d’icônes à droite, qui reste réservée à l’engrenage et au point d’information.",
    ["On the Wrath client the module stands down completely and the client keeps its own window. Our restyle addresses Blizzard's widgets by name and by region number, and behind those names that client has a different anatomy: black holes where the hidden regions used to be, a stretched title bar, dropdowns over the recipe list — and no error, because nothing throws, it simply lands on the wrong widgets."] = "Sur le client Wrath, le module se retire complètement et le client garde sa propre fenêtre. Notre habillage s’adresse aux éléments de Blizzard par leur nom et par leur numéro de région, et derrière ces noms ce client a une autre anatomie : des trous noirs là où étaient les régions masquées, une barre de titre étirée, des menus déroulants par-dessus la liste des recettes — et aucune erreur, car rien ne plante, cela atterrit simplement sur les mauvais éléments.",
    ["Talent group buttons run down the right edge, one for each group you have bought. Left-click shows a group, right-click activates it, the same split Blizzard's own window uses. Talents can only be learned in the active group, so a click in the preview does nothing and the tooltip says so beforehand."] = "Le long du bord droit courent des boutons de groupes de talents, un par groupe acheté. Le clic gauche affiche un groupe, le clic droit l’active, la même répartition que celle de la fenêtre de Blizzard. Les talents ne s’apprennent que dans le groupe actif, un clic dans l’aperçu ne fait donc rien et l’infobulle le dit à l’avance.",
    ["The tab carries a book instead of a question mark. That mark is Blizzard's placeholder for a missing icon and read like a defect."] = "L’onglet porte un livre plutôt qu’un point d’interrogation. Cette marque est l’espace réservé de Blizzard pour une icône manquante et se lisait comme un défaut.",
    ["Glyphs"] = "Glyphes",
    ["CHARACTER"] = "Personnage",
    ["Packs the selected bar setup into a string you can pass on. Slots, macros and key bindings travel with it."] = "Emballe le réglage de barres sélectionné dans une chaîne que vous pouvez transmettre. Les emplacements, les macros et les raccourcis voyagent avec.",
    ["Reads a bar setup string into your library. Putting it onto your bars stays a separate step."] = "Lit une chaîne de réglage de barres dans votre bibliothèque. L’appliquer à vos barres reste une étape distincte.",
    ["The bar setup string is damaged."] = "La chaîne du réglage de barres est endommagée.",
    ["This is not a bar setup string."] = "Ceci n’est pas une chaîne de réglage de barres.",
    ["Bar setup '%s' imported."] = "Réglage de barres '%s' importé.",
    ["Macros left alone: the switch above is off."] = "Macros non touchées : l’interrupteur ci-dessus est désactivé.",
    ["Macros: %d restored, |cffff8800%d failed|r -- the macro list may be full."] = "Macros : %d restaurées, |cffff8800%d échouées|r — la liste des macros est peut-être pleine.",
    ["Macros: %d restored."] = "Macros : %d restaurées.",
    ["Key bindings left alone: the switch above is off."] = "Raccourcis non touchés : l’interrupteur ci-dessus est désactivé.",
    ["Key bindings: %d applied."] = "Raccourcis clavier : %d appliqués.",
    ["Bar setup '%s' saved: %d slots, %d macros, %d key bindings."] = "Réglage de barres '%s' enregistré : %d emplacements, %d macros, %d raccourcis clavier.",
    ["|cffff8800No key bindings were captured.|r This client may not report them."] = "|cffff8800Aucun raccourci clavier n’a été capturé.|r Ce client ne les signale peut-être pas.",
    -- Patch notes 1.50.0
    ["Export as string – Packs the selected setup into a string you can pass on, with its slots, macros and key bindings"] = "Exporter en chaîne – Emballe le réglage sélectionné dans une chaîne que vous pouvez transmettre, avec ses emplacements, ses macros et ses raccourcis",
    ["Import from string – Reads someone else's setup into your library; a name you already use gets a number rather than being overwritten"] = "Importer depuis une chaîne – Lit le réglage de quelqu’un d’autre dans votre bibliothèque ; un nom que vous utilisez déjà reçoit un numéro au lieu d’être écrasé",
    ["An imported setup is rebuilt entry by entry before it is stored. The restore walks every entry, so a malformed one would have thrown in the middle of a run with part of your bars already changed. Broken entries are dropped, the rest still arrives."] = "Un réglage importé est reconstruit entrée par entrée avant d’être rangé. La restauration parcourt chaque entrée, donc une entrée mal formée aurait planté en plein milieu, une partie de vos barres déjà modifiée. Les entrées cassées sont écartées, le reste arrive quand même.",
    ["Saving and loading say what they did. Both had been counting their work all along and throwing the numbers away, so a setup whose macros all failed looked exactly like one that had none, and a save that captured no key bindings said nothing at all."] = "L’enregistrement et le chargement disent ce qu’ils ont fait. Tous deux comptaient leur travail depuis toujours et jetaient les chiffres : un réglage dont toutes les macros échouaient ressemblait à un réglage sans macros, et un enregistrement sans aucun raccourci capturé ne disait rien du tout.",
    ["The character window can be placed by hand on the Wrath client. Blizzard's editor does not own that window, so it takes the same direct route the loot window already uses; one box moves the character, reputation and skills tabs together, and the stats panel and set list travel with it."] = "La fenêtre de personnage peut être placée à la main sur le client Wrath. L’éditeur de Blizzard ne possède pas cette fenêtre, elle emprunte donc la même voie directe que la fenêtre de butin ; une boîte déplace ensemble les onglets personnage, réputation et compétences, et le panneau de statistiques et la liste d’ensembles voyagent avec.",
    ["The window starts wide on the Wrath client. The slider has always gone to 400 — it simply started at nothing, so the extra room only ever reached whoever went looking for it."] = "La fenêtre démarre large sur le client Wrath. Le curseur est toujours monté à 400 — il partait simplement de rien, si bien que la place gagnée n’atteignait que celui qui allait la chercher.",
    ["The glyph page opens from a button under the talent group buttons, and it is dark now. The rune circle is dimmed rather than removed, because it is what makes that page recognisable; the sockets take the accent colour, and the glyph artwork and the pickup highlight stay as they are."] = "La page des glyphes s’ouvre par un bouton sous les boutons de groupe de talents, et elle est sombre désormais. Le cercle runique est assombri plutôt que retiré, car c’est lui qui rend cette page reconnaissable ; les châsses prennent la couleur d’accentuation, et l’illustration du glyphe et la surbrillance de prise restent telles quelles.",
    ["The talent group button shows its tree's icon instead of a question mark. It asked for that icon through an interface that does not answer on every client, and fell back to the placeholder; the answer is now worked out from the ranks themselves, which cannot be misread."] = "Le bouton de groupe de talents affiche l’icône de son arbre au lieu d’un point d’interrogation. Il la demandait via une interface qui ne répond pas sur tous les clients et se rabattait sur l’espace réservé ; la réponse est maintenant déduite des rangs eux-mêmes, qui ne peuvent pas être mal lus.",
    ["The level number on the player frame sits where the client puts it on the Wrath client. Our two anchors are measured against one frame sheet, and where a different one ships, the number landed beside the portrait — the client keeps that anchor itself there anyway, moving it as the rest and PvP icons come and go."] = "Le niveau sur la fenêtre du joueur se place là où le client le met, sur le client Wrath. Nos deux ancrages sont mesurés sur une planche de cadre, et là où une autre est livrée, le nombre atterrissait à côté du portrait — le client y entretient cet ancrage lui-même et le déplace au gré des icônes de repos et JcJ.",

    -- Character Panel: socket strip
    ["Socket strip under the window"] = "Barre de châsses sous la fenêtre",
    ["Puts a strip with every socket of your equipped gear under the character window. Click a socket to put a gem from your bags into it. Stays empty on clients whose game has no gems."] = "Place sous la fenêtre du personnage une barre reprenant chaque châsse de votre équipement. Cliquez sur une châsse pour y sertir une gemme de vos sacs. Reste vide sur les clients dont le jeu ne connaît pas les gemmes.",
    ["Choose a gem"] = "Choisir une gemme",
    ["No gems in your bags."] = "Aucune gemme dans vos sacs.",
    ["Empty socket"] = "Châsse vide",
    ["Click to pick a gem from your bags."] = "Cliquez pour choisir une gemme dans vos sacs.",
    ["Cannot socket gems in combat."] = "Impossible de sertir des gemmes en combat.",
    ["Close the socketing window first."] = "Fermez d’abord la fenêtre de sertissage.",
    -- Patch notes 1.51.0
    ["Socket strip under the window – A row of every socket on your equipped gear, hung under the character window; click a socket to put a gem from your bags into it"] = "Barre de châsses sous la fenêtre – Une rangée reprenant chaque châsse de votre équipement, sous la fenêtre du personnage ; cliquez sur une châsse pour y sertir une gemme de vos sacs",
    ["The enchant text on armour slots reads the enchant again instead of the item's difficulty tag. The filter took the first green line of the tooltip, and where an item carries a tag that tag stands above the enchant — so every such slot showed the tag, while a weapon two rows down showed its enchant correctly because nothing stood in front of it. The tag and the client's bracketed hints are both recognised now, in every language rather than only in English and German."] = "Le texte d'enchantement sur les emplacements d'armure affiche de nouveau l'enchantement au lieu de la marque de difficulté de l'objet. Le filtre prenait la première ligne verte de l'infobulle, et lorsqu'un objet porte cette marque, elle se place au-dessus de l'enchantement — chaque emplacement affichait donc la marque, tandis qu'une arme deux rangées plus bas affichait correctement le sien, faute de quoi que ce soit devant. La marque et les indications entre chevrons du client sont désormais reconnues toutes les deux, et dans toutes les langues et non plus seulement en anglais et en allemand.",
    ["The set list no longer casts a shadow past its own frame. What looked like the background standing out over the border was a drop shadow: not an outline but four filled rectangles reaching up to seven pixels beyond the frame on every side, and behind Blizzard's dialog frame there was nothing for it to fall on. It is gone in both looks."] = "La liste des ensembles ne projette plus d'ombre au-delà de son propre cadre. Ce qui ressemblait à un fond débordant de la bordure était une ombre portée : non pas un contour, mais quatre rectangles pleins s'étendant jusqu'à sept pixels au-delà du cadre de chaque côté, et derrière le cadre de dialogue de Blizzard elle n'avait rien sur quoi tomber. Elle a disparu dans les deux styles.",
    ["In the Classic+ look the dark ground stopped short of the ornate line instead of ending on it, and so showed past the frame on every side."] = "Dans le style Classic+, le fond sombre s'arrêtait avant la ligne ornée au lieu de finir dessus, et débordait donc du cadre de tous les côtés.",

    -- Nameplates: layout preset + health text content
    ["Apply this arrangement"] = "Appliquer cette disposition",
    ["Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, and gives the cast bar its icon, its remaining time and its target. Your current arrangement is saved first and the button beside this one brings it back."] = "Place le nom de l'unité et la valeur de vie dans la barre, le contrôle de foule à sa gauche, les affaiblissements entrants au-dessus et les améliorations à sa droite, et donne à la barre d'incantation son icône, son temps restant et sa cible. Votre disposition actuelle est sauvegardée d'abord et le bouton voisin la restitue.",
    ["Restore my arrangement"] = "Restaurer ma disposition",
    ["Puts every text and aura position back to what it was before the arrangement was applied, and removes the saved copy. Anything you moved by hand since then goes back as well."] = "Remet chaque position de texte et d'aura telle qu'elle était avant l'application de la disposition, et supprime la copie sauvegardée. Tout ce que vous avez déplacé à la main depuis revient également.",
    ["Nameplate layout applied. The button beside it puts your old one back."] = "Disposition des plaques de nom appliquée. Le bouton voisin restitue l'ancienne.",
    ["Nameplate layout restored."] = "Disposition des plaques de nom restaurée.",
    ["Shows"] = "Affiche",
    ["Current health"] = "Vie actuelle",
    ["Current and maximum"] = "Actuelle et maximale",
    ["Current and percent"] = "Actuelle et pourcentage",
    ["Separator"] = "Séparateur",
    ["What goes between the two numbers, when the row above is set to current and percent."] = "Ce qui se place entre les deux nombres, lorsque la ligne du dessus est réglée sur actuelle et pourcentage.",
    ["Brackets"] = "Parenthèses",
    ["Vertical bar"] = "Barre verticale",
    ["Dash"] = "Tiret",
    ["Space"] = "Espace",
    -- Patch notes 1.52.0
    ["The own background for the input line is offered on every client. It was limited to one client generation, and the code already said it would work everywhere."] = "Le fond propre de la ligne de saisie est proposé sur tous les clients. Il était limité à une génération de client, et le code disait déjà qu'il fonctionnerait partout.",
    ["The icon borders are pixel-exact. The border there is not a texture of its own but the rim of a plate behind the icon, so the two have to sit on the same pixel grid, the thickness has to be counted in pixels rather than frame units, and the icon size and spacing have to begin on whole pixels. None of the three was true, which is why a rim came out two pixels on one edge and none on the opposite."] = "Les bordures des icônes sont exactes au pixel. La bordure n'y est pas une texture à part mais le liseré d'une plaque derrière l'icône : les deux doivent donc reposer sur la même grille de pixels, l'épaisseur se compter en pixels et non en unités de cadre, et la taille comme l'espacement commencer sur des pixels entiers. Aucune des trois n'était vraie, d'où un liseré de deux pixels d'un côté et d'aucun de l'autre.",
    ["Apply this arrangement – Puts the unit name and the health value inside the bar, crowd control left of it, incoming debuffs above that and buffs to its right, with the cast bar carrying its icon, its remaining time and its target"] = "Appliquer cette disposition – Place le nom de l'unité et la valeur de vie dans la barre, le contrôle de foule à sa gauche, les affaiblissements entrants au-dessus et les améliorations à sa droite, la barre d'incantation portant son icône, son temps restant et sa cible",
    ["The unit name was hidden behind the health bar fill as soon as a text slot put it inside the bar. The name and the health value hang from different parents: the value is created on the bar, the name on the plate, and the bar is a child of the plate — so it draws over anything the plate draws. While the name only ever sat above the bar this never showed. It has its own layer now, above the bar but not attached to it, because name-only mode hides that bar and a text parented to a hidden frame would go with it."] = "Le nom de l'unité disparaissait derrière le remplissage de la barre de vie dès qu'un emplacement de texte le plaçait dans la barre. Le nom et la valeur de vie dépendent de parents différents : la valeur est créée sur la barre, le nom sur la plaque, et la barre est un enfant de la plaque — elle dessine donc par-dessus tout ce que dessine la plaque. Tant que le nom ne se tenait qu'au-dessus de la barre, cela ne se voyait pas. Il a désormais sa propre couche, au-dessus de la barre sans y être rattaché, car le mode nom seul masque cette barre et un texte rattaché à un cadre masqué disparaîtrait avec lui.",
    ["The health text has its controls back: what it shows, and which mark goes between the two numbers. Both were still being read and had been unreachable since the page was rebuilt."] = "Le texte de vie retrouve ses réglages : ce qu'il affiche, et quel signe se place entre les deux nombres. Les deux étaient toujours lus et devenus inaccessibles depuis la refonte de la page.",
    ["The active talent group was always reported as the first one on clients that do not carry the newer interface for it. Everything behind that believed group one was running: the header called the group you were standing in not active, the activate button offered to switch to the one already on, and the switch reported success while changing nothing. Five files ask that same question, so profile overrides and bar setups were reading it too."] = "Le groupe de talents actif était toujours annoncé comme le premier sur les clients qui ne portent pas l'interface plus récente prévue pour cela. Tout ce qui suit croyait donc que le groupe un tournait : l'en-tête qualifiait de non actif le groupe dans lequel vous vous teniez, le bouton d'activation proposait de basculer sur celui déjà en cours, et la bascule annonçait une réussite sans rien changer. Cinq fichiers posent la même question, si bien que les remplacements de profil et les configurations de barres y puisaient aussi.",
    ["The glyph page stands permanently beside the window. It is lifted out of Blizzard's talent frame, where it lives inside the scroll area of the very window we replace, and handed back when ours closes."] = "La page des glyphes se tient en permanence à côté de la fenêtre. Elle est extraite du cadre de talents de Blizzard, où elle réside dans la zone de défilement de la fenêtre même que nous remplaçons, et rendue à la fermeture de la nôtre.",
    ["The separate glyph button is gone with it. Its only job was to send you to the page that now stands in front of you."] = "Le bouton de glyphes distinct disparaît du même coup. Sa seule tâche était de vous envoyer vers la page qui se trouve désormais devant vous.",
    ["A band under the header carries the activate button and the name of the talent group on screen. Until now switching existed only as a right-click on the small side icons, and nothing announced it."] = "Un bandeau sous l'en-tête porte le bouton d'activation et le nom du groupe de talents affiché. Jusqu'ici la bascule n'existait que sous forme de clic droit sur les petites icônes latérales, et rien ne l'annonçait.",
    ["Form paging"] = "Pagination des formes",
    ["Keep the main bar on its page in every form"] = "Garder la barre principale sur sa page dans toutes les formes",
    ["|cffaaaaaaCat, bear, stealth, stances and Shadowform normally swap the main bar to their own page. Switch this off to keep the bar you built through every form.|r"] = "|cffaaaaaaFélin, ours, camouflage, postures et Forme d'Ombre font normalement basculer la barre principale sur leur propre page. Désactivez ceci pour conserver dans toutes les formes la barre que vous avez composée.|r",
    -- Patch notes 1.52.1
    ["Keep the main bar on its page in every form – Cat, bear, stealth, stances and Shadowform stop swapping action bar 1 to a page of their own"] = "Garder la barre principale sur sa page dans toutes les formes – Félin, ours, camouflage, postures et Forme d'Ombre cessent de basculer la barre d'action 1 sur une page à elles",
    ["The ticker that paints cooldown dimming and range colouring no longer walks switched-off bars. It read and repainted every action bar five times a second, including the ones whose buttons nobody can see, so running two bars cost as much as running all of them."] = "Le minuteur qui dessine l'assombrissement de recharge et la coloration de portée ne parcourt plus les barres désactivées. Il lisait et repeignait chaque barre d'action cinq fois par seconde, y compris celles dont personne ne voit les boutons : deux barres coûtaient donc autant que toutes.",
    ["Leaving a button no longer builds a fresh check each time. The check only ever reads the bar, not the button, so it is built once per bar and shared by all of its buttons."] = "Quitter un bouton ne construit plus une vérification neuve à chaque fois. La vérification ne lit que la barre, pas le bouton, elle est donc construite une seule fois par barre et partagée par tous ses boutons.",
    ["The opponent frames are left alone unless you actually asked for a different arrangement. They are protected frames: anchoring one from our side is allowed outside a fight, but it marks the frame for the rest of the session, and the next time the default interface repositions it during a round its own call is refused and the block is reported against us. There is no way to anchor a protected frame without leaving that mark, so an untouched setup now keeps the default stacking. Order, spacing, grow direction and slot offsets all still work — the message becomes the price of a feature you asked for rather than something every arena hands out for free."] = "Les cadres des adversaires sont laissés tranquilles tant que vous n'avez pas réellement demandé une autre disposition. Ce sont des cadres protégés : en ancrer un depuis notre côté est autorisé hors combat, mais cela marque le cadre pour le reste de la session, et la fois suivante où l'interface par défaut le repositionne en pleine manche, son propre appel est refusé et le blocage nous est imputé. Il n'existe aucun moyen d'ancrer un cadre protégé sans laisser cette marque, donc une configuration intacte conserve désormais l'empilement par défaut. L'ordre, l'espacement, le sens de croissance et les décalages d'emplacement fonctionnent toujours : le message devient le prix d'une fonction demandée plutôt que quelque chose que chaque arène distribue gratuitement.",
    ["Move up and move down work again on a category you switched off and back on. The order list was filled once, while it was still empty, so anything that did not exist at that moment never got an entry, and its arrows then did nothing at all for the rest of the session without saying so."] = "Monter et descendre fonctionnent de nouveau sur une catégorie que vous avez désactivée puis réactivée. La liste d'ordre n'était remplie qu'une fois, tant qu'elle était encore vide ; ce qui n'existait pas à cet instant n'obtenait jamais d'entrée, et ses flèches ne faisaient plus rien du tout pour le reste de la session, sans le dire.",
    ["Switching a module off releases its event handlers again. The note recording which module owns a handler stayed behind when the handler was unregistered, and that note kept a hard reference to every handler the module had ever registered."] = "Désactiver un module libère de nouveau ses gestionnaires d'événements. La note indiquant à quel module appartient un gestionnaire restait en place lors du retrait, et cette note conservait une référence forte vers chaque gestionnaire que le module avait un jour enregistré.",
    -- Patch notes 1.52.2
    ["Casting out of the spell book keeps working after the book was opened from the micro menu. Our micro buttons are stand-ins that hand the click on to the default button behind them, which runs everything that follows inside our own call — and for the spell book that ends in the book writing down which half of itself it is showing. That note then counted as ours, the book reads it on every click on a spell, and so every cast from the book was refused as coming from an addon. Out of combat as well, for the rest of the session, until the interface was reloaded. Opening the book by its key was never affected. The micro menu now carries the default button itself, wearing our icon, so nothing is handed through us any more."] = "Lancer un sort depuis le grimoire fonctionne toujours après avoir ouvert celui-ci depuis le micro-menu. Nos boutons de micro-menu sont des doublures qui transmettent le clic au bouton d'origine placé derrière, si bien que tout ce qui suit s'exécute à l'intérieur de notre propre appel — et pour le grimoire cela se termine par le livre qui note quelle moitié de lui-même il affiche. Cette note comptait alors comme la nôtre, le livre la lit à chaque clic sur un sort, et ainsi chaque incantation depuis le grimoire était refusée comme venant d'un addon. Hors combat également, pour le reste de la session, jusqu'au rechargement de l'interface. Ouvrir le grimoire avec sa touche n'a jamais été concerné. Le micro-menu porte désormais le bouton d'origine lui-même, avec notre icône, si bien que plus rien ne passe par nous.",
    ["Pointing at a bag slot shows the tooltip of the bag itself — quality colour, how much it holds, everything the item carries — with the click hints under it, instead of the bare name. In the inventory window as well as at the bank, which had drifted apart although the two bars are the same thing."] = "Pointer un emplacement de sac affiche l'infobulle du sac lui-même — couleur de qualité, capacité, tout ce que l'objet apporte — avec les indications de clic en dessous, au lieu du seul nom. Dans la fenêtre d'inventaire comme à la banque, qui avaient divergé alors que les deux barres sont la même chose.",
    ["The bar in the inventory window takes bags now, the way the one at the bank already did: drag a bag onto a slot to put it there, or left-click a slot with a bag on the cursor. Right-click with an empty hand takes the bag off again, and left-click with an empty hand still shows and hides it. The backpack and the keyring are not slotted bags, so they accept nothing and are not offered the right-click line in the first place."] = "La barre de la fenêtre d'inventaire accepte les sacs, comme celle de la banque le faisait déjà : faites glisser un sac sur un emplacement pour l'y placer, ou cliquez gauche sur un emplacement avec un sac sur le curseur. Le clic droit à main vide retire le sac, et le clic gauche à main vide continue de l'afficher et de le masquer. Le sac à dos et le trousseau de clés ne sont pas des sacs équipés : ils n'acceptent rien et la ligne du clic droit ne leur est même pas proposée.",
    ["The enchant on the wrist slot sits closer to the rows around it, and the enchant on the weapon sits six pixels lower."] = "L'enchantement de l'emplacement des poignets se rapproche des lignes qui l'entourent, et celui de l'arme descend de six pixels.",
    ["The trainer tab is a button of its own now. It used to be a spare tab of the spell book that we wrote on with every update, and the book reads those tabs back in the middle of its own pass. It also goes away with the pet book, where it used to stay behind."] = "L'onglet du précepteur est désormais un bouton à lui. C'était auparavant un onglet libre du grimoire que nous écrivions à chaque mise à jour, et le livre relit ces onglets au milieu de son propre passage. Il disparaît aussi avec le grimoire du familier, où il restait auparavant.",
    -- Nameplates: aura border + CC size
    ["Match the health bar height"] = "Aligner sur la hauteur de la barre de vie",
    ["The icon becomes a square exactly as tall as the health bar. The three size sliders below step aside while this is on."] = "L'icône devient carrée et exactement aussi haute que la barre de vie. Les trois curseurs de taille en dessous se mettent en retrait tant que ceci est activé.",
    ["Border around aura icons"] = "Bordure autour des icônes d'auras",
    ["The thin rim around debuff, damage-over-time, buff and crowd-control icons. Its thickness follows the border size of the plate."] = "Le fin liseré autour des icônes d'affaiblissements, de dégâts sur la durée, d'améliorations et de contrôle de foule. Son épaisseur suit l'épaisseur de bordure de la plaque.",
    ["Aura border colour"] = "Couleur de la bordure des auras",
    ["Border in the aura's own school colour"] = "Bordure dans la couleur d'école de l'aura",
    ["Magic blue, curse purple, disease orange, poison green — instead of the one colour beside it."] = "Magie bleu, malédiction violet, maladie orange, poison vert — au lieu de l'unique couleur à côté.",
    -- Global settings: settings window scale
    ["Settings Window Scale"] = "Taille de la fenêtre des réglages",
    ["Scales this settings window on its own. The game's interface keeps the size it has."] = "Met à l'échelle uniquement cette fenêtre de réglages. L'interface du jeu garde la taille qu'elle a.",
    -- Patch notes 1.52.3
    ["Match the health bar height – Makes the crowd-control icon a square exactly as tall as the health bar, in place of its own size sliders"] = "Aligner sur la hauteur de la barre de vie – Rend l'icône de contrôle de foule carrée et exactement aussi haute que la barre de vie, à la place de ses propres curseurs de taille",
    ["Border around aura icons – Switches the rim around debuff, damage-over-time, buff and crowd-control icons on or off, with its colour beside it"] = "Bordure autour des icônes d'auras – Active ou désactive le liseré des icônes d'affaiblissements, de dégâts sur la durée, d'améliorations et de contrôle de foule, avec sa couleur à côté",
    ["Text size – Sets how large the unit name and the health value are drawn, in the panel behind each of those two rows"] = "Taille du texte – Définit la taille à laquelle le nom de l'unité et la valeur de vie sont dessinés, dans le panneau derrière chacune de ces deux lignes",
    ["A long unit name is trimmed with three dots instead of running through the health value. The two share the bar as soon as both sit inside it, so the name now gets the width that is actually free — and only a health value at the other end takes room away, because sharing one slot is something you did on purpose. Only a name that would overflow is capped at all, which is what keeps the level number glued to the name instead of hanging off an oversized box."] = "Un nom d'unité trop long est coupé par trois points au lieu de traverser la valeur de vie. Les deux partagent la barre dès qu'ils s'y trouvent tous les deux, si bien que le nom reçoit désormais la largeur réellement libre — et seule une valeur de vie à l'autre bout lui prend de la place, partager un même emplacement étant votre propre choix. Seul un nom qui déborderait est limité, et c'est ce qui garde le niveau collé au nom au lieu de le laisser pendre au bord d'un cadre trop large.",
    ["The aura border can also take the colour of the aura's own school. That switch was read from the start and had no control anywhere."] = "La bordure des auras peut aussi prendre la couleur d'école de l'aura. Cet interrupteur était lu depuis le début et n'avait de commande nulle part.",
    ["Settings Window Scale – Scales this settings window on its own, from 70 to 130 per cent, while the game's interface keeps the size it has"] = "Taille de la fenêtre des réglages – Met à l'échelle uniquement cette fenêtre de réglages, de 70 à 130 pour cent, tandis que l'interface du jeu garde sa taille",
    ["Making the window smaller now gives it back its full size on a screen that was cutting it off. The fitting measured the room in the game's units and the window in its own, so scaling it down changed nothing about what it was allowed to be."] = "Réduire la fenêtre lui rend maintenant sa taille complète sur un écran qui la rognait. L'ajustement mesurait la place dans les unités du jeu et la fenêtre dans les siennes, si bien que la réduire ne changeait rien à ce qu'elle avait le droit d'occuper.",
    -- Nameplates: reverse aura swipe
    ["Reverse the swipe"] = "Inverser le balayage",
    ["The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone."] = "L'ombre revient à mesure que l'aura s'épuise : une icône presque dégagée signifie donc qu'elle est presque terminée.",
    -- Character panel: socket overwrite confirmation
    ["Replace %s with %s? The gem that comes out is destroyed."] = "Remplacer %s par %s ? La gemme retirée est détruite.",
    ["That socket has changed — nothing was socketed."] = "Cette châsse a changé — rien n’a été serti.",
    ["Click to replace the gem — the old one is destroyed."] = "Cliquez pour remplacer la gemme — l’ancienne est détruite.",
    ["Ask before overwriting a gem"] = "Demander avant d’écraser une gemme",
    ["A click on a socket that already holds a gem asks first — putting a gem in destroys the one that comes out."] = "Un clic sur une châsse qui contient déjà une gemme demande d’abord — sertir une gemme détruit celle qui en sort.",
    -- Loadouts: equipping straight out of the bank
    ["%d of them came out of the bank."] = "%d d’entre eux sortaient de la banque.",
    ["in the bank — open the bank window to equip it"] = "à la banque — ouvrez la fenêtre de la banque pour l’équiper",
    -- Patch notes 1.52.4
    ["Ask before overwriting a gem – A click on a socket that already holds a gem asks first, because putting a gem in destroys the one that comes out"] = "Demander avant d’écraser une gemme – Un clic sur une châsse qui contient déjà une gemme demande d’abord, car sertir une gemme détruit celle qui en sort",
    ["Pointing at an occupied socket says what a click on it costs. Clicking one was always allowed, nothing ever said so, and the gem that comes out is destroyed. The question names both gems in their quality colours, and it drops the action when the gear moved while it was standing — otherwise a swap under the open dialog would answer for a socket you never looked at."] = "Pointer une châsse occupée indique ce que coûte un clic dessus. Le clic a toujours été possible, personne ne l’a jamais dit, et la gemme qui en sort est détruite. La question nomme les deux gemmes dans leurs couleurs de qualité et abandonne l’action si l’équipement a bougé pendant qu’elle était ouverte — sinon un changement sous la fenêtre ouverte aurait répondu pour une châsse que vous n’avez jamais regardée.",
    ["Equipping a set at the bank takes the pieces that are lying in the bank, as long as the bank window is open. Until now they counted as missing, so you could stand at the bank and be told the set was not equippable. The message says how many of them came out of the bank, and the piece that comes off goes into the bank slot the new one came from. With the bank closed, a missing piece in there no longer only names its place, it says to open the bank window."] = "Équiper un ensemble à la banque prend les pièces qui se trouvent à la banque, tant que la fenêtre de la banque est ouverte. Jusqu’ici elles comptaient comme manquantes, vous pouviez donc être devant la banque et vous entendre dire que l’ensemble n’était pas équipable. Le message indique combien d’entre elles sortaient de la banque, et la pièce retirée va dans l’emplacement de banque d’où venait la nouvelle. La banque fermée, une pièce manquante qui s’y trouve ne nomme plus seulement son emplacement, elle vous dit d’ouvrir la fenêtre de la banque.",
    ["The line that tells you which sets an item belongs to appears in item tooltips. It was built and hooked up from the start, but it went in through the one tooltip mechanism this client offers and never uses, so no line was ever drawn and nothing complained."] = "La ligne qui indique à quels ensembles appartient un objet apparaît dans les infobulles d’objet. Elle était construite et branchée depuis le début, mais elle passait par le seul mécanisme d’infobulle que ce client propose et n’utilise jamais, si bien qu’aucune ligne n’a jamais été dessinée et que rien ne s’est plaint.",
    ["Reverse the swipe – The shade grows back as the aura runs out, so a nearly clear icon means it is nearly gone"] = "Inverser le balayage – L'ombre revient à mesure que l'aura s'épuise : une icône presque dégagée signifie donc qu'elle est presque terminée",
    ["The cooldown swipe on the aura icons has a control of its own. It was read from the start and could not be changed anywhere."] = "Le balayage de recharge sur les icônes d’aura a son propre réglage. Il était lu depuis le début et ne pouvait être modifié nulle part.",
    ["The raid target marker is visible at all. The eight marks live on one sheet, and the call that picks a tile out of it was working on a frame that never got the sheet — a cut-out of nothing, on every plate and in the preview, since the module was built."] = "Le symbole de raid est visible tout simplement. Les huit symboles tiennent sur une seule planche, et l’appel qui y choisit une case travaillait sur une surface qui n’a jamais reçu la planche — une découpe de rien, sur chaque barre de nom et dans l’aperçu, depuis la construction du module.",
    ["The raid target marker takes one of the six named slots, like the four aura rows. It had three positions of its own and could land on top of a row, which is the very collision the slots exist for. The old choice moves into the matching slot once and then goes, so there is no second control for the same question. Its room is reserved as soon as it is switched on, not only once a unit really carries a mark, so the rows do not jump every time somebody sets a skull."] = "Le symbole de raid occupe l’un des six emplacements nommés, comme les quatre rangées d’auras. Il avait trois positions à lui et pouvait tomber sur une rangée, exactement la collision pour laquelle ces emplacements existent. L’ancien choix passe une fois dans l’emplacement correspondant puis disparaît, afin qu’il n’y ait pas deux réglages pour la même question. Sa place est réservée dès qu’il est activé, et pas seulement quand une unité porte vraiment un symbole, pour que les rangées ne sautent pas chaque fois que quelqu’un pose une tête de mort.",
    ["The marker's own offset and spacing sliders take effect again. They were writing two fields of their own while the plate read the slot, so the visible control was the one without an effect. The old values move across once."] = "Les curseurs de décalage et d’espacement propres au symbole agissent de nouveau. Ils écrivaient dans deux champs à eux pendant que la barre de nom lisait l’emplacement : le réglage visible était donc celui sans effet. Les anciennes valeurs suivent une fois.",
    ["A mark set between two aura passes lands where it belongs. Where the marker goes is worked out in the aura pass, because only that knows how far the rows on its side reach, and the plate now remembers that point for the event that shows the marker on its own."] = "Un symbole posé entre deux passes d’auras arrive là où il doit. La place du symbole est calculée dans la passe d’auras, car elle seule sait jusqu’où vont les rangées de son côté, et la barre de nom retient maintenant ce point pour l’événement qui montre le symbole seul.",
    ["The cast time and the cast target show something in the preview. Both only exist for a cast that is really running on a real unit, so both stayed empty while their switches, colours and side settings stood next to them with nothing to show."] = "Le temps d’incantation et la cible de l’incantation montrent quelque chose dans l’aperçu. Les deux n’existent que pour une incantation réellement en cours sur une unité réelle, ils restaient donc vides tandis que leurs interrupteurs, couleurs et réglages de côté étaient à côté sans rien à montrer.",
    -- Slot picker: the bags moved under an open picker
    ["Your bags moved — pick the item again."] = "Vos sacs ont changé — choisissez l’objet à nouveau.",
    -- Bar setups: load confirmation, imported macros left alone
    ["Load '%s'? Every button on your bars is overwritten or cleared."] = "Charger '%s' ? Chaque bouton de vos barres est écrasé ou vidé.",
    ["Macros: %d restored, %d of your own kept (an import does not rewrite them)."] = "Macros : %d restaurées, %d des vôtres conservées (un import ne les réécrit pas).",
    -- Patch notes 1.52.5
    ["The enchant text of the wrist slot sits under its slot instead of beside it. The wrist is the last slot of the left column, and to the right of it lies the weapon row, which is where the line was writing."] = "Le texte d'enchantement des bracelets s'affiche sous son emplacement au lieu d'à côté. Les bracelets sont le dernier emplacement de la colonne de gauche, et à leur droite se trouve la rangée des armes, là même où la ligne s'écrivait.",
    ["Search field in the enchanting window – Leaves only the recipes whose name or reagents match what you type"] = "Champ de recherche dans la fenêtre d'enchantement – Ne laisse que les recettes dont le nom ou les composants correspondent à ce que vous tapez",
    ["The enchanting window is the one profession window that never had a search box. The field sits between the title and the slot dropdown: type into it and only the recipes whose name or one of their reagents matches stay, with the scroll bar shortening along with the list instead of leaving empty rows under the last hit. Recipes you starred still float to the top of what is left, and closing the window clears the text — otherwise the next visit would open on a list with most of the recipes missing and nothing on screen to explain it."] = "La fenêtre d'enchantement est la seule fenêtre de métier qui n'a jamais eu de champ de recherche. Il se place entre le titre et le menu des emplacements : tapez-y et seules restent les recettes dont le nom ou l'un des composants correspond, la barre de défilement se raccourcissant avec la liste au lieu de laisser des lignes vides sous le dernier résultat. Les recettes marquées d'une étoile remontent toujours en tête de ce qu'il reste, et la fermeture de la fenêtre efface le texte ; sinon la visite suivante s'ouvrirait sur une liste amputée de la plupart des recettes, sans rien à l'écran pour l'expliquer.",
    -- Patch notes 1.52.5
    ["Diminishing returns and interrupts recognise every rank of a spell. Both lists carried one identifier per spell, usually the one for rank one, so what is really cast at level seventy fell through: no icon for the polymorph, no bar for the kick. All ranks share their name, and the client knows the name behind every identifier already in the list, so one pass builds a name index that covers every rank at once, in the client's own language, which is the one the combat log speaks."] = "Les réductions dégressives et les interruptions reconnaissent tous les rangs d'un sort. Les deux listes ne portaient qu'un identifiant par sort, le plus souvent celui du rang un, si bien que ce qui est réellement lancé au niveau soixante-dix passait à travers : pas d'icône pour la métamorphose, pas de barre pour le coup de pied. Tous les rangs partagent leur nom, et le client connaît le nom de chaque identifiant déjà présent dans la liste ; un passage en construit donc un index de noms qui couvre tous les rangs d'un coup, dans la langue du client, celle-là même que parle le journal de combat.",
    ["Loading a setup asks first. It sets a hundred and twenty slots and empties the ones the setup has nothing for, and a single click in the dropdown was enough. The only warning, for a setup belonging to another class, was a chat line that arrived after the damage was done."] = "Charger une configuration demande confirmation. Elle place cent vingt emplacements et vide ceux pour lesquels elle n'a rien, et un simple clic dans le menu suffisait. Le seul avertissement, pour une configuration d'une autre classe, était une ligne de discussion qui arrivait après les dégâts.",
    ["Importing a setup leaves your own macros and keybindings alone. Macros are matched by name, and a name like Pull belongs to everyone, so a foreign setup replaced the contents of your own macro of that name with the switch on by default and without a word about it. Imported setups are marked as foreign now and keep what is already there, and the message says how many were kept. A backup entry carrying no keys at all no longer gets restored either, which used to clear the keys of that command and save the result."] = "Importer une configuration laisse vos propres macros et raccourcis tranquilles. Les macros sont appariées par leur nom, et un nom comme Pull appartient à tout le monde : une configuration étrangère remplaçait donc le contenu de votre macro homonyme, avec l'option activée par défaut et sans un mot. Les configurations importées sont désormais marquées comme étrangères et laissent en place ce qui existe déjà, et le message indique combien ont été conservées. Une entrée de sauvegarde sans aucune touche n'est plus restaurée non plus, ce qui effaçait jusqu'ici les touches de cette commande et enregistrait le résultat.",
    ["The enchant text of a weapon sits above its slot. Beside a weapon there is the next weapon, and to the left the whole text column, so the line had nowhere to go; above the weapon row the paper doll is empty. It is centred over its own slot and wraps upward, so two enchanted weapons no longer write across each other."] = "Le texte d'enchantement d'une arme se place au-dessus de son emplacement. À côté d'une arme il y a l'arme suivante, et à gauche toute la colonne de texte : la ligne n'avait nulle part où aller, alors qu'au-dessus de la rangée des armes le mannequin est vide. Elle est centrée sur son propre emplacement et se replie vers le haut, de sorte que deux armes enchantées ne s'écrivent plus l'une par-dessus l'autre.",
    ["The question before overwriting a gem is only armed once the dialog is really standing. If one was already open the client reuses it, and rebuilding it cleared the note that had just been made, so the second question answered nothing at all and said nothing about it. The recheck now compares the item as well, and an open window on its own no longer counts as proof that it is the right one."] = "La question posée avant d'écraser une gemme ne s'arme qu'une fois la boîte de dialogue réellement affichée. S'il y en avait déjà une d'ouverte, le client la réutilise, et la reconstruire effaçait la note qui venait d'être prise : la deuxième question ne répondait donc à rien, sans le dire. La contre-vérification compare désormais aussi l'objet, et une fenêtre ouverte ne suffit plus à prouver que c'est la bonne.",
    ["The item level of a piece the client has not cached yet appears once it arrives. The retry ran into the very gate that had excluded it and drew nothing, ever. It is capped at twenty attempts per item so it cannot turn into a loop that runs every tenth of a second."] = "Le niveau d'objet d'une pièce que le client n'a pas encore mise en cache apparaît dès qu'il arrive. La nouvelle tentative retombait dans la porte même qui l'avait exclue et ne dessinait jamais rien. Elle est désormais plafonnée à vingt essais par objet, pour ne pas devenir une boucle toutes les dixièmes de seconde.",
    ["Deleting an entry removes the one you clicked. It went by the position the row was built with, and the list is rewritten behind the open page whenever the trinket matching adds or removes entries after an equipment change, so the neighbour disappeared instead."] = "Supprimer une entrée retire bien celle sur laquelle vous avez cliqué. L'opération passait par la position avec laquelle la ligne avait été construite, or la liste est réécrite derrière la page ouverte dès que l'appariement des bijoux ajoute ou retire des entrées après un changement d'équipement : c'était donc la voisine qui disparaissait.",
    ["Logging in no longer opens the edit mode behind your back. Restoring frame positions used to apply the layout by showing the client's own edit mode manager, and that rebuilds every system the editor owns out of our call stack, which hands them to the addon for the rest of the session. Measured in game: one such call three seconds after login, and twenty seconds later 1593 refused actions in combat, party and raid frames among them. The layout is still written, and the client applies it the next time it does so itself. A frame you drag by hand still settles immediately."] = "La connexion n'ouvre plus le mode édition dans votre dos. La restauration des positions appliquait la disposition en affichant le gestionnaire de mode édition du client, lequel reconstruit chaque système appartenant à l'éditeur depuis notre pile d'appels, ce qui les remet à l'addon pour le reste de la session. Mesuré en jeu : un tel appel trois secondes après la connexion, et vingt secondes plus tard 1593 actions refusées en combat, cadres de groupe et de raid compris. La disposition est toujours enregistrée, et le client l'applique la prochaine fois qu'il le fait de lui-même. Un cadre déplacé à la main se pose toujours immédiatement.",
    ["A frame dropped after a fight has started keeps the spot you dropped it at. A drag can only begin out of combat but it can end in one, and letting go wrote the anchor onto a protected frame without asking. The position was already saved by then, so the saved value and the frame on screen would have disagreed for the rest of the session. The write now waits for the fight to end and is made good afterwards."] = "Un cadre relâché après le début d'un combat reste là où vous l'avez posé. Un déplacement ne peut commencer qu'hors combat, mais il peut se terminer en plein combat, et le relâchement écrivait l'ancrage sur un cadre protégé sans rien demander. La position était déjà enregistrée à ce moment-là : la valeur enregistrée et le cadre à l'écran se seraient donc contredits pour le reste de la session. L'écriture attend maintenant la fin du combat et est rattrapée ensuite.",
    ["The client settings the fishing mode borrows survive a crash. The backup of your own values lived in memory only, so a reload, a disconnect or a crash while fishing mode was running took it along, and music, ambience, auto loot and soft targeting stayed on the fishing values for good with nothing left anywhere to say what they had been."] = "Les réglages du client que le mode pêche emprunte survivent à un plantage. La sauvegarde de vos propres valeurs ne vivait qu'en mémoire : un rechargement, une déconnexion ou un plantage pendant le mode pêche l'emportait avec lui, et musique, ambiance, ramassage automatique et ciblage doux restaient définitivement sur les valeurs de pêche, sans que rien nulle part ne dise ce qu'il y avait avant.",
    ["Switching the camera zoom option off returns the zoom to the client's default. The comment promised as much and the code did nothing of the sort, so with the option already on from an earlier session there was no value of ours to fall back to and the maximum stayed for every session after. It is only reset while the value still is our maximum, so anything you have set yourself since then stays."] = "Désactiver l'option de zoom de caméra ramène le zoom à la valeur par défaut du client. Le commentaire le promettait, le code n'en faisait rien, et si l'option était déjà active depuis une session antérieure, aucune valeur à nous n'était disponible : le maximum restait pour toutes les sessions suivantes. La remise à zéro n'a lieu que tant que la valeur est encore notre maximum, donc tout ce que vous avez réglé vous-même depuis reste en place.",
    ["Unit tooltips no longer throw a Lua error on a unit without an identifier. The fallback one line above did the arithmetic on the missing identifier itself and handed the result to the very call that cannot take it."] = "Les infobulles d'unité ne provoquent plus d'erreur Lua sur une unité sans identifiant. Le repli de la ligne précédente faisait lui-même le calcul avec l'identifiant manquant et transmettait le résultat à l'appel même qui ne peut pas l'accepter.",
    ["A set finds its own piece when two items share an identifier, the way the owl's ring and the bear's ring do. Sets store the full reference but searched by the bare identifier; the search goes by identifier and suffix now, while enchants and gems stay out of it because those change during an item's life and would make a set report its own piece as missing."] = "Un ensemble retrouve sa propre pièce quand deux objets partagent un identifiant, comme l'anneau du hibou et celui de l'ours. Les ensembles enregistrent la référence complète mais cherchaient par l'identifiant nu ; la recherche se fait désormais par identifiant et suffixe, tandis que les enchantements et les gemmes en restent volontairement exclus, car ils changent au cours de la vie d'un objet et feraient déclarer manquante la pièce même de l'ensemble.",
    ["The name comes back after a cast the same way the interrupt flash already decides it. A retired field was still being asked, although the options page says it is read nowhere any more."] = "Le nom revient après un sort de la même façon que l'éclair d'interruption le décide déjà. Un champ mis hors service était encore interrogé, alors que la page d'options indique qu'il n'est plus lu nulle part.",
    ["The click area of a plate returns to its measured size. The value that means the client's own size was only right as long as the setter had never run, so afterwards the old area stood until a reload and the sliders went up without ever coming back."] = "La zone de clic d'une plaque revient à sa taille mesurée. La valeur qui désigne la taille propre du client n'était juste que tant que le setter n'avait jamais tourné ; ensuite l'ancienne zone tenait jusqu'au rechargement et les curseurs montaient sans jamais redescendre.",
    ["An installation from before the schema stamp runs its migrations instead of skipping them. No stamp meant two opposite things, a fresh installation with nothing to migrate or one older than the stamp with everything still pending, and both were stamped current and skipped, so the older one silently lost every migration, its bar setups in their old storage place among them. The two are told apart now by whether there is any module data at all."] = "Une installation antérieure au sceau de schéma exécute ses migrations au lieu de les sauter. L'absence de sceau signifiait deux choses opposées, une installation neuve sans rien à migrer ou une installation plus ancienne que le sceau avec tout en attente, et les deux étaient scellées à jour puis ignorées : la plus ancienne perdait ainsi en silence chaque migration, y compris ses configurations de barres à leur ancien emplacement. Les deux se distinguent maintenant à la présence ou non de données de module.",
    ["The strip for the weapon slots opens downward instead of sideways. The three weapons are the only slots standing in a row rather than a column, at the bottom of the paper doll, where sideways always runs into their own neighbour. It grows away from the middle of the screen so it cannot pass the near edge, and it tips upward when the window sits at the bottom of the screen."] = "La bande des emplacements d'arme se déploie vers le bas au lieu du côté. Les trois armes sont les seuls emplacements disposés en rangée et non en colonne, en bas du mannequin, où le côté tombe toujours sur leur propre voisin. Elle grandit en s'éloignant du centre de l'écran pour ne pas dépasser le bord proche, et bascule vers le haut lorsque la fenêtre est collée au bas de l'écran.",
    ["A click in the picker can no longer hit whatever has moved into that bag slot in the meantime. It remembered bag and slot from the moment it was filled and listened to no bag event, so after a sort run a click hit what was lying there by then, which with a merchant window open would have been a sale. It follows bag changes now, and every click checks the item in place against the one the button was built for."] = "Un clic dans le sélecteur ne peut plus atteindre ce qui a glissé entre-temps dans cet emplacement de sac. Il mémorisait sac et emplacement au moment du remplissage et n'écoutait aucun événement de sac : après un tri, le clic touchait ce qui s'y trouvait alors, ce qui, avec une fenêtre de marchand ouverte, aurait été une vente. Il suit désormais les changements de sac, et chaque clic compare l'objet présent à celui pour lequel le bouton a été construit.",
    ["The merchant lock covers both trinket slots. A mixed-up condition left it applying to the lower one only."] = "Le verrou marchand couvre les deux emplacements de bijou. Une condition inversée ne le laissait s'appliquer qu'au plus bas.",
    ["The addon no longer stamps the client's own health text and target classification with its taint. Both called the client's updaters from our call stack, the very thing the same file forbids two hundred lines further down in writing and with a reason, which makes the client's next pass over those frames unsafe. Both write what they need themselves now. The standard border returns the moment the client next classifies your target."] = "L'addon ne marque plus de sa souillure le texte de vie ni la classification de cible du client. Les deux appelaient les routines du client depuis notre pile d'appels, précisément ce que le même fichier interdit deux cents lignes plus bas, noir sur blanc et avec sa raison, et ce qui rend le passage suivant du client sur ces cadres non sûr. Chacun écrit désormais lui-même ce dont il a besoin. La bordure standard revient dès que le client classe votre cible la fois suivante.",
    ["|cffff7777What it costs, and why this is off unless you switch it on: the answer has to sit on a name the client's own protected code reads, which hands the party and raid frames to this addon for the rest of the session. In combat they then refuse to resize and name this addon while doing it. Switching it back off stops it happening again but does not undo the session it already happened in - that takes a reload.|r"] = "|cffff7777Ce que cela coûte, et pourquoi c'est désactivé tant que vous ne l'activez pas : la réponse doit se trouver sur un nom que le code protégé du client lit lui-même, ce qui confie les cadres de groupe et de raid à cet addon pour le reste de la session. En combat, ils refusent alors de se redimensionner en nommant cet addon. Le redésactiver empêche seulement que cela se reproduise, cela n'annule pas la session où c'est déjà arrivé : il faut recharger pour cela.|r",
    ["not applied - this client does reject the call, so the error is firing"] = "non appliqué : ce client refuse bien l'appel, l'erreur se produit donc",
    -- Patch notes 1.52.6
    ["X Offset / Y Offset – Nudge the stack and reagent numbers away from their chosen corner; both sit behind the gear of the position row"] = "Décalage X / Décalage Y – Éloigne les nombres de piles et de composants de leur coin choisi ; les deux se trouvent derrière l'engrenage de la ligne de position",
    ["Opening Edit Mode no longer hands the party and raid frames to the addon for the rest of the session. Merely opening it drove the client's frame editor through the addon, and in combat the client then refused to update those frames, naming the addon in the message. Only really moving one of Blizzard's frames still writes to the editor, and a frame that is hidden, like the focus frame while nothing is focused, never does."] = "Ouvrir le mode édition ne remet plus les cadres de groupe et de raid à l'addon pour le reste de la session. Le simple fait de l'ouvrir faisait passer l'éditeur de cadres du client par l'addon, et en combat le client refusait ensuite de mettre à jour ces cadres, en nommant l'addon dans le message. Seul le déplacement réel d'un cadre de Blizzard écrit encore dans l'éditeur, et un cadre masqué, comme le cadre de focalisation sans focalisation, ne le fait jamais.",
    ["Opening Edit Mode closes the options window. It sat exactly on top of the boxes it had just unlocked."] = "Ouvrir le mode édition ferme la fenêtre d'options. Elle se plaçait exactement sur les cases qu'elle venait de déverrouiller.",
    ["The equipment list steps aside for the rune engraving panel. That panel opens on the right side of the character sheet, exactly where the list docks, so the two stood on top of each other. The list now follows the panel's edge, and where the screen is too narrow for sheet, panel and list together, it moves to the left side of the sheet."] = "La liste d'équipement s'écarte du panneau de gravure de runes. Ce panneau s'ouvre à droite de la feuille de personnage, exactement là où la liste s'amarre, si bien que les deux se superposaient. La liste suit désormais le bord du panneau et, là où l'écran est trop étroit pour la feuille, le panneau et la liste réunis, elle passe à gauche de la feuille.",
    ["The role fix ships switched off. What it fixes is a silent error that truncates one update when a nameplate appears; what it costs is that the party and raid frames count as touched by the addon for the whole session and refuse to resize in combat, with the addon named in the message. That price was reaching players who never chose it, so now only whoever switches the fix on pays it."] = "Le correctif de rôle est livré désactivé. Ce qu'il corrige est une erreur silencieuse qui tronque une mise à jour à l'apparition d'une plaque ; ce qu'il coûte, c'est que les cadres de groupe et de raid comptent comme touchés par l'addon pour toute la session et refusent de se redimensionner en combat, avec l'addon nommé dans le message. Ce prix, des joueurs qui ne l'avaient jamais choisi le payaient ; désormais seul le paie qui active le correctif.",
    ["The status line of the role fix tells the whole truth. With the fix off it used to claim it was not needed on this client, even for players who do have the error; it now says whether the fix is applied, not needed, or simply not switched on while the error is firing."] = "La ligne d'état du correctif de rôle dit toute la vérité. Correctif désactivé, elle affirmait qu'il n'était pas nécessaire sur ce client, même pour les joueurs qui ont bel et bien l'erreur ; elle dit maintenant si le correctif est appliqué, inutile, ou simplement pas activé alors que l'erreur se produit.",
    ["The bar ships switched off. A second resource bar is a strong opinion to hand someone who never asked for one, and the client already draws its own. Installations that already exist keep the bar exactly as it was."] = "La barre est livrée désactivée. Une deuxième barre de ressource est une opinion forte à imposer à qui n'a rien demandé, et le client dessine déjà la sienne. Les installations existantes gardent la barre exactement comme elle était.",
    ["The dark skin keeps Blizzard's rim off the stance buttons for good. Their updates write the button art back directly, past the hook that guards the action bars, so the rim used to return the first time you switched."] = "L'habillage sombre garde la bordure de Blizzard loin des boutons de forme, définitivement. Leurs mises à jour réécrivent directement l'art du bouton, en passant à côté du crochet qui protège les barres d'action, si bien que la bordure revenait au premier changement.",
    ["Bonus"] = "Bonus",
