    ["Shadow (darkened Blizzard border)"] = "Ombre (bordure Blizzard assombrie)",
    ["Standard (Blizzard's own look)"] = "Standard (apparence d'origine de Blizzard)",
    ["Pick how the action buttons look: Blizzard's own untouched button, the dark Shadow skin, or a masked shape (circle, square, hexagon)."] = "Choisissez l'apparence des boutons d'action : le bouton d'origine de Blizzard, l'habillage sombre Ombre ou une forme masquée (cercle, carré, hexagone).",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): Blizzard's own look, the dark Shadow skin, or masked shapes.|r"] = "|cff9b6cffLe style de bordure et d'icône des boutons se règle dans le module Habillage sombre (Barres d'action → Style de barre) : l'apparence d'origine de Blizzard, l'habillage sombre Ombre ou des formes masquées.|r",
    ["Circle (masked shape)"] = "Cercle (forme masquée)",
    ["Square (masked shape)"] = "Carré (forme masquée)",
    ["Hexagon (masked shape)"] = "Hexagone (forme masquée)",
    ["WeakAuras style"] = "Style WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Style des icônes WeakAuras, indépendant des barres d'action.",
    ["Shadow 1"] = "Shadow 1",
    ["Shadow 2"] = "Shadow 2",
    ["Shadow 3"] = "Shadow 3",
    ["Shadow 4"] = "Shadow 4",
    ["Shadow 5"] = "Shadow 5",
    ["Border color"] = "Couleur de la bordure",
    ["Tints the frame of the Shadow and shape styles. Reset it to get each style's built-in coloring back."] = "Teinte le cadre des styles Ombre et des formes. Réinitialisez pour retrouver la couleur d'origine de chaque style.",
    ["Tints the border layer of the aura sets. Reset it to get each set's built-in coloring back."] = "Teinte la couche de bordure des ensembles d'auras. Réinitialisez pour retrouver la couleur d'origine de chaque ensemble.",
    ["Spell lists"] = "Listes de sorts",
    ["Edit spell lists"] = "Modifier les listes de sorts",
    ["Always-show and never-show spell IDs for this row."] = "IDs de sorts à toujours afficher ou ne jamais afficher pour cette rangée.",
    ["Always show"] = "Toujours afficher",
    ["Never show"] = "Ne jamais afficher",
    ["Auras on this list always appear in this row, even when its own rules would hide them."] = "Les auras de cette liste apparaissent toujours dans cette rangée, même quand ses propres règles les masqueraient.",
    ["Auras on this list never appear in this row."] = "Les auras de cette liste n'apparaissent jamais dans cette rangée.",
    ["No entries yet."] = "Aucune entrée pour l'instant.",
    ["Unknown spell"] = "Sort inconnu",
    ["Click to switch this entry on or off without deleting it."] = "Cliquez pour activer ou désactiver cette entrée sans la supprimer.",
    ["Mine"] = "Miens",
    ["Any"] = "Tous",
    ["Counts only your own casts - click to count any caster."] = "Seuls vos propres sorts comptent - cliquez pour compter tous les lanceurs.",
    ["Counts any caster - click to count only your own casts."] = "Tous les lanceurs comptent - cliquez pour ne compter que vos propres sorts.",
    ["Low-health glow"] = "Lueur à vie basse",
    ["Lights the plate up once the unit drops below the chosen health percentage."] = "Illumine la plaque dès que l'unité passe sous le pourcentage de vie choisi.",
    ["Thin ring"] = "Anneau fin",
    ["Pulsing glow"] = "Lueur pulsante",
    ["Low-health percent"] = "Pourcentage de vie basse",
    -- Patch notes 1.53.0
    ["Every row of the stats sheet now explains itself when you point at it, and spell haste has joined the sheet."] = "Chaque ligne de la feuille de caractéristiques s'explique d'elle-même quand vous la pointez, et la hâte des sorts a rejoint la feuille.",
    ["Custom class colours moved into the addon's own colour book. Writing them into the client's shared tables marked the party and raid frames as touched by the addon at every login, and the client then refused to resize them in combat. The clean-up has a price: the client's own windows and other addons show the standard class colours again, while the custom ones colour everything this addon draws."] = "Les couleurs de classe personnalisées emménagent dans le livre de couleurs de l'addon. Les écrire dans les tables partagées du client marquait les cadres de groupe et de raid comme touchés par l'addon à chaque connexion, et le client refusait ensuite de les ajuster en combat. Le nettoyage a un prix : les fenêtres du client et les autres addons affichent de nouveau les couleurs de classe standard, tandis que les personnalisées colorent tout ce que cet addon dessine.",
    ["Edit spell lists – Every aura row carries an always-show and a never-show spell ID list, kept in its own editing window behind the slot's fine tuning"] = "Modifier les listes de sorts – Chaque rangée d'auras porte une liste toujours afficher et une liste ne jamais afficher par ID de sort, gérées dans leur propre fenêtre d'édition derrière le réglage fin de l'emplacement",
    ["Low-health glow – Marks plates below a chosen health percentage, as a thin ring or a soft pulsing glow, in a colour of your choice"] = "Lueur à vie basse – Marque les plaques sous un pourcentage de vie choisi, en anneau fin ou en douce lueur pulsante, dans la couleur de votre choix",
    ["The pulsing glow ships as a new texture file, so it takes one full client restart to appear; a reload is not enough."] = "La lueur pulsante arrive sous forme de nouveau fichier de texture : il faut un redémarrage complet du client pour la voir, un rechargement ne suffit pas.",
    ["The seal-twist helper no longer counts a swing ahead on parries or when attacking starts; its window used to point at a swing that never came."] = "L'assistant de changement de sceau ne compte plus un coup d'avance sur les parades ni au début de l'attaque ; sa fenêtre pointait vers un coup qui ne venait jamais.",
    ["The import preview no longer sits on top of the paste step of the import dialog."] = "L'aperçu d'importation ne se pose plus sur l'étape de collage du dialogue d'importation.",
    ["The clock keeps ticking through abilities that replace the swing, Heroic Strike and Cleave among them: they write their own combat log line instead of a swing line, so the bar used to stand still exactly for the classes that queue such an ability on every swing."] = "L'horloge continue de tourner avec les techniques qui remplacent le coup, Frappe héroïque et Enchaînement entre autres : elles écrivent leur propre ligne dans le journal de combat au lieu d'une ligne de coup, si bien que la barre restait figée précisément pour les classes qui posent une telle technique sur chaque coup.",
    ["Swing-resetting spells that deal no damage, parried special attacks and extra attacks now reach the clock too."] = "Les sorts qui réinitialisent le coup sans dégâts, les attaques spéciales parées et les attaques supplémentaires atteignent maintenant l'horloge eux aussi.",
    ["WeakAuras style – A separate icon style for WeakAuras, independent of the action bars, with five Shadow aura sets"] = "Style WeakAuras – Un style d'icônes à part pour WeakAuras, indépendant des barres d'action, avec cinq jeux d'auras Shadow",
    ["Border color – Tints the frame of the Shadow and shape styles; resetting it restores each style's built-in colouring"] = "Couleur de la bordure – Teinte le cadre des styles Shadow et des formes ; la réinitialiser rend à chaque style sa coloration intégrée",
    ["The bar style now starts at Blizzard's own untouched look, and the masked shapes circle, square and hexagon bring their own frames."] = "Le style de barres démarre désormais sur l'apparence intacte de Blizzard, et les formes masquées cercle, carré et hexagone apportent leurs propres cadres.",
    -- Action Ring
    ["%d of %d entries"] = "%d entrées sur %d",
