    ["Add new ring"] = "Ajouter un nouvel anneau",
    ["All %d rings are in use."] = "Les %d anneaux sont tous utilisés.",
    ["An extra key that closes the ring without using anything. ESCAPE always works."] = "Une touche supplémentaire qui ferme l'anneau sans rien utiliser. ESCAPE fonctionne toujours.",
    ["Arc width"] = "Largeur de l'arc",
    ["At the cursor"] = "Au curseur",
    ["Bind or change the key that opens this ring."] = "Assigne ou modifie la touche qui ouvre cet anneau.",
