    ["Grey out unusable entries"] = "Griser les entrées inutilisables",
    ["Hold a keybind to open a ring of actions around the cursor; aim at an entry and release to use it."] = "Maintenez un raccourci pour ouvrir un anneau d'actions autour du curseur ; visez une entrée et relâchez pour l'utiliser.",
    ["Horizontal offset"] = "Décalage horizontal",
