    ["Opens this ring without a key press. It closes by itself after a while, or press the button again."] = "Ouvre cet anneau sans appui sur une touche. Il se ferme de lui-même après un moment, ou appuyez de nouveau sur le bouton.",
    ["Press a key... (ESC to cancel)"] = "Appuyez sur une touche... (ESC pour annuler)",
