    ["Spells"] = "Sorts",
    ["The key that uses the aimed entry while the ring is kept open. Without it the ring falls back to hold-and-release."] = "La touche qui utilise l'entrée visée lorsque l'anneau reste ouvert. Sans elle, l'anneau revient au mode maintenir-et-relâcher.",
    ["The ring grows on its own when entries would overlap; this is the smallest size."] = "L'anneau s'agrandit de lui-même lorsque les entrées se chevaucheraient ; c'est la taille minimale.",
    ["The ring stays open after the key is released. Aim and press the select key to use an entry; ESCAPE or the ring's key closes it."] = "L'anneau reste ouvert après le relâchement de la touche. Visez et appuyez sur la touche de sélection pour utiliser une entrée ; ESCAPE ou la touche de l'anneau le ferme.",
