    ["Strip direction"] = "Sens de la bande",
    ["Templates are built from what this character has right now."] = "Les modèles sont construits à partir de ce que ce personnage possède actuellement.",
    ["The release fires the entry under the pointer; with this off, the wheel's entry fires."] = "Le relâchement déclenche l'entrée sous le pointeur ; si l'option est désactivée, c'est l'entrée choisie à la molette qui se déclenche.",
    ["The shared settings take this ring's values and every ring's own override is removed."] = "Les réglages partagés adoptent les valeurs de cet anneau et le remplacement propre à chaque anneau est supprimé.",
    ["Theme colour"] = "Couleur du thème",
    ["This ring keeps its own layout and display settings; every other ring follows the shared ones above."] = "Cet anneau conserve ses propres réglages de disposition et d'affichage ; tous les autres anneaux suivent les réglages partagés ci-dessus.",
    ["This ring's own look"] = "Apparence propre à cet anneau",
    ["Unknown spells and missing macros are left out of the ring entirely. The stored entries stay for characters that can use them."] = "Les sorts inconnus et les macros manquantes sont entièrement exclus de l'anneau. Les entrées enregistrées restent pour les personnages qui peuvent les utiliser.",
    ["|cffaaaaaaTurn the override on to give this ring its own settings.|r"] = "|cffaaaaaaActivez le remplacement pour donner à cet anneau ses propres réglages.|r",
    ["Target markers"] = "Marqueurs de cible",
    ["Hearthstone"] = "Pierre de foyer",
    ["Teleports"] = "Téléportations",
    ["Potions"] = "Potions",
    ["Druid forms"] = "Formes de druide",
    ["Stances and auras"] = "Postures et auras",
    ["Quest items"] = "Objets de quête",
    -- Action Ring
    ["Not in combat - keybinds can't be changed while fighting."] = "Pas en combat : les raccourcis ne peuvent pas être modifiés pendant le combat.",
    -- Action Ring
    ["Colour while a swing attack is queued"] = "Colorer tant qu'une attaque est en attente",
    ["While an on-next-swing attack (Heroic Strike, Cleave, Raptor Strike, Maul) is queued, the bar takes this colour - the resource it will eat is already spoken for."] = "Tant qu'une attaque au prochain coup (Frappe héroïque, Enchaînement, Frappe de raptor, Mutiler) est en attente, la barre prend cette couleur : la ressource qu'elle consommera est déjà réservée.",
    ["Queued colour"] = "Couleur d'attente",
    -- Patch notes 1.54.0
    ["Action Ring – Hold a keybind to open a ring of actions, aim at an entry and release to use it, spells, items and macros alike, in and out of combat"] = "Anneau d'actions – Maintenez un raccourci pour ouvrir un anneau d'actions ; visez une entrée et relâchez pour l'utiliser, sorts, objets et macros confondus, en combat comme en dehors",
    ["Choose between a ring, a grid and a mouse-wheel strip, run up to 16 rings with their own keys, entries and look, and start from ready-made templates such as raid marks, teleports, potions or shapeshifts."] = "Au choix : anneau, grille ou bande à la molette, jusqu'à 16 anneaux avec leurs propres touches, entrées et apparence, et des modèles prêts à l'emploi comme les marques de raid, les téléportations, les potions ou les changements de forme.",
    ["The options page shows a live preview of the selected ring that redraws while you drag a slider, and a plus button right in the picture adds entries."] = "La page d'options affiche un aperçu en direct de l'anneau choisi, redessiné pendant que vous faites glisser un curseur, et un bouton plus dans l'image même ajoute des entrées.",
    ["Colour while a swing attack is queued – The resource bar shows a colour of your choice while an on-next-swing attack waits for the hit, so you can see that the resource is already spoken for"] = "Colorer tant qu'une attaque est en attente – La barre de ressource prend une couleur de votre choix tant qu'une attaque au prochain coup attend de partir, pour montrer que cette ressource est déjà réservée",
    ["The low-health glow now reaches further past the plate and rounds its corners more generously; before, it hugged the frame so tightly that it read as a border instead of a glow."] = "La lueur de vie basse dépasse maintenant davantage de la plaque et arrondit ses coins plus généreusement ; avant, elle collait tant au cadre qu'elle passait pour une bordure plutôt que pour une lueur.",
    ["The glow texture changed on disk, so it takes one full client restart to show its new shape; a reload is not enough."] = "La texture de la lueur a changé sur le disque : il faut un redémarrage complet du client pour voir sa nouvelle forme, un rechargement ne suffit pas.",
    ["The bar colour opens a full colour picker instead of a short list of presets; existing profiles keep the colour they had."] = "La couleur de la barre ouvre un vrai sélecteur de couleurs au lieu d'une courte liste de préréglages ; les profils existants gardent leur couleur.",
    ["Bar default"] = "Défaut de la barre",
    ["Edit glows..."] = "Modifier les lueurs...",
    ["Sound when ready"] = "Son quand c'est prêt",
    ["Custom icon..."] = "Icône personnalisée...",
    ["Park this icon (kept, never shown)"] = "Mettre cette icône de côté (conservée, jamais affichée)",
    ["Drag to reorder. Right-click opens this icon's settings."] = "Glissez pour réorganiser. Un clic droit ouvre les réglages de cette icône.",
    ["Drag to reorder. Right-click an icon for its settings."] = "Glissez pour réorganiser. Clic droit sur une icône pour ses réglages.",
    ["Custom icon: enter a spell or item ID, or a texture path. Empty returns the real icon."] = "Icône personnalisée : saisissez l'ID d'un sort ou d'un objet, ou le chemin d'une texture. Vide rétablit l'icône d'origine.",
    ["Switching the module off now hands the micro buttons and the bag buttons back to their exact Blizzard positions, and a dialog offers the reload right away; the addon's row layout used to survive into the default bars until the next reload."] = "En désactivant le module, les micro-boutons et les boutons de sacs retrouvent exactement leurs positions Blizzard, et une boîte de dialogue propose de recharger aussitôt ; auparavant, la disposition en rangée de l'addon survivait dans les barres par défaut jusqu'au rechargement suivant.",
    ["Sound when ready – Every icon can announce the end of its cooldown with a sound from the shared media list, auditioned right in the menu with every click"] = "Son quand c'est prêt – Chaque icône peut annoncer la fin de sa recharge avec un son de la liste des médias partagés, écouté directement dans le menu à chaque clic",
    ["Custom icon... – Any entry can wear an icon of your choice, named by spell or item ID or a texture path"] = "Icône personnalisée... – Chaque entrée peut porter l'icône de votre choix, indiquée par l'ID d'un sort ou d'un objet ou par le chemin d'une texture",
    ["Right-clicking an icon in the preview strip opens a settings menu for that one entry: glow while ready with its own colour, the ready flash, the dimming, the cooldown swipe and the countdown text can each override the bar's setting, and the glow editor, parking and removing live in the same place. Removing is no longer the bare right-click itself, so a stray click cannot shorten the bar."] = "Un clic droit sur une icône de la bande d'aperçu ouvre un menu de réglages pour cette seule entrée : la lueur quand c'est prêt avec sa propre couleur, le flash, l'assombrissement, le balayage de recharge et le texte du compte à rebours peuvent chacun remplacer le réglage de la barre, et l'éditeur de lueurs, la mise de côté et la suppression vivent au même endroit. La suppression n'est plus le simple clic droit, un clic égaré ne peut donc plus raccourcir la barre.",
    ["Long popup menus, the module list on the minimap button among them, now show a window that scrolls with the mouse wheel instead of growing past the screen edge."] = "Les longs menus contextuels, dont la liste des modules du bouton de la minicarte, affichent désormais une fenêtre qui défile à la molette au lieu de dépasser le bord de l'écran.",
    ["Helm"] = "Casque",
    ["Cloak"] = "Cape",
    ["Don't change"] = "Ne pas modifier",
    ["shown"] = "affiché",
    ["hidden"] = "masqué",
    ["Resilience"] = "Résilience",
    ["Reduces the chance to be critically hit and the damage taken from critical strikes."] = "Réduit le risque de subir un coup critique et les dégâts des coups critiques.",
    -- Patch notes 1.56.0
    ["Keeping the main bar on its page in every form now also holds the standard main bar, even while the whole module is off. The keys fire exactly what the buttons show, and switching to bars 2 to 6 by hand still works."] = "Garder la barre principale sur sa page dans toutes les formes tient désormais aussi la barre principale standard, même quand le module entier est désactivé. Les touches déclenchent exactement ce que montrent les boutons, et passer à la main aux barres 2 à 6 fonctionne toujours.",
    ["The stats sheet shows resilience under Defense, with the rating and its percent effect in the tooltip."] = "La feuille de caractéristiques affiche la résilience sous Défense, avec le score et son effet en pourcentage dans l'infobulle.",
    ["The enchant text on the equipment slots no longer falls onto the green armor line of pieces with built-in bonus armor; that line only stands in when no real enchant follows."] = "Le texte d'enchantement des emplacements d'équipement ne tombe plus sur la ligne verte d'armure des pièces à armure bonus intégrée ; cette ligne ne prend le relais que si aucun enchantement réel ne suit.",
    ["Helm / Cloak – Each set can show, hide or leave untouched the helm and the cloak as it is equipped, chosen in the row's right-click menu, and the row tooltip names the choice"] = "Casque / Cape – Chaque ensemble peut montrer, cacher ou laisser tels quels le casque et la cape à l'équipement, au choix dans le menu contextuel de la ligne, et l'infobulle de la ligne nomme le choix",
    ["The set rows can be reordered with the left mouse button held down: a translucent ghost follows the pointer, a line in the accent colour marks where the row will land, and letting go outside the list cancels. Existing sets keep their alphabetical order as the starting point, new ones join at the end."] = "Les lignes d'ensembles se réordonnent en maintenant le bouton gauche de la souris : un fantôme translucide suit le pointeur, une ligne à la couleur d'accent marque où la ligne atterrira, et relâcher hors de la liste annule. Les ensembles existants partent de leur ordre alphabétique, les nouveaux s'ajoutent à la fin.",
    ["The red auto-attack blink sits exactly on the icon in the skinned button styles and is cut to the same shape; it used to be drawn for the standard button art and blinked beside the icon."] = "Le clignotement rouge de l'attaque automatique se pose exactement sur l'icône dans les styles de bouton habillés et est découpé à la même forme ; il était dessiné pour l'habillage standard du bouton et clignotait à côté de l'icône.",
    ["Popup dialogs measure their frame with the font that is really drawn; with long texts the buttons used to hang below the border."] = "Les boîtes de dialogue mesurent leur cadre avec la police réellement dessinée ; sur les textes longs, les boutons pendaient sous la bordure.",
    ["In your bags: %d"] = "Dans les sacs : %d",
    ["In the bank: %d"] = "À la banque : %d",
    ["Item counts in tooltips"] = "Quantités dans les infobulles",
    ["Item tooltips show how many you carry in your bags and how many sit in the bank, as last seen at a banker."] = "Les infobulles d'objet montrent combien vous en portez dans vos sacs et combien sont à la banque, d'après la dernière visite au banquier.",
    ["Fonts"] = "Polices",
    ["Colors"] = "Couleurs",
    ["Module Fonts"] = "Polices par module",
    ["|cffaaaaaaGive single modules their own font; everything else follows the global font. Changes need a /reload.|r"] = "|cffaaaaaaDonnez leur propre police à certains modules ; tout le reste suit la police globale. Les changements demandent un /reload.|r",
    ["Button texts (keybind, macro name, count) and the XP bar text."] = "Textes des boutons (raccourci, nom de macro, quantité) et le texte de la barre d'expérience.",
    ["Name, level, health, cast and aura text on nameplates."] = "Nom, niveau, vie, texte d'incantation et d'auras sur les plaques.",
    ["Duration, stacks and keybind text on the icons, the strip and the resource bar."] = "Texte de durée, de cumuls et de raccourcis sur les icônes, la bande et la barre de ressource.",
    ["Chat messages, the input box and the tab labels, while the chat module uses the addon font."] = "Messages de discussion, la zone de saisie et les étiquettes des onglets, tant que le module de discussion utilise la police de l'addon.",
    ["The stats sheet of the modern character panel."] = "La feuille de caractéristiques de la fenêtre de personnage moderne.",
    ["Requires /reload."] = "Nécessite un /reload.",
    ["Reduces the chance that your attacks are dodged or parried."] = "Réduit la chance que vos attaques soient esquivées ou parées.",
    ["Dodge and parry reduction"] = "Réduction d'esquive et de parade",
    -- Patch notes 1.57.0
    ["Bags & Bank"] = "Sacs et banque",
    ["Item counts in tooltips – Item tooltips show how many you carry in your bags and how many sit in the bank, as last seen at a banker"] = "Quantités dans les infobulles – Les infobulles d'objet montrent combien vous en portez dans vos sacs et combien sont à la banque, d'après la dernière visite au banquier",
    ["The bank mirror is taken on every banker visit now, with the default bank window and with the bags module switched off alike; it used to fill only while the replacement window was on."] = "Le miroir de la banque est relevé à chaque visite au banquier, aussi avec la fenêtre de banque standard et le module de sacs désactivé ; avant, il ne se remplissait que lorsque la fenêtre de remplacement était active.",
    ["The melee section shows expertise the way the game's own sheet does, with both weapons when dual wielding; the tooltip names the dodge and parry reduction in percent along with the rating. Only on clients whose game has the stat."] = "La section de mêlée affiche l'expertise comme la feuille du jeu lui-même, avec les deux armes en ambidextrie ; l'infobulle donne la réduction d'esquive et de parade en pourcentage avec le score. Seulement sur les clients dont le jeu connaît cette valeur.",
    ["Module Fonts – Give single modules their own font: action bars, nameplates, cooldown manager, chat and the stats sheet each take a face of their own, everything else follows the global font"] = "Polices par module – Donnez leur propre police à certains modules : barres d'action, plaques, gestionnaire de temps de recharge, discussion et feuille de caractéristiques prennent chacun leur police, tout le reste suit la police globale",
    ["Fonts and colors live on two separate tabs now; the class and resource colors moved to their own Colors tab unchanged."] = "Les polices et les couleurs occupent désormais deux onglets séparés ; les couleurs de classe et de ressource ont déménagé telles quelles vers leur propre onglet Couleurs.",
    ["An imported look string carries the module fonts along, and the action bar buttons keep the game's own lettering until a module font is chosen for them."] = "Une chaîne d'apparence importée emporte les polices par module, et les boutons des barres d'action gardent l'écriture du jeu tant qu'aucune police de module ne leur est choisie.",
    -- Patch notes 1.57.1
    ["The form-paging section shows up in Standard mode too. The switch itself already reached the standard main bar; the row that flips it was only drawn in Modern mode, so nobody running the standard bars could find it."] = "La section contre le changement de page par forme apparaît désormais aussi en mode standard. L'interrupteur agissait déjà sur la barre principale standard ; sa ligne n'était dessinée qu'en mode moderne, si bien que personne avec les barres standard ne pouvait la trouver.",
    ["Seven hot paths allocate less memory: unit-frame health text, nameplate number formatting and health smoothing, cooldown-manager scan keys, combat-text throttling, bag refreshes, the arena bar-text hook and the reminder pass all reuse what they used to rebuild, so the garbage collector has less to clean up in combat."] = "Sept chemins chauds allouent moins de mémoire : le texte de vie des cadres d'unité, le format des nombres et le lissage de vie des plaques, les clés de balayage du gestionnaire de temps de recharge, le limiteur du texte de combat, le rafraîchissement des sacs, le texte des barres d'arène et la passe des rappels réutilisent ce qu'ils reconstruisaient ; le ramasse-miettes a moins à nettoyer en combat.",
    ["The red auto-attack blink sits on the icon in every button style now, the untouched standard button included. The game defines that blink with retail-sized frame art and a single corner anchor, so on the classic button art it hung past the button to the right and bottom."] = "Le clignotement rouge de l'attaque automatique se pose désormais sur l'icône dans tous les styles de bouton, bouton standard intact compris. Le jeu définit ce clignotement avec un habillage à la taille de Retail et une seule ancre de coin, il dépassait donc à droite et en bas sur l'habillage classique.",
-- Trackbars
["Clock"] = "Horloge",
["Start empty"] = "Commencer à vide",
["An empty bar to build from scratch."] = "Une barre vide à construire de zéro.",
["Top/Bottom info bar"] = "Barre d'informations haut/bas",
["Full-width bar with the classic info blocks."] = "Barre pleine largeur avec les blocs d'informations classiques.",
["Minimap companion"] = "Compagnon de la minicarte",
["Compact clock and FPS readout."] = "Horloge compacte et affichage des FPS.",
["Micro menu strip"] = "Bande du micro-menu",
["Just the micro menu buttons."] = "Seulement les boutons du micro-menu.",
["Bar %d"] = "Barre %d",
["User-built info bars: clock, gold, XP, micro menu and more."] = "Barres d'informations personnalisées : horloge, or, XP, micro-menu et plus encore.",
["Server time"] = "Heure du serveur",
["Local time"] = "Heure locale",
["fps"] = "fps",
["ms"] = "ms",
["Dur"] = "Durée",
["Session earned"] = "Gains de la session",
["Session spent"] = "Dépenses de la session",
["Session profit"] = "Bénéfice de la session",
["+%d more"] = "+%d de plus",
["Total"] = "Total",
["Left-Click: bags -- Ctrl+Right-Click: reset session"] = "Clic gauche : sacs -- Ctrl+Clic droit : réinitialiser la session",
["free"] = "libre",
["Max level (Right-Click: reputation)"] = "Niveau maximum (clic droit : réputation)",
["XP"] = "XP",
["No reputation tracked"] = "Aucune réputation suivie",
["Current"] = "Actuel",
["Rested"] = "Reposé",
["Right-Click: toggle XP / reputation"] = "Clic droit : basculer entre XP et réputation",
["Gap"] = "Écart",
["Use accent color"] = "Utiliser la couleur d'accent",
["Paints this block in the interface accent color instead of the color above."] = "Peint ce bloc dans la couleur d'accent de l'interface au lieu de la couleur ci-dessus.",
["24-hour clock"] = "Horloge 24 heures",
["Show world latency"] = "Afficher la latence monde",
["Show free bag slots"] = "Afficher les emplacements de sac libres",
["Short format (gold only)"] = "Format court (or uniquement)",
["Show coordinates"] = "Afficher les coordonnées",
["|cffaaaaaaBuild your own info bars from blocks: clock, gold, XP, latency, micro menu and more. Create a bar from a template, then stack and order its blocks below.|r"] = "|cffaaaaaaConstruisez vos propres barres d'informations à partir de blocs : horloge, or, XP, latence, micro-menu et plus encore. Créez une barre à partir d'un modèle, puis empilez et ordonnez ses blocs ci-dessous.|r",
["Enable Trackbars"] = "Activer Trackbars",
["Create your first bar"] = "Créez votre première barre",
["|cffaaaaaaPick a template to start with. Every bar stays fully editable afterwards.|r"] = "|cffaaaaaaChoisissez un modèle pour commencer. Chaque barre reste entièrement modifiable par la suite.|r",
["Bar"] = "Barre",
["New bar..."] = "Nouvelle barre...",
["Click again to delete"] = "Cliquez à nouveau pour supprimer",
["Removes the selected bar and all of its blocks."] = "Supprime la barre sélectionnée et tous ses blocs.",
["Bar Settings"] = "Réglages de la barre",
["Length"] = "Longueur",
["Edge"] = "Bord",
["Edge offset"] = "Décalage du bord",
["Stop moving"] = "Arrêter le déplacement",
["Shows the movers so free-standing bars can be dragged into place."] = "Affiche les cadres de déplacement pour glisser les barres autonomes à leur place.",
["Distribution"] = "Répartition",
["Auto sizes each block by its content; even split gives every block the same share of the bar."] = "Auto dimensionne chaque bloc selon son contenu ; répartition égale donne à chaque bloc la même part de la barre.",
["Font scale"] = "Échelle de police",
["Hide border"] = "Masquer la bordure",
["Blocks"] = "Blocs",
["|cffaaaaaaThis bar has no blocks yet -- add one below.|r"] = "|cffaaaaaaCette barre n'a pas encore de blocs -- ajoutez-en un ci-dessous.|r",
["Add block..."] = "Ajouter un bloc...",
["Full width"] = "Pleine largeur",
["Custom length"] = "Longueur personnalisée",
["Even split"] = "Répartition égale",

    -- Patch notes 1.58.0
    ["Trackbars"] = "Trackbars",
    ["Trackbars – Build your own info bars from blocks: clock, gold, XP, latency, micro menu and more"] = "Trackbars – Composez vos propres barres d'informations à partir de blocs : horloge, or, XP, latence, micro-menu et plus",
    ["Bars are created from templates: start empty, a full-width info bar pinned to the top or bottom edge, a compact minimap companion, or a micro menu strip. Every bar stays fully editable afterwards."] = "Les barres se créent à partir de modèles : commencer vide, une barre d'informations pleine largeur épinglée au bord supérieur ou inférieur, un compagnon de minicarte compact ou une barre de micro-menu. Chaque barre reste ensuite entièrement modifiable.",
    ["Ten blocks to stack and order: clock, gold, XP and reputation, FPS, latency, durability, free bag slots, zone with coordinates, micro menu, and a spacer."] = "Dix blocs à empiler et ordonner : horloge, or, XP et réputation, FPS, latence, durabilité, emplacements de sacs libres, zone avec coordonnées, micro-menu et un séparateur.",
    ["The gold block tracks what the current session earned and spent, and its tooltip lists the gold of every character on the account, richest first."] = "Le bloc d'or tient le compte des gains et des dépenses de la session en cours, et son infobulle liste l'or de chaque personnage du compte, les plus riches en premier.",
    ["The XP block renders a real progress bar with the rested bonus overlaid, and a right-click switches it to the tracked reputation."] = "Le bloc d'XP dessine une vraie barre de progression avec le bonus de repos superposé, et un clic droit le bascule vers la réputation suivie.",
    ["The micro menu opens the spellbook, talents and friends through the game's own buttons, so it works safely in combat and never blocks spell casting."] = "Le micro-menu ouvre le grimoire, les talents et les amis via les propres boutons du jeu : il fonctionne donc en toute sécurité en combat et ne bloque jamais l'incantation.",
    ["The module ships disabled: switch it on under HUD in the options window."] = "Le module arrive désactivé : activez-le sous HUD dans la fenêtre d'options.",
-- Resistance verdict
["Resists on average %d%% of matching spell damage against boss enemies."] = "Résiste en moyenne à %d%% des dégâts des sorts correspondants contre les boss.",
["Decent"] = "Correct",
["Good"] = "Bon",
["Very good"] = "Très bon",
["Maximum"] = "Maximum",
    -- Patch notes 1.58.1
    ["The resistance tooltips now rate the value: how much matching spell damage you resist on average against boss enemies, by the game's own formula, plus a colored verdict from Low to Maximum."] = "Les infobulles de résistance évaluent désormais la valeur : quelle part des dégâts des sorts correspondants est résistée en moyenne contre les boss, selon la formule du jeu, avec un verdict coloré de Faible à Maximum.",
    ["Two copies of the same item that differ only in their gems or enchants now swap correctly when switching sets. A regemmed single copy still counts as equipped and is never reported missing. If a set was saved before the gems went in, save it once more while wearing the right copy."] = "Deux exemplaires du même objet qui ne diffèrent que par leurs gemmes ou leur enchantement s'échangent désormais correctement au changement d'ensemble. Un exemplaire unique regemmé compte toujours comme équipé et n'est jamais signalé manquant. Si un ensemble a été enregistré avant la pose des gemmes, réenregistrez-le une fois en portant le bon exemplaire.",
    ["A sweep over thirteen files cuts memory churn and idle work in hot paths: timer texts only rebuild when their value changes, the trinket queue checks once per second instead of every frame, the arena binds its aura events per zone, and the dark skin, bags, tooltips and class trackers reuse what they already computed."] = "Une passe sur treize fichiers réduit le travail mémoire et à vide dans les chemins chauds : les textes de temps ne se reconstruisent qu'au changement de valeur, la file des bijoux vérifie une fois par seconde au lieu de chaque image, l'arène lie ses événements d'auras par zone, et l'habillage sombre, les sacs, les infobulles et les suivis de classe réutilisent ce qui était déjà calculé.",
["Not enough free bag space to unequip everything."] = "Pas assez de place libre dans les sacs pour tout retirer.",
    -- Patch notes 1.58.2
    ["Empty slots are now part of a set: saving records deliberately bare slots, and equipping strips those pieces into the bags, with a single notice when the bags are too full. Sets saved before this change keep their old behavior, so save a set once more to pick up its empty slots."] = "Les emplacements vides font désormais partie de l'ensemble : l'enregistrement note les emplacements volontairement nus, et l'équipement range ces pièces dans les sacs, avec un seul message si les sacs sont trop pleins. Les ensembles enregistrés avant ce changement gardent leur ancien comportement ; réenregistrez un ensemble une fois pour qu'il reprenne ses emplacements vides.",
    ["The unit's level at the name's left edge, coloured by how dangerous it is to you."] = "Le niveau de l'unité au bord gauche du nom, coloré selon le danger qu'elle représente pour vous.",
    ["Elite and rare tag"] = "Étiquette élite et rare",
    ["Adds + for elite, R for rare, R+ for rare elite and B for world bosses. A tagged level turns gold."] = "Ajoute + pour élite, R pour rare, R+ pour élite rare et B pour les boss mondiaux. Un niveau étiqueté devient doré.",
    ["Level text size"] = "Taille du texte du niveau",
    ["0 = uses the name's text size."] = "0 = utilise la taille de texte du nom.",
    ["Where the row extends as more icons arrive. Left and right apply to a horizontal row above or below the plate. Up and down give a vertical column beside the plate a fixed starting end instead of staying centred."] = "Où la rangée s'étend quand d'autres icônes arrivent. Gauche et droite s'appliquent à une rangée horizontale au-dessus ou en dessous de la plaque. Haut et bas donnent à une colonne verticale à côté de la plaque une extrémité de départ fixe au lieu de rester centrée.",
} end)
